INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1001, '子', '一树残花，有枝复茂。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1002, '子', '寄人廊庙，何如自立门户。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1003, '子', '家业消耗，独守为难。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1004, '子', '苦雨连宵，行人为难。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1005, '子', '日照纱窗紫艳明，柳阴枝上报新春。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1006, '子', '家室亨通，心安意稳。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1007, '子', '有意外之虞，含哺而笑。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1008, '子', '得人轻借力，便是运通时。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1009, '子', '卜君之寿，未满六旬。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1010, '子', '时亨运又通，镇日笑春风。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1011, '子', '元贞无咎，固之所宜。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1012, '子', '荣受职任，定在此年。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1013, '子', '半夜西风，晚开雾色。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1014, '子', '斯年头带白，难免孝孤忧。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1015, '子', '为人不实，指东话西。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1016, '子', '正妻无子，副妻有儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1017, '子', '名登痒序，弓马入泮。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1018, '子', '亲近贵人，不有饶益。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1019, '子', '荣任职务，此年大幸。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1020, '子', '运未至时，未可施为。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1021, '子', '乾元用九，动而有成。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1022, '子', '能刚断而往事，决不类流俗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1023, '子', '无端生非，破财难免。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1024, '子', '偏房不结子，正室产麟儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1025, '子', '暖到春回日，百花正及时。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1026, '子', '中流行舟，仔细掌舵。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1027, '子', '平康正直，问利有余。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1028, '子', '名登痒序，身赴儒林。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1029, '子', '日到中天，何期云雾掩其光。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1030, '子', '小运既通，所为稍利顺。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1031, '子', '年当大有，富丽时光。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1032, '子', '生平功名遂，辟雍得荣身。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1033, '子', '路旁之处见山坡，前有长须杖扶。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1034, '子', '不得失却前程在，财散免灾病中苦。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1035, '子', '拖泥带水，征途崎岖。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1036, '子', '母赴瑶池，三年泣血。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1037, '子', '命薄不由人，一世奔波苦劳心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1038, '子', '人和安乐，价值千金。', '[52, 53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1039, '子', '平安年吉，人乐尧天。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1040, '子', '镜中之花，只可对玩。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1041, '子', '人事从容，所为顺利。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1042, '子', '功名成就，国学名香。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1043, '子', '托祖宗之德，初授百总之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1044, '子', '不辛数尽。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1045, '子', '一日元亨，再日利贞。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1046, '子', '命带大凶，妄想无本全利难。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1047, '子', '官拜运司而致任。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1048, '子', '妻生一子，妾亦如之。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1049, '子', '夫妻应偕老，数注半路各分离。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1050, '子', '持弓欲射虎，无奈虎负隅。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1051, '子', '移花接木，艰难培植。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1052, '子', '蛟龙困于渊，未可再施为。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1053, '子', '数有一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1054, '子', '流年运不通，冷落晚风来。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1055, '子', '月到云边，其光掩蔽。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1056, '子', '水流花落，事总难施。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1057, '子', '黄金埋土，未得使用。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1058, '子', '深山有伏蛇，行人须仔细。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1059, '子', '操江之任，立送屈原。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1060, '子', '人有支离，不如守拙。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1061, '子', '一字君记卜之日守。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1062, '子', '李陵误入太后国，高筑云台丰溪忧。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1063, '子', '生子之年。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1064, '子', '束身修德，自无赛难之虞。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1065, '子', '拂度菱花垢，静而光自现。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1066, '子', '和气景象，人有乐意。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1067, '子', '绛帐橘泉名列客，不是儒林即杏林。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1068, '子', '鸟囿于樊笼，神旺而不喜。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1069, '子', '钦命典试。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1070, '子', '高山流水，幸有佳音。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1071, '子', '良骥无差，未受如人之利。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1072, '子', '流年至此，事顺安吉。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1073, '子', '犬生两口，请君详之。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1074, '子', '言公接迟，图之叹惜。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1075, '子', '风云际会功名遂，姓字沾恩雨露深。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1076, '子', '生吝才愚，一毛不拔。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1077, '子', '花柳如絮，春乐宜人。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1078, '子', '行乐度流年，万事得安然。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1079, '子', '湘江游遍，衣食仅足。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1080, '子', '荒江叶乱露初冷，独掉孤舟夜上流。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1081, '子', '婚姻早临，天喜当头。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1082, '子', '先培根本，枝叶畅茂。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1083, '子', '其人品自宏，深怀安乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1084, '子', '风钦通神人共仰，伏遇提携与成家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1085, '子', '清间薄利与微名，做个都市卖卜人。', '[52, 53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1086, '子', '万恨千愁，一朝尽释。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1087, '子', '一日吉利，再日亨通。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1088, '子', '告君记四字：待兔守株。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1089, '子', '草色逢春，始发萌芽。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1090, '子', '流年顾利，何事可为。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1091, '子', '时哉时哉，力图大用。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1092, '子', '耿介独立，名之日辟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1093, '子', '平安二字，亨用之时。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1094, '子', '泰山秃梁木，坏天丧斯文。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1095, '子', '吉人偕同行，牵引无颠陷。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1096, '子', '光天化日，可以勇为。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1097, '子', '大道乐尧天，天佑吉利人。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1098, '子', '恶曜攻身，须防危险。', '[77]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1099, '子', '调倘之才，终须小试。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1100, '子', '人事如愿囊中有，余钱仓中有余粟。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1101, '子', '临渊羡鱼，不如退而结网。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1102, '子', '五彩绳牵月老话，画眉京兆许张郎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1103, '子', '奔走重山，生计他乡可兴发。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1104, '子', '架上有书堪教子，囊中无物不生财。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1105, '子', '只令统指犹未得；相安无事。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1106, '子', '春色侵入，韶光明媚。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1107, '子', '险象横生，大难不死。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1108, '子', '颠沛无常，见闻多闷。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1109, '子', '六十有七，不觉文星矣。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1110, '子', '数定按台宫，至临察御史。', '[87]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1111, '子', '如履虎尾，翼翼小心。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1112, '子', '金匮相扶，喜气频频而至。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1113, '子', '大理为九寺之职，守三章约法之重。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1114, '子', '斯年四个宇，自在安乐。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1115, '子', '关山函谷鸡鸣早，冯缓西秦贺孟堂。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1116, '子', '妻生二子，妾亦如之。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1117, '子', '见机而作，可以无患。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1118, '子', '江边风雨滩头急，钓得鱼来失却钩。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1119, '子', '绿暗红稀春色老，即随流水去不归。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1120, '子', '金章颁北阙，广棘寺深思。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1121, '子', '斯年就有，孝服之忧。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1122, '子', '妻生二子，妾生二儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1123, '子', '子陵钓于富春江，悠然自得。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1124, '子', '六阴之象，事不安宁。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1125, '子', '云连山径，树色模糊。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1126, '子', '父死之年，人子不幸。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1127, '子', '数有偏祜，妻生目。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1128, '子', '数定明刑宫，至大理寺卿。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1129, '子', '鸟得其所，饮啄自如。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1130, '子', '中秋月色，分外光明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1131, '子', '知己论心解，我心傲重喜。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1132, '子', '马遇康庄，可以驰驱。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1133, '子', '命带暗疾，一自不明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1134, '子', '鸦同行，吉凶自分。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1135, '子', '微雨洒暗天，正恼人时候。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1136, '子', '谢安选胜东山，终日饮酒。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1137, '子', '妻生二子，妾生一儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1138, '子', '玉洞桃花，锦绣炫目。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1139, '子', '无兄只一弟，庶母而生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1140, '子', '风散云收，月色千里。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1141, '子', '逆旅穷途，得一知己喜洋洋。', '[4950]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1142, '子', '门中交争，分明破财。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1143, '子', '未能长驱，车脱其轮。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1144, '子', '日落西沉，人在暗中行。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1145, '子', '走过他乡，茫然无处归宿。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1146, '子', '为人多性良，一生无大患。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1147, '子', '圣武恢张四海安，皇恩远庇九州庆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1148, '子', '青春柳眼眉，春光美十分。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1149, '子', '幸得室家欢聚，阴阳有鬼主刑妻。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1150, '子', '夕阳西下，一片彩霞。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1151, '子', '生涯惟有几行书，常伴青毡度岁时。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1152, '子', '好运正当兴，玉出荆山色自明。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1153, '子', '财源恩星，从此而曜。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1154, '子', '事积如麻，且招其祸。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1155, '子', '丰年，衣食饶裕。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1156, '子', '不山不水问渔樵，踪迹无常谓子虚。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1157, '子', '阳春布暖，天气晴明。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1158, '子', '日晨之离，鼓岳而歌。', '[81, 82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1159, '子', '美玉无瑕玷，晴天细雨飞。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1160, '子', '南楼花影度栏杆，寂寞柴门夜色寒。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1161, '子', '托祖宗庇护，甘心守法律。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1162, '子', '蔽日烟尘，行道塞滞。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1163, '子', '盘根错节之时，坚持利器。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1164, '子', '东西南北，处处有逢迎。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1165, '子', '小小经营成家富，微微立业创成基。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1166, '子', '有正已格物之风，笃人臣事君之义。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1167, '子', '花发上林，锦乡夺目。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1168, '子', '披剪荆棘，为力之难。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1169, '子', '谋定无忧，贵人点头。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1170, '子', '耳顺欠二年，椿庭入黄泉。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1171, '子', '蓝关雪拥，马不能前。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1172, '子', '寒窗飞暗雨，万事系人怀。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1173, '子', '鸟栖于树，绿阴正长。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1174, '子', '尘封宝镜，晦滞之中应有份。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1175, '子', '杨花滚雪，北国风光。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1176, '子', '江州司马多情，青衫泪湿沾衣。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1177, '子', '无意之中得意，有意之中失意。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1178, '子', '小往大来，诸吉悉至。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1179, '子', '眼目不明，前生所定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1180, '子', '波纹初定，微风水面劲吹来。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1181, '子', '福兮祸所倚，祸兮福所伏。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1182, '子', '灾星相侵，大小不宁。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1183, '子', '进之未安，退之不可。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1184, '子', '时有寒冷，坚冰未解。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1185, '子', '一叶扁舟载明月，芦花两岸水盈盈。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1186, '子', '内有明谋，幸得贵人解脱。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1187, '子', '扫净风烟光会见，无名带励栋梁材。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1188, '子', '鱼游春水，洋洋而纵。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1189, '子', '母赴瑶池，三年泣血。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1190, '子', '薏苡被谤，可以思瑕。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1191, '子', '舍近求远，劳而无功。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1192, '子', '人面春风，融融乐意。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1193, '子', '太白饮窗下，快乐自足意。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1194, '子', '兄弟三人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1195, '子', '国学名成，光耀其身。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1196, '子', '国学荣身，见于此年。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1197, '子', '海棠初带雨，红泪点栏杆。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1198, '子', '门前榆柳已成，绿映王孙衬马蹄。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1199, '子', '丧门相照，防有哭泣之哀。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1200, '子', '田宅竟相争，兄弟转成仇。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1201, '子', '春水乐流，付之往事。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1202, '子', '杏花深处里，折取一枝来。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1203, '子', '此岁相亲遇贵人，北山猿笑易成人。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1204, '子', '幸得贤郎成鼎志，晚来亨福乐余年。', '[79]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1205, '子', '柳絮初晴，珠帘点雪。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1206, '子', '作事漫停，重云蔽日闷沉沉。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1207, '子', '双生之子，一死一生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1208, '子', '衣食最艰辛，生涯猛浪度青春。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1209, '子', '福履绥之，子孙昌吉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1210, '子', '和风日暖，俄然风起雷声。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1211, '子', '鬼伏床头，飞灾相触。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1212, '子', '一生维绍福且隆，安然享福保其终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1213, '子', '路旁梅花，杨妃之美。', '[18, 19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1214, '子', '南山松柏，岁寒之赠。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1215, '子', '太阳东升，阴气渐消。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1216, '子', '病符相照，势如黄叶迎风。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1217, '子', '赤兔黑鸟，室家有忌。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1218, '子', '忠厚待人，人偏相侮。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1219, '子', '一生近贵，名利皆有。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1220, '子', '数该生子。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1221, '子', '壮志步青云，幼年为寒士。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1222, '子', '行到此年，数已尽矣。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1223, '子', '幽闲无事纳祯祥，几朵梅花扑鼻香。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1224, '子', '知君寿数高，一百还有余。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1225, '子', '喜之未安，忧之又随。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1226, '子', '福自天来事，为求而自合。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1227, '子', '掘井九轫，而不及泉。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1228, '子', '立世刚而好古，一言逆而不容。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1229, '子', '临风回首，揽三叹。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1230, '子', '凶神夹党，居安思危。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1231, '子', '行走有力，凿路可通。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1232, '子', '湘江雁阵，一只先投入网。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1233, '子', '杨柳渐逢春色暖，松柏不怕雪霜寒。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1234, '子', '辛苦经商，途中遇雨贵人扶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1235, '子', '六害三刑命相触，头男长女须防哭。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1236, '子', '少年吉利，中途蹉跎。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1237, '子', '莫游盘盂中，不正自苟合。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1238, '子', '兄在东，弟在西。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1239, '子', '流年顺境，家室胥庆。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1240, '子', '一周无过，流年顺遂。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1241, '子', '月照楼台，怡时行乐。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1242, '子', '临事慷慨，喜气融和。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1243, '子', '行迈靡靡，载驰载驱。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1244, '子', '三党情疏，六亲意绝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1245, '子', '黄花开遍，晚节有荣。', '[85, 86]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1246, '子', '走遍他乡，难逢知己。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1247, '子', '春风入户，棠梨上苔。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1248, '子', '丰年可乐业，穗足断无忧。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1249, '子', '枕席之畔，不测哭来。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1250, '子', '湘江雁阵，二只先伤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1251, '子', '四子送老，皆庶所出。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1252, '子', '贵人指引在重山，重山之外得黄金。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1253, '子', '湘江雁阵，三只先伤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1254, '子', '生涯半世一虚名，奔走徒劳费精神。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1255, '子', '别境鸟啼，益我岑寂。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1256, '子', '腐草之余，复荣之茂。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1257, '子', '湘江雁阵，四只先伤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1258, '子', '抱子挈足，优游而多福。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1259, '子', '其子再来相遇，直遭横祸。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1260, '子', '授任之年。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1261, '子', '催官星拱照，恩自九重来。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1262, '子', '其年运自亨，雨润春花见清明。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1263, '子', '老年生子，人之大幸。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1264, '子', '拥炉围火，暖气熏人。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1265, '子', '此年灾祸，艰难又忧心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1266, '子', '乾龙伟度，奎壁奇姿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1267, '子', '悲似喜，喜似悲。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1268, '子', '寒暖无常，留心动静。', '[85, 86]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1269, '子', '勿以有女见嫌，数中原无子息。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1270, '子', '梦之未醒，尚在颠倒他乡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1271, '子', '一阳初动，梅花几点绽寒头。', '[26, 27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1272, '子', '人事称心，图谋得合。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1273, '子', '乡科及第。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1274, '子', '荣身之年。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1275, '子', '汉子于无声，君子展大成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1276, '子', '湘江雁阵，五只先伤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1277, '子', '贯索相寻，是非有日。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1278, '子', '谋事得合。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1279, '子', '反被小利相缠，终身不得扬眉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1280, '子', '点灯当中，以抓其烟。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1281, '子', '生不逢时，壮士几经挫折。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1282, '子', '陆地行舟，枉费心机。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1283, '子', '一生几成几败，幸余筋骨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1284, '子', '大数已停，一樽美酒送行程。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1285, '子', '五更鸡鸣早，姓字达天聪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1286, '子', '涸泽鮒鱼，涵咏升斗之水。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1287, '子', '室中伏火猪，噬鼠而能焰。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1288, '子', '千里之才，终朝一遇。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1289, '子', '淡然守固，不以得失动心。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1290, '子', '和悦处众，内外皆称。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1291, '子', '流年不宁，父死泪沾襟。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1292, '子', '高山虎威，君子得志之时。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1293, '子', '斯年灾星难免，幸得阴功可保。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1294, '子', '白玉投于泥沙，未得圭璋之选。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1295, '子', '浮云到此，其光渐掩。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1296, '子', '仕途恐有变，举止当谨慎。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1297, '子', '能酒能诗兴最谊，将来事业付儿曹。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1298, '子', '狼狈一生，名利无成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1299, '子', '事业重关锁，进退两无可。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1300, '子', '虽得祖业，中途消耗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1301, '子', '数该生子，天赐老人。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1302, '子', '奴仆成行，前生所生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1303, '子', '其年该破财，官非口舌逼人来。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1304, '子', '非儒又非吏，浪迹为活计。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1305, '子', '恁高之外有惊恐，得个贵人来指导。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1306, '子', '山风转过，尚有岐途。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1307, '子', '踪迹莫蹉跎，攸往可如非。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1308, '子', '奴婢成行，其人有缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1309, '子', '贵人提挟，必成大器。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1310, '子', '孝服之忧，阖门哭也。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1311, '子', '身入宫门，可以谋食。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1312, '子', '朝东暮西，年来辛苦强支持。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1313, '子', '老于鸡夜下，白手费吟哦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1314, '子', '仕途变幻，流年不宁。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1315, '子', '数有五子，送老一枝。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1316, '子', '学多成少，心杂不一。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1317, '子', '大运转生，福来无地。', '[36, 37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1318, '子', '傍贵成家，触贵祸侵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1319, '子', '病符相照，切忌淫灾。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1320, '子', '阳和美景，春色逼人。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1321, '子', '到处交情容易报，春风车马易追求。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1322, '子', '不为梁上君子，定做下小人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1323, '子', '智术能巧，弄巧反成拙。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1324, '子', '羞涩一文钱，巴巴结结度流年。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1325, '子', '文运亨通，其人锦程。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1326, '子', '人情好合，偏于疏处得相亲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1327, '子', '踪迹若浮萍，动止总无定。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1328, '子', '财星到命，数注成家皆兴隆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1329, '子', '一片江帆，千里暮云。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1330, '子', '四岁有灾，饮食慎重。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1331, '子', '终身飘荡恨无家，牛背羊头日转斜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1332, '子', '花开不结子，风雨又相催。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1333, '子', '生不逢时何所为，进退艰难多徘徊。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1334, '子', '动辑有诽谤，不合于斯世。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1335, '子', '天生聪明，过目不忘。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1336, '子', '文章观上国，应知帝座彻金莲。', '[50, 51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1337, '子', '从政孚民，万姓讴歌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1338, '子', '一妻一妾又一妻，三度见佳期。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1339, '子', '根基无定，早年风卷杨花。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1340, '子', '慎之慎之，是非难免。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1341, '子', '禹门雷风动，波浪起龙吟。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1342, '子', '一点灯花报喜来，游人骑马到阳台。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1343, '子', '紫微星照，特开救命之荣。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1344, '子', '头面有亏，前生孽报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1345, '子', '血刃交回，脓疮之灾。', '[90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1346, '子', '云破月生光，还被云遮掩。', '[87, 88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1347, '子', '凶神相见欺，吉神相扶持。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1348, '子', '贵显高门，祖宗遗阴。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1349, '子', '花将开时雨，水炉纵荣而不茂。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1350, '子', '名进黉门，半甘半苦度平生。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1351, '子', '名进黉门，半甘半苦于乡井。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1352, '子', '积多金于子孙，不如积德以延寿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1353, '子', '深谋远虑，多作敢为。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1354, '子', '早丧严慈可奈何，蓼三复泪沱。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1355, '子', '天地罗网，切忌横飞之灾。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1356, '子', '历尽辛苦，六亲骨肉总无缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1357, '子', '龙吟虎啸，大魁天下。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1358, '子', '暮否朝泰，生计无恁。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1359, '子', '庭前芳草正姜姜，一夜风霜花色萎。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1360, '子', '功名蹭蹬，见犬吐气。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1361, '子', '半夜残灯，鬼怪现形。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1362, '子', '一周二岁有关津，病晦相侵有一惊。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1363, '子', '桃子争妍，春风峭寒。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1364, '子', '风折椿枝，三年泣血。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1365, '子', '秦楚不和，兵连祸结。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1366, '子', '''乡科及第。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1367, '子', '周道如砥可，无争挫之虞。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1368, '子', '深山大泽有伏蛇，吩咐行人心仔细。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1369, '子', '终身奔驰，财源耗去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1370, '子', '鸡鸣山谷，接高飞。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1371, '子', '不作生涯不耕田，还从笔里度流年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1372, '子', '花际阳春争秀色，人逢美景益精神。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1373, '子', '际遇蹉跎莫问天，还从笔里度流年。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1374, '子', '薏茨被谤，不可不退。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1375, '子', '三春柳絮，风惨西堂。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1376, '子', '一步一回头，恐有差错事。', '[5960]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1377, '子', '命有三子，得以送终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1378, '子', '家室未有安，两眉正交操。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1379, '子', '祸患不可测，不但人嗔且有鬼。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1380, '子', '妻早子早，人生最妙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1381, '子', '客阻关山，寂莫风雨。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1382, '子', '水年招妻，前生注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1383, '子', '世上难逢百岁人，如今在岁有二春。', '[102]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1384, '子', '雁阵同飞，突然失去五只。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1385, '子', '囊中有物宜收拾，暗有群邪合伴谋。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1386, '子', '人事缓相求，黄河水逆流。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1387, '子', '月转西边五更天，子规啼处不堪闻。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1388, '子', '巩上下两江锁钥，奠东南半壁金汤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1389, '子', '人事纷纷，鹊噪鸦鸣。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1390, '子', '晓烟遮柳，远近朦。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1391, '子', '真假六子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1392, '子', '疾风暴雨，倾墙及室。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1393, '子', '真假五子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1394, '子', '劳劳碌碌流年，已得安闲日又偏。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1395, '子', '山坡曲径处，到处有人家。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1396, '子', '南山风雨过，烦热消除爽气来。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1397, '子', '眉头交蹙眉，心事不足。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1398, '子', '以贡授职，荣禄高迁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1399, '子', '数定三分贵，恩奉九重来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1400, '子', '长途踯躅，朝入燕来暮入秦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1401, '子', '一村又一村，前村未有可停。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1402, '子', '灾星相侵，门庭闹乱。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1403, '子', '筑之东墙，倾之西壁。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1404, '子', '数有偏枯，妻目不明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1405, '子', '思患预防，乃克有济。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1406, '子', '买臣贡薪而行歌，其才干未可试着。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1407, '子', '水穷之处，坐看云生。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1408, '子', '太仓之粟，鼠雀耗之。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1409, '子', '不入泮林，定列辟雍。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1410, '子', '科名显达，定列文扬。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1411, '子', '官非相侵，闭户难禁。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1412, '子', '五湖水顺流，水顺好行舟。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1413, '子', '谋事乖离，东转西驰。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1414, '子', '一门和气霭阳春，祥光拱户几色云。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1415, '子', '数该生子。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1416, '子', '妇性仁慈，助夫益子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1417, '子', '粪土之墙强涂朱，外面光华内里腐。', '[87, 88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1418, '子', '少乐多忧，长处不足。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1419, '子', '祸患逼人，幸人解神。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1420, '子', '桑榆晚景，常享安舒。', '[85, 86]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1421, '子', '一举冠群英，名著当今殊。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1422, '子', '聚散无常，浮云飘荡。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1423, '子', '栏翠金钗十二行，金田良土福无疆。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1424, '子', '徒弟二人，一人送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1425, '子', '沟渠淤港，冲起流通。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1426, '子', '梅花几片苦为情，梦断孤山起土魂。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1427, '子', '入于幽谷，进而倍暗。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1428, '子', '牡丹正当好时节，鹿鸣宴上又簪花。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1429, '子', '傲物气高，顺下逆上。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1430, '子', '数该生子。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1431, '子', '黄菊东篱正色芳，俄然二朵层秋霜。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1432, '子', '晨昏相伴休中道，乐得清闲一位禅。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1433, '子', '枯雨得雨，勃然而兴。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1434, '子', '古稀荣任，天发善人。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1435, '子', '七里滩头一钓翁，几经苦雨几经风。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1436, '子', '荷叶荡荡圆，圆后碎复圆。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1437, '子', '妻子皆早，人生大幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1438, '子', '功允不退，被之戮辱。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1439, '子', '舟在中流，帆桅顺风转悠悠。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1440, '子', '好梦初醒，报喜报晴。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1441, '子', '其人之亡，定在三月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1442, '子', '子规啼血楼，头鼓打三更。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1443, '子', '谋事乖离，东转西驰。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1444, '子', '兄弟十人，数有五贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1445, '子', '一轮红日下西山，远出主人尚未还。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1446, '子', '马首载辔，驰骤千里。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1447, '子', '杨花成阵阵，点点着人衣。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1448, '子', '明月转东楼，朱衣暗点头。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1449, '子', '崎岖已应历，今已见亨通。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1450, '子', '千里暮云路，迢迢莫问津。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1451, '子', '好花枝落，结子篱边。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1452, '子', '命当短促，徒增父母之悲。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1453, '子', '荫祖父基业，不止而守成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1454, '子', '麟儿生下，无刑克之伤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1455, '子', '三径黄花落，渊明解印时。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1456, '子', '黄鸟出谷，已迁乔木。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1457, '子', '懿哉荫泽之博施。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1458, '子', '少年壮而老，总无安闲心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1459, '子', '心性虽急而无毒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1460, '子', '东风入画堂，和气生满室。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1461, '子', '品优性温，事难决断。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1462, '子', '花色更新，春色几时。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1463, '子', '几番雨打柳花球，一阵风吹上舞楼。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1464, '子', '月照楼台，及时行乐。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1465, '子', '愁愁闷闷，多少离人恨。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1466, '子', '性急而雄躁，扶弱而抑强。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1467, '子', '兄弟三人，先损其二。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1468, '子', '日照桑榆，犹足三千里。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1469, '子', '晦气侵入，朦胧度日。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1470, '子', '步步回头，坎坷已过。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1471, '子', '犹之复喜，得意失意。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1472, '子', '少壮而老，发愤无穷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1473, '子', '大数已到，发福无穷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1474, '子', '蓉菊初开，晚霞始落。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1475, '子', '兄弟三人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1476, '子', '家室康宁，流年之庆。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1477, '子', '莫嫌花色淡，黄花晚节香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1478, '子', '柳岸花飞春欲尽，愁人寂寞倚栏杆。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1479, '子', '数至太史官，至修撰东迁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1480, '子', '始舍圉圉，因而未纵。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1481, '子', '既乘其时，可以有为。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1482, '子', '经营湖海，仅值千金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1483, '子', '兄弟四人，三死非命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1484, '子', '欲是高楼未有梯，不能举步上扳。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1485, '子', '路当坦途，可以安步。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1486, '子', '花开尽矣。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1487, '子', '杀重身轻，须延其寿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1488, '子', '妾生三子，妻生一儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1489, '子', '沙边鸥鸟，相依忘仇。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1490, '子', '鸾坡视草官，至侍读荣身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1491, '子', '利见大人，无往不利。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1492, '子', '手中持拮据，争奈不求人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1493, '子', '且将心事付诸虚，纵有强梁不用忧。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1494, '子', '其年有刑，丧骨肉叹凄凉。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1495, '子', '老年丧子，人生不幸。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1496, '子', '东篱黄菊正芬芳，相看白衣送酒归。', '[6768]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1497, '子', '根浅风狂，树将吹倒。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1498, '子', '班师皆相庆，人民诵西平。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1499, '子', '兄弟三人，数奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1500, '子', '枯木逢春，岁月峥嵘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1501, '子', '钦命典试。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1502, '子', '兄弟七人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1503, '子', '道路崎岖，行人不辨东西。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1504, '子', '早运沉淹志未伸，纵然才大也难成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1505, '子', '春花开时锦绣丛，风月晴和人意浓。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1506, '子', '其年孝孤，在眉头。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1507, '子', '鬼伏前途，朝暮仔细。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1508, '子', '梦兆飞鸿，官禄高擢。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1509, '子', '一道恩光下九理，封侯庙堂立奇功。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1510, '子', '扶杖过危桥，心机又恐慌。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1511, '子', '秋庆春常卿，月照庙堂彩。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1512, '子', '麟经第一，凤无只。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1513, '子', '身冒知石，险阴无虞。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1514, '子', '享皇家之乐，济黎庶之忧。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1515, '子', '祖宗之业不守，子孙之基有余。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1516, '子', '杨花扑面，三年泣血守亲帷。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1517, '子', '秩秉三来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1518, '子', '兄弟三人，乐奏几般音。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1519, '子', '天授衡士，归子司命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1520, '子', '老虎无牙，得解得脱。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1521, '子', '妻生一子，妾生一儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1522, '子', '恩难图易，事巧有济。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1523, '子', '权重天关，山高日寺。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1524, '子', '万里晴空，天开眼目。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1525, '子', '落花能结子，无弗又嫌迟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1526, '子', '龙吟苍海，云起飞腾。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1527, '子', '文星守命，官至主侍读荣身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1528, '子', '渡江风正好，欢聚趁潮来。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1529, '子', '流年驳杂是非多.三番四覆。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1530, '子', '到老有精神，黄花晚节新。', '[99100]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1531, '子', '事乖似花枝，零落东风里。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1532, '子', '名利两悠悠，春去又复秋。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1533, '子', '营谋笔墨到公门，熟读萧曹有异名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1534, '子', '课雨占晴茅，檐仅可逍遥。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1535, '子', '可恨灾星不可逃，阴阳度祸相遭。', '[6364]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1536, '子', '不见舟人未有来，大江风雨船难开。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1537, '子', '从容，韶光明媚。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1538, '子', '田园丰阜，家室安宁。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1539, '子', '头生两角，事多差错。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1540, '子', '官至布政，恩照万民。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1541, '子', '武曲照命，弓马入泮。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1542, '子', '凉风吹落叶，飘飘在墙角。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1543, '子', '少年登科第，皇都得意回。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1544, '子', '中馈人亡，未免寂寞。', '[50, 51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1545, '子', '兄弟二人，秦楚干戈。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1546, '子', '谨慎才富，束兵爱民。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1547, '子', '屈子于长沙，时之未遇机。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1548, '子', '雨中荷叶，风到珠落。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1549, '子', '槽中有马宜收拾，一走长征去路遥。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1550, '子', '葭萌飞灰，功名取之如反掌。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1551, '子', '勋齐宗伯皇，风杨孔乐辉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1552, '子', '兄弟三人，数当尽贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1553, '子', '点灯相照，往来大道。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1554, '子', '仁声四达，昭于群生。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1555, '子', '椿庭已折，泣血三年。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1556, '子', '举人授任，爵禄荣迁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1557, '子', '财利有余，事事得意。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1558, '子', '开辟抑提衡之任，一人资秉笔之司。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1559, '子', '兄弟四人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1560, '子', '数有五子，三子送终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1561, '子', '荆棘黄华，勾庐在位。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1562, '子', '西园春老，桃李无颜。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1563, '子', '上下得和同，家门喜气多。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1564, '子', '巴巴急急，争个度日。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1565, '子', '明月照前堤，征夫露湿衣。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1566, '子', '数定天符星，尚主寺卿职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1567, '子', '大限已定，卢衣乐之。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1568, '子', '一轮明月出扶桑，瑞气盈盈出画堂。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1569, '子', '老景安康，身强力健。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1570, '子', '勾索相逢，交争扰害。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1571, '子', '姊妹一人，先损一丁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1572, '子', '将军之箭最难当，此岁身亡。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1573, '子', '富有千钟，更添好景。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1574, '子', '东转西行是山，得遇樵人指路迷。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1575, '子', '婚姻早配，琴琴未离弦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1576, '子', '披麻无情，姑命当顾。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1577, '子', '无荣无辱，斯为多福。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1578, '子', '凉风已近，一解烦焦爽气来。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1579, '子', '数应行使，官至行人之职。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1580, '子', '披胜相侵，晦气无情。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1581, '子', '桐叶初落，秋色已动。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1582, '子', '退思有得，进则有失。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1583, '子', '博古通今，官至有司之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1584, '子', '失尾却晚，群鬼见之而走。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1585, '子', '异路而选照，磨数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1586, '子', '薏苡被谤，仕途有阴抑之非。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1587, '子', '几点寒星，明明复灭。', '[80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1588, '子', '五行无驳杂，一举冠群英。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1589, '子', '久居簪缨之班，益峻梅之望。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1590, '子', '富有千钟，安亨无穷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1591, '子', '觅得金鳞替钓丝，江头月落醉眠时。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1592, '子', '杨花扑面，泣血三年。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1593, '子', '一病相侵，半身晦气。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1594, '子', '方懋服德，天与荣身。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1595, '子', '老来无子，以族子为儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1596, '子', '六害无情，骨肉有刑。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1597, '子', '名进黉宫，弓马入泮。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1598, '子', '数定赞画官至五，府察院内庆荣迁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1599, '子', '父殆于水，欲见无由。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1600, '子', '得外来之财，因而起家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1601, '子', '柳絮摇新绿夹岸，晓烟收挂主平安。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1602, '子', '柳花带雪，满园开放。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1603, '子', '双挂珠绿，洞房花烛。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1604, '子', '数定赞画官至都，府察院内照荣升。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1605, '子', '其人之亡，定在正月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1606, '子', '登高远望，无边景色。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1607, '子', '披发相侵，口舌交争。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1608, '子', '生子之年。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1609, '子', '寿数将满百，竟作天仙客。', '[98]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1610, '子', '凿井得泉，亦能解渴。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1611, '子', '松柏有常青，耐寒岁月稠。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1612, '子', '尊至九重之上，万岁称呼。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1613, '子', '阴蛴不分，晚有景色。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1614, '子', '桃花五千树，锦色若绵绵。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1615, '子', '文运天开，科名高第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1616, '子', '周年应有灾，雾色片云迷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1617, '子', '数有二子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1618, '子', '演武及第。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1619, '子', '兄弟五人，秦楚不盟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1620, '子', '绿荫婆婆丝，行人喘息未安舒。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1621, '子', '鬼怪出世，破财多失。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1622, '子', '数有六子，送老得二。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1623, '子', '高山之调，未遇子期。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1624, '子', '数至赞画官至都，府察院内讨荣衔。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1625, '子', '朝霞布锦，画堂形色。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1626, '子', '三代遗民，不复多见。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1627, '子', '命带刑伤，克夫无子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1628, '子', '门前柳色报芳菲，裘马翩翩踏紫微。', '[52, 53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1629, '子', '缘木求鱼，难得其利。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1630, '子', '数该生子。', '[52, 53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1631, '子', '耳须之年晚景奇，皇都得意在春闹。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1632, '子', '官居都堂，爵高禄厚。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1633, '子', '虽一女子，女中丈夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1634, '子', '大限如何，逍遥门外之欢乐。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1635, '子', '兄弟六人，数有五贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1636, '子', '春风大户来，和气畅人家。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1637, '子', '烟锁池塘柳，阴暗迷人走。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1638, '子', '曲道推车，进退两难。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1639, '子', '宿雨初收，春山润色。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1640, '子', '东风解冰，依旧春色。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1641, '子', '周公流言底，谨慎而退避。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1642, '子', '鱼化为龙，庆云相从。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1643, '子', '警一目玻一足，前生孽报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1644, '子', '枝头惫鸟，可以退避。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1645, '子', '恶曜攻身，当有恶报。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1646, '子', '晚来风紧，花枝披离。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1647, '子', '春酒今朝熟，欣然醒北邻。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1648, '子', '庙堂知重器，宝鼎玉居先。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1649, '子', '芙蓉金菊正秋容，雅淡春生乐意浓。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1650, '子', '兄弟六人，中断离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1651, '子', '疏复反复，命有羊刃。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1652, '子', '溺爱不明，兄弟明争。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1653, '子', '祸侵无常，只闻多闷。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1654, '子', '一年三迁，春风得意。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1655, '子', '此刻生人，金水之年必遇险。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1656, '子', '天官首卿，班列太宰。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1657, '子', '病符星照命，数定获缠绵。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1658, '子', '克宽克明，布仁彰信于兆民。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1659, '子', '柔而无断酿，家门之阴祸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1660, '子', '文昌为八座，名位列中台。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1661, '子', '青灯自守命犯孤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1662, '子', '生子之年。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1663, '子', '妻生一子，妾生二儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1664, '子', '一日不利，再日赛滞。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1665, '子', '简在宸衷，执命铨部。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1666, '子', '明月钓娥，清风洒泪多。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1667, '子', '不必问行藏，老运不安康。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1668, '子', '农业兴隆，运至时通。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1669, '子', '寿比颜回多一旬。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1670, '子', '病符逼人，恍忧惊。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1671, '子', '数难回头，实定一铨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1672, '子', '丧门照命，哭泣之哀。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1673, '子', '宝镜未磨，滞中有明。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1674, '子', '勿以轻舟渡海易，旁人先戒飓风号。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1675, '子', '一卷青囊，普照万家风雨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1676, '子', '黄甲传宣，春奏捷。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1677, '子', '或泣或歌，室中伏祸。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1678, '子', '心忙身劳，只见儿女情长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1679, '子', '姻缘奇配，夫步青云。', '[50, 51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1680, '子', '寒毡冷落几黄昏，风雨潇潇早闭门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1681, '子', '分有嫡母，我生是庶。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1682, '子', '马到鬼坡，前有所阻。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1683, '子', '君子不锁，握有铨曹。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1684, '子', '凉风初楚王台，烦热消除爽气来。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1685, '子', '已知其足，自然无辱。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1686, '子', '眉端不挂烦恼，安舒自如。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1687, '子', '分有嫡母，我生继母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1688, '子', '闭塞其户，四壁有光。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1689, '子', '命照武曲，弓马入泮。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1690, '子', '崇天朝宥密之府，阶元老区楼之任。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1691, '子', '冠裳还是旧冠裳，龙虎相逢姓字香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1692, '子', '人生不幸，老年丧夫。', '[64, 65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1693, '子', '求炎必得，得之必失。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1694, '子', '道洽正治，泽润万民。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1695, '子', '近贵不如近帝好，操心那及道心高。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1696, '子', '若问功名，国学名翔。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1697, '子', '如何塞北独无春，二月中旬草不生。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1698, '子', '阴极一阳，天道还转。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1699, '子', '解印荣归，平安之福。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1700, '子', '官拜巡抚，荣归画堂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1701, '子', '苇杭客可渡，光涌有奔泉。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1702, '子', '不因人依谤，赖有骨肉情。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1703, '子', '锋然守于吝，中无为之时。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1704, '子', '枯木逢春芽特达。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1705, '子', '命主刑夫，应作妾室。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1706, '子', '相如病千金，马际曾佳期。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1707, '子', '吉凶并主。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1708, '子', '兄弟二人，秦楚不同盟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1709, '子', '昔提弹夹食无鱼，今年弹夹出有车。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1710, '子', '外物不可必，听之斯有得。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1711, '子', '大开轩窗，高下八方。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1712, '子', '叠断其路，往来不通。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1713, '子', '反复又反复，或时笑或时哭。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1714, '子', '吞陷与亡神，并力相侵扰。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1715, '子', '海棠沾露，泪洒红襟。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1716, '子', '先生不是等闲人，龙跃于渊屈可伸。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1717, '子', '胆大如天，破家之祸。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1718, '子', '鸟在檐前啼，谋为事事宜。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1719, '子', '高堂椿树正扶苏，不料狂风吹折枝。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1720, '子', '既乘其时，当人其用。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1721, '子', '屡进屡退，事多反覆。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1722, '子', '可恨姻缘不到头，此年应有所担忧。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1723, '子', '玉洞梅花，含笑春风。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1724, '子', '云深峰顶黑，山杂岭头高。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1725, '子', '仕途还有梦，举止当慎重。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1726, '子', '南柯梦入华回，忆昔英雄笑语中。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1727, '子', '时运不通，谋事肘。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1728, '子', '五轮光满至，十月有清寒。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1729, '子', '老蚌生珠，修德报不爽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1730, '子', '天禄有情，纵然官讼害。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1731, '子', '人事有恍惚，朝夕有忧疑。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1732, '子', '身在公门心在道，多逢吉庆少逢凶。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1733, '子', '劳神劳形，仅能糊口。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1734, '子', '扁舟设钓儿，顷刻有招非。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1735, '子', '和悦近人，到处恰心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1736, '子', '运未来时，只好悠悠坚守。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1737, '子', '性急不容多好胜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1738, '子', '风动辟雍，万姓安康。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1739, '子', '补掖行人之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1740, '子', '逸而有始终，延年而获寿。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1741, '子', '灾生不急，晦气缠绵。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1742, '子', '牡丹花开，春园姿容。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1743, '子', '用人不疑，疑人不用。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1744, '子', '温温恭人，维德之基。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1745, '子', '舟在波浪，操着力。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1746, '子', '片帆无恙，长江一夕遇春风。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1747, '子', '惟山崔鬼，马劳偃病。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1748, '子', '花径深秋有苍苔，竹杖相扶仔细来。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1749, '子', '晚烟迷漫，满江风雨。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1750, '子', '秋色藤芜转晚凉，只余黄菊满庭芳。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1751, '子', '燕子含泥春正长，经营费尽枉无功。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1752, '子', '经恩济人，反招其怨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1753, '子', '夕阳古道行，人生正徘徊。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1754, '子', '江流水势涌，且把钓鱼竿。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1755, '子', '马足奔波，车不可行。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1756, '子', '风火烈性，决无成心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1757, '子', '椿庭一病成回首，笑语依稀梦中逢。', '[44, 45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1758, '子', '乘其机会，进取有功。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1759, '子', '牧牛丰草地，可以守之余。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1760, '子', '马至中途，逢坎失足。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1761, '子', '早运淹沉中运通，成家立业自兴隆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1762, '子', '行人指迷津，回头杳无音。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1763, '子', '南轩新雾色，人帘钓鱼机。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1764, '子', '千里蟾光彻夜明，碧空湛湛净无尘。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1765, '子', '泪流满面，愁积腔怀。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1766, '子', '阴山积雪丈，穹空无阳气。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1767, '子', '银灯照复残，掩映照愁怀。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1768, '子', '寿元足矣。', '[90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1769, '子', '官至黄堂，不能高握。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1770, '子', '醉乡深处，鞭乐莫为。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1771, '子', '有酒盈樽，春风一面。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1772, '子', '暖风春回，芳草生机。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1773, '子', '操切太急，祸在萧墙。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1774, '子', '劳苦成家，晚享佳福。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1775, '子', '独行，御侮无人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1776, '子', '守其晓田，庶几无失。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1777, '子', '万花谷中，日接不暇。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1778, '子', '南楼杜鹃，更尽无声。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1779, '子', '真假四子，二子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1780, '子', '几多无了事，只恨一无常。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1781, '子', '傍个贵人得成家，次第分明有好处。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1782, '子', '谋事成而又败，不如守拙为高。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1783, '子', '路中有伏蛇，虽惊而无害。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1784, '子', '送终一子，身带残疾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1785, '子', '兄弟六人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1786, '子', '武陵溪畔有渔塘，指引云衢达仙乡。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1787, '子', '慧苡被谤，难免流言。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1788, '子', '度秦岭关，葛藤缚足。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1789, '子', '朝囊夕，克享成福。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1790, '子', '问名无成，问利不益。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1791, '子', '灾晦缠身，有犯太岁。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1792, '子', '命中多，家业消耗。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1793, '子', '夜色风色繁，寒气正愁人。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1794, '子', '顺风江上好扬帆，不料江头有石滩。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1795, '子', '气顺和悦，宜其家室。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1796, '子', '赋性仁慈，持躬淑慎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1797, '子', '太阳正东升，江山气象新。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1798, '子', '神祖扶庇，登甲钦点一翰林。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1799, '子', '小顺大逆，苟全性命。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1800, '子', '切莫问功名，费心总无成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1801, '子', '性优柔，难以决断。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1802, '子', '据般若姿，然未动。', '[7980]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1803, '子', '时运未至，欲前却后。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1804, '子', '钦选黄堂太守。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1805, '子', '道途正崎岖，行止费踌躇。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1806, '子', '性质高谊何，其命宿孤寒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1807, '子', '心多好胜，恃而凌人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1808, '子', '行舟浅水，却费推移。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1809, '子', '丹桂一枝开，秋风得意回。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1810, '子', '草木逢春，千村雨顺。', '[38, 39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1811, '子', '时逢恩星，富贵之期。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1812, '子', '荡澜轻舟，顺风顺水。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1813, '子', '流年驳杂，烦恼难舒。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1814, '子', '车辙满泥沙，转动多费力。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1815, '子', '夜行舟道，坦然无阻。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1816, '子', '菱荷香处，亭畔披襟。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1817, '子', '不从文武科中出，命有总督一将官。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1818, '子', '烟波渺渺，舟人厌倦。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1819, '子', '灶法荣归，家声大振。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1820, '子', '一阵轻风，南轩爽快。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1821, '子', '平平稳稳，无喜无忧。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1822, '子', '倚楼邀明月，掩映至南轩。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1823, '子', '斗转星移，日出扶桑照曜明。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1824, '子', '家业千金，未可量陶朱堪比。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1825, '子', '不从文武科中出，命在营伍大丈夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1826, '子', '所谋不合，命途多险。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1827, '子', '兄弟十一人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1828, '子', '官居臭司，不能高抬。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1829, '子', '祥光宜见，古曜相扶。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1830, '子', '喜偏房之多娶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1831, '子', '大数已尽，痛切泪涟。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1832, '子', '萧墙之内，暗伏凶神。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1833, '子', '持家之妇，姻缘前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1834, '子', '解组林下，心逸身闲。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1835, '子', '鸟展其翅，乘风南徙。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1836, '子', '有人相欺，囊中有天。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1837, '子', '父死之年。', '[56, 57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1838, '子', '富贵之期，世上仰之。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1839, '子', '布政风威，为人师表。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1840, '子', '上山多费力，有树可扳枝。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1841, '子', '老年丧父，世上难逢。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1842, '子', '虽然妻已死，犹恐晚年孤。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1843, '子', '万里晴空，明月一轮。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1844, '子', '水出芙蓉更新鲜，鸠鸣唤雨色如烟。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1845, '子', '日之夕矣，山阴道上未曾归。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1846, '子', '洞房之喜，定在此年。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1847, '子', '数有不幸，母适他家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1848, '子', '明月上初弦，其光渐渐圆。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1849, '子', '时逢恩星，当贡之期。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1850, '子', '杏蕊未全红，浮云飞去月朦胧。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1851, '子', '恩星照命，一贡成名。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1852, '子', '半吉半凶，一喜一忧。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1853, '子', '行在急流处，其舟有破漏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1854, '子', '一朵名花果出奇，嫉风骤雨又相催。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1855, '子', '梦在颠倒，得人唤醒。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1856, '子', '当贡之期。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1857, '子', '禹门雷风动，波浪起龙吟。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1858, '子', '骨月凋残可奈何，半生穷途半生孤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1859, '子', '舟行浅滩，午潮正落。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1860, '子', '道路有坎坷，行人便仔细。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1861, '子', '勿谓轻舟易行，谁知车折其福。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1862, '子', '月转初旬，缺而渐回。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1863, '子', '龙起飞腾会，飞腾上九天。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1864, '子', '呼之转应，天从人愿。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1865, '子', '文星照命，功名显达。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1866, '子', '暮夜须防疏生人。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1867, '子', '黄花开晚节，翠竹茂松林。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1868, '子', '乡科及第。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1869, '子', '将星照命，威镇三军。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1870, '子', '兄弟四人，中断离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1871, '子', '数有五子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1872, '子', '奔走尘埃前，高低任意行。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1873, '子', '高堂之树正扶苏，不料狂风吹折枝。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1874, '子', '谋之无不利，是畅怀所来。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1875, '子', '入幽谷中，进而倍暗。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1876, '子', '恩星相照，当贡之期。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1877, '子', '风平浪静，恰好行舟。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1878, '子', '意气待人，忌之牛口之下。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1879, '子', '福来佑人，逢凶大吉。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1880, '子', '飞霜落瓦，形影凄然。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1881, '子', '雾色似初晴，东方仿佛明。', '[90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1882, '子', '武场捷报。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1883, '子', '大鹏有健翅，东风便飞升。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1884, '子', '无意栽花卉，山上林锦绣。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1885, '子', '老夫老妻，难免其悲。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1886, '子', '碧水桃花下，红雨点罗襟。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1887, '子', '烟尘蔽日，人物糊涂。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1888, '子', '薰风东来，和气满怀。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1889, '子', '兄弟成群，非一母所生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1890, '子', '得意马蹄，踏遍长安春色。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1891, '子', '操守有方，举止不苟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1892, '子', '百花如锦绣，春色正芳菲。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1893, '子', '梦入南柯境，不必问遐龄。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1894, '子', '有笼罩古今之才，无科甲两榜之荣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1895, '子', '此刻乃得贵妇人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1896, '子', '此年运小，吉凶常寻。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1897, '子', '功名卜有分，还须自厚培。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1898, '子', '两岁而亡，如花不久。', '[2]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1899, '子', '花径阴移，恍惚生恐。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1900, '子', '东边日出西边雨，一朝几度怨无端。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1901, '子', '凄凉苦雨，寂莫愁人。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1902, '子', '乍暗乍明云里月，半开半落雨中花。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1903, '子', '高山嵯峨，无门卜笼。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1904, '子', '天怨人怨阴阳，事不遂谋鬼又缠。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1905, '子', '泪痕未干，镜破残妆。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1906, '子', '爵位方伯之尊，亦是外台极品。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1907, '子', '东西料峭，白云生寒。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1908, '子', '风暖鸟儿碎，日高花影移。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1909, '子', '一夫又一夫，命里犯刑孤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1910, '子', '严父数已尽，难留在画堂。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1911, '子', '图名图利，易可却名而问利。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1912, '子', '一群女行人，一双先伤失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1913, '子', '山高水深，虽有舟车不易行。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1914, '子', '诗书未缘，白首是穷年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1915, '子', '数该生子。', '[30, 31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1916, '子', '财源滚滚来，家室安康在。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1917, '子', '此刻生入，流年有咎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1918, '子', '入林中，鸟雀有恐。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1919, '子', '秋风先有信，丹桂一枝开。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1920, '子', '兄弟十人之外方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1921, '子', '父母拮据而起家，子孙能守其成功。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1922, '子', '身心不快，知已难老。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1923, '子', '房考之年。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1924, '子', '老来有刑伤，父母泪两行。', '[66, 67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1925, '子', '兄弟十二人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1926, '子', '烟光渐起，江山依旧。', '[95, 96]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1927, '子', '徒弟二人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1928, '子', '皇都恩波，赐我一贡。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1929, '子', '数有几妾，死于非命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1930, '子', '吉凶并行。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1931, '子', '恶曜攻身，有犯太岁。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1932, '子', '古稀之年父死矣。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1933, '子', '兄弟六人，数有四贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1934, '子', '星夜平分，更饶物色。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1935, '子', '少年登贡，祖宗庇荫。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1936, '子', '圆月如环用不穷，祸自消除福自隆。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1937, '子', '春光布暖，万物滋荣。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1938, '子', '渠花生水，却脱泥淤。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1939, '子', '作事刻薄，骨肉目侧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1940, '子', '暖风迟日正熙春。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1941, '子', '陇头报消息，春色一枝梅。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1942, '子', '命中一子，如龙如虎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1943, '子', '呼童携行李，不必问东君。', '[64]');
