INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1946, '子', '有妻生活，离缘不相宜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1947, '子', '国学名香。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1948, '子', '疾风又怒电，浊浪卷波平。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1949, '子', '新筆始解，节老便成竿。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1950, '子', '绸缪不少，快意无多。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1951, '子', '皇都得意，一贡成名。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1952, '子', '男女总无缘，到老艰辛不可言。', '[7980]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1953, '子', '偏不如意，多招怨悔。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1954, '子', '芦花明月两悠悠，一点渔灯古渡头。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1955, '子', '若问寿元何日止，六旬加九是归期。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1956, '子', '秋天月色，上下清光。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1957, '子', '风光行处好，云物望中生。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1958, '子', '此刻生人，父亡于木年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1959, '子', '画虎于墙，见者惊而无害。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1960, '子', '兄弟十人，秦楚不同盟。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1961, '子', '寿元七旬，大数已尽。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1962, '子', '暗中行路，无人点火相助。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1963, '子', '小舟水上行，转换一帆风。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1964, '子', '岂是聪明果让人，谋略左右恨无穷。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1965, '子', '兄弟六人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1966, '子', '托祖宗之业，可以守成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1967, '子', '前路崎岖未可行，不如守拙且消停。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1968, '子', '寿元何日止，七旬加五是归期。', '[75]');
