INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1976, '子', '当有三母之称。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1977, '子', '经营千里走，马囊遍黄金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1978, '子', '双目朦胧，前生注定。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1979, '子', '梨花风阵阵，片片白云飞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1980, '子', '两耳虽有竟不听，随人说短与谈长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1981, '子', '其人之亡，定在三月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1982, '子', '寿元何日止，六旬加六是归期。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1983, '子', '淑人君子，其德不回。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1984, '子', '满招损，谦受益。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1985, '子', '命途多赛，家业少聚多散。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1986, '子', '君子豹变，文明之家。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1987, '子', '板桥滑湿，行人有成。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (1988, '子', '小宋应熊黑，二子可得之。', '[27, 28]');
