INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2004, '丑', '人总一名，各出一姓。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2005, '丑', '若能守中正，仅可免灾忧。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2006, '丑', '口舌哓哓，不听为高。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2007, '丑', '戒之有德，安分守命。', '[53, 54]');
