INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2016, '丑', '添新纵喜，生甲可悲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2017, '丑', '泮水之游，芹香可美。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2018, '丑', '先娶未有子，再娶降麟儿。', '[17]');
