INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2077, '丑', '妻命属水生，木年娶妻方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2078, '丑', '皇都之市，金紫如棉。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2079, '丑', '久居芝兰室，而不知其香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2080, '丑', '蜃气楼台，空中望阁自光浑。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2081, '丑', '海阔天空，往来自如。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2082, '丑', '生子之年。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2083, '丑', '听流泉石壁，下水流如怒。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2084, '丑', '官至知县，不为斗米而折腰。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2085, '丑', '命照文昌，大魁天下。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2086, '丑', '守口如瓶嘴，无意之中舌自生。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2087, '丑', '蛟然大旱，沛然雨下。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2088, '丑', '运至时行，吞君获庆。', '[30, 31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2089, '丑', '生有善缘，胎内食素。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2090, '丑', '长河有意，一息千里。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2091, '丑', '雨问晴天，意时行乐。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2092, '丑', '母先故于土年方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2093, '丑', '公正有余为，一方之表率。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2094, '丑', '好成人之事，偏惹事生非。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2095, '丑', '人夜秋志声，愁人离绪恨。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2096, '丑', '命带羊刃，数注五旬配妻。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2097, '丑', '半步颠连未有成，南园种柳北园开。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2098, '丑', '房考之年。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2099, '丑', '父母生于木年终于金年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2100, '丑', '飞雁一只，历过南楼。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2101, '丑', '啾唧哭碌碌，疾病挠相促。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2102, '丑', '龙德星高，灾星并磨。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2103, '丑', '朝三暮四急，忙忙度流年。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2104, '丑', '寒窗相对，正是万难时。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2105, '丑', '银汉相隔，闰房少乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2106, '丑', '闭门自守可无虞。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2107, '丑', '不幸良人先叶世，空余银烛伴黄昏。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2108, '丑', '数注郎官天上客，风吹金带麝阑香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2109, '丑', '其人数尽，定在八月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2110, '丑', '寒犬明月，自费精神。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2111, '丑', '白虎当头有一惊，回头及早把门关。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2112, '丑', '无灾无害，老景安闲。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2113, '丑', '心中有事，难言逢人强为欢。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2114, '丑', '行到水湾处，摇橹舟子呼。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2115, '丑', '闻不闻见不见，暗中须防人放箭。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2116, '丑', '其人之亡，定在八月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2117, '丑', '凤失其凰，难于呈祥。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2118, '丑', '父金命先死于火年，母木命后死于金年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2119, '丑', '诗书纵习步青云，命无科甲两榜荣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2120, '丑', '纵有栋渠，未得工师之选。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2121, '丑', '父母同日生，生也姻缘死也缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2122, '丑', '名登榜首。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2123, '丑', '数注辟雍成名早，椿萱并茂享荣花。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2124, '丑', '反笑伏吟，骨肉相刑。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2125, '丑', '丧门相照，哭泣之哀。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2126, '丑', '母先故于水年，父生于金年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2127, '丑', '母故之年，自叹何恃。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2128, '丑', '内助不相和，狮吼是非多。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2129, '丑', '取此东风候，扁舟渡万山。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2130, '丑', '大生两口，任君详之。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2131, '丑', '人不遂黄金，黄金转遂人。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2132, '丑', '相照有丧门，衣裳白一番。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2133, '丑', '并蒂双莲出，奇哉两朵开。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2134, '丑', '玉衣锦裳，千仓万箱。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2135, '丑', '三场未幸登科甲，一贡承恩可牧民。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2136, '丑', '图得东来缺了西，还是君家运未济。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2137, '丑', '注定步青云，金年中举人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2138, '丑', '终日乾乾，若厉无咎。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2139, '丑', '双亲俱去世，母先辞别父难留。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2140, '丑', '再任黄堂，数皆前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2141, '丑', '补授照磨，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2142, '丑', '穷通得失皆前定，何必怨天又尤人。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2143, '丑', '木年母先终，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2144, '丑', '此时生人，父母不睦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2145, '丑', '官至钦命，知县前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2146, '丑', '窥见室家之好，牢穴隙之情。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2147, '丑', '小车无辙，其何以行。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2148, '丑', '子产三丁，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2149, '丑', '禄马荣花，得阶八座之荣。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2150, '丑', '欣欣向荣，春光明媚。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2151, '丑', '已酉之年，武魁及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2152, '丑', '人事无求，安然自优。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2153, '丑', '恩难图易，四方有济。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2154, '丑', '其人之亡，定在五月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2155, '丑', '太岁当头，灾星不减病相缠。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2156, '丑', '思病不可测，不但人嗔亦有鬼。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2157, '丑', '兄弟四人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2158, '丑', '木年火年，生子无损。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2159, '丑', '陟兴嗟，趋庭之训。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2160, '丑', '福德相扶，官职高位。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2161, '丑', '江山新雨遍，人在锦丝中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2162, '丑', '人春犹是无多日，寒气侵入未及回。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2163, '丑', '母故于木年，父尚春将茂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2164, '丑', '滂沱风紧莫行舟，跃马檀溪到豫州。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2165, '丑', '生结局。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2166, '丑', '兄弟七人，秦楚不同盟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2167, '丑', '破巢之祸。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2168, '丑', '奔走东西未有定，劳劳碌碌不安康。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2169, '丑', '乡科及第。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2170, '丑', '鸿飞冥冥，忙了代人。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2171, '丑', '不利不利，时运未至。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2172, '丑', '金年母先终方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2173, '丑', '贤淑大度，庭训所然。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2174, '丑', '初任百总之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2175, '丑', '经之营之，忙度岁月。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2176, '丑', '丙戌之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2177, '丑', '不正而正，桃花开过艳阳明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2178, '丑', '此数生来格局奇，明经出仕耀门庭。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2179, '丑', '耆硕衙望，龙锡宾筵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2180, '丑', '虎落平源，壮志难舒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2181, '丑', '积得黄金多少，太阳一照渐消磨。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2182, '丑', '嫩蕊霜欺，條然变色。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2183, '丑', '兄弟七人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2184, '丑', '惟盼东君归有期，落花流水两相催。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2185, '丑', '掘井渠泉，不解其渴。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2186, '丑', '多晦多忧，常眉头。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2187, '丑', '中运恢复，正当自立。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2188, '丑', '厌见江南未曾收，朦胧一渡过年速。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2189, '丑', '春深桃节，到处成荫。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2190, '丑', '兄弟九人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2191, '丑', '猛如烈火，偏不让强。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2192, '丑', '细雨薰风，唯解烦气。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2193, '丑', '一点丹青仿得真，能垂不配付名人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2194, '丑', '有士子之职，无甲第之荣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2195, '丑', '补授博士之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2196, '丑', '千里马未逢伯乐，双龙剑难遇张华。', '[32, 33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2197, '丑', '热晦天气，微雨度阴云。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2198, '丑', '旭日升林，同见太阳之象。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2199, '丑', '钦命典试。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2200, '丑', '宝玉发祥光，良马伯乐逢。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2201, '丑', '凿井耕田，先民乐趣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2202, '丑', '愁之复忧，牧羊山坡。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2203, '丑', '帝里风光，三月新春。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2204, '丑', '脱却机关，又当蹉跎。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2205, '丑', '齿德俱尊，宾筵藉重。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2206, '丑', '躁急招悔，不思省悟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2207, '丑', '谢却病来愁水缠，几回不敢向人言。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2208, '丑', '南山爽气欲投，怪鬼持戈正逐人。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2209, '丑', '先男后女，命中注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2210, '丑', '孤鸿带月影披离，南北东西未有依。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2211, '丑', '活计无恁，山高水深。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2212, '丑', '骨月凋残人事难，泪痕洒竹染成斑。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2213, '丑', '童年一二岁，春光满眼浓。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2214, '丑', '春光满面，一腔啾唧自家知。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2215, '丑', '奎星初照，一举拨前茅。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2216, '丑', '惆怅多逆风，操辑费着力。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2217, '丑', '星宫见学，损多益少结一枝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2218, '丑', '燕子双飞绕画堂，春色几度断肝肠。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2219, '丑', '马陷沙中，跃之不起。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2220, '丑', '次第春风上苑红。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2221, '丑', '行人不知，马失其足。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2222, '丑', '秋分交错，水充花落。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2223, '丑', '吟就月中诗，风卷见碧空。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2224, '丑', '天时人事喜相逢，不成之得也成功。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2225, '丑', '其人寿绝，定在七月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2226, '丑', '一年又一年，颠倒不如前。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2227, '丑', '分有嫡母，生母继母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2228, '丑', '挣得家业无恙，身遭心多磨障。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2229, '丑', '有妻若无妻，其实靠首妻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2230, '丑', '池塘拳寸湿，春水漾金麟。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2231, '丑', '求之十九，成之十一。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2232, '丑', '浮云卷尺碧天空，春风融和瑞气祥。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2233, '丑', '颠颠沛沛，怀儿撞碎。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2234, '丑', '好花将开，风雨又来。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2235, '丑', '东西少有忧，云照屋檐头。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2236, '丑', '室家相宜，夫妻乐趣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2237, '丑', '命犯呻吟杀，当有身不遂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2238, '丑', '烦恼无忧，谋来可忧。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2239, '丑', '恍恍惚惚，不但人嗔且有鬼。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2240, '丑', '身姿妩娜，临风之柳。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2241, '丑', '前后有阻，并无安土。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2242, '丑', '牛羊恐破财，未免是非多。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2243, '丑', '爵与齿俱高，有德为达尊。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2244, '丑', '生姿气钟灵出，他日龙门必占先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2245, '丑', '是个朝阳补僧，高山流水出红尘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2246, '丑', '舟车往来，关津有阻。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2247, '丑', '金年水年，父母早去方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2248, '丑', '血盆星临，产死其妻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2249, '丑', '夫妻本是同林鸟，不幸雄者意先飞。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2250, '丑', '壮年劳劳碌碌，成家无安度闲日。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2251, '丑', '人事纠缠，费尽工夫也破钱。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2252, '丑', '兄弟三人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2253, '丑', '月上乱云收，青光照彩楼。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2254, '丑', '福禄频加，享受荣华。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2255, '丑', '七七之年当断弦。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2256, '丑', '满面春风人道好，多少不足自家知。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2257, '丑', '凶神遇解神，灾祸不相侵。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2258, '丑', '道路从征飞暗尘，隔江风雨起秋新。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2259, '丑', '圣门弟子，个个飞腾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2260, '丑', '重山之处问黄金，逐逐泥途有一惊。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2261, '丑', '逐野兽以前，驱失足以陷。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2262, '丑', '快乐秋鸟，高飞见忧。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2263, '丑', '黄昏天气暗，月色渐光明。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2264, '丑', '天赐祯祥纳庆多，花前月下听高歌。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2265, '丑', '岸花红滴露，秋树绿含烟。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2266, '丑', '暗路逢人，南北莫辨。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2267, '丑', '房考之年。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2268, '丑', '事不称心，枉费精神。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2269, '丑', '花开车枝满园红，不料根皮一树浓。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2270, '丑', '命不招祖，自创家园。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2271, '丑', '暗道流萤：一点余光。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2272, '丑', '鹿鸣照耀，天以善人。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2273, '丑', '劝君相助本阴人，迷恋阴人必丧身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2274, '丑', '数有四子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2275, '丑', '数内往来格局高，官扬福显姓名香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2276, '丑', '有酒且高歌，人生有几何。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2277, '丑', '荷花出水，亭亭玉立。', '[16, 17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2278, '丑', '一点浮云掩中天，太阳一现渐渐明。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2279, '丑', '晦气不可争，争必有人侵。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2280, '丑', '半夜浮云掩月，五更云散复明。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2281, '丑', '蝉在柳梢叫，若笑而厌倦。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2282, '丑', '人闲心不闲，有事来相关。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2283, '丑', '春风送暖，除旧迎新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2284, '丑', '衣食有余，少当带疾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2285, '丑', '绿荫之下有婆娑，羊触藩篱奈若何。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2286, '丑', '谋望不何，镜花空开。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2287, '丑', '滚滚财源如水，洋洋家计如春。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2288, '丑', '安享之福，无日不足。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2289, '丑', '灾晦相侵，流年凶星。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2290, '丑', '月宫板丹桂，何乐如仙阁。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2291, '丑', '苍松翠柏耐岁寒。', '[82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2292, '丑', '多福多寿，前世所修。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2293, '丑', '徒弟三人，一人送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2294, '丑', '掘泥砌石，寒暑难堪。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2295, '丑', '板桥滑湿戒人行，前提免被水没身。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2296, '丑', '室中安乐，天意从人。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2297, '丑', '数中十子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2298, '丑', '南山虎啸长风，得取休祥之庆。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2299, '丑', '马足迟迟，幸被颠晦。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2300, '丑', '生母当属虎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2301, '丑', '身闲无事，安休之庆。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2302, '丑', '人有刑伤，愁锁眉头泪几行。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2303, '丑', '年逢百外有二春，忧然无事往西行。', '[102]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2304, '丑', '亲把兵权，威镇三军。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2305, '丑', '山风遇虎豹，朝暮当谨慎。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2306, '丑', '十几年庚滞，小试终不利。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2307, '丑', '一天星斗甚光明，东西云生夜不分。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2308, '丑', '紫微聚三台，三场捷报来。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2309, '丑', '兄弟七人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2310, '丑', '数有十人，送老八人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2311, '丑', '汲水烹茶，清闲之福。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2312, '丑', '奇术游天下，未遇知己人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2313, '丑', '万斛之舟起便风，飘然飞渡过江东。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2314, '丑', '数该生子。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2315, '丑', '斗柄已移数已改，喜气频频送过来。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2316, '丑', '寻个优优致，咏笑傲乾坤。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2317, '丑', '行断江头渺茫茫，行人欲渡意仿徨。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2318, '丑', '征帆顺水，瞬息千里。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2319, '丑', '长歌春酒，乐以忘忧。', '[91]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2320, '丑', '兄弟十一人，中断借离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2321, '丑', '萱花椿树萎何时，他日父先母后逝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2322, '丑', '祸患不可测，不但人嗔且有鬼。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2323, '丑', '终身飘泊未有依，明月飞来未有栖。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2324, '丑', '大作怪主，人当有灾。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2325, '丑', '黄金久掩在泥沙，有日开藏世共夸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2326, '丑', '数该生子，谁道蚌珠老。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2327, '丑', '明月中末，文人之盛。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2328, '丑', '据于藜，且招耻辱。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2329, '丑', '四壁有灾，寒虫飞出。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2330, '丑', '人无姊妹，苦不堪言。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2331, '丑', '陇头消息报春来，点缀梅花次第开。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2332, '丑', '持家有法，必专大权。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2333, '丑', '得意之中还得意，财源之上发财源。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2334, '丑', '兄弟十一人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2335, '丑', '半夜飞霜彻夜寒，园中百草必有殃。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2336, '丑', '衣锦藏珠，家门欢趣。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2337, '丑', '名登黄甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2338, '丑', '渐沥秋声，悲衰何堪。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2339, '丑', '姊妹六人，数有不爽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2340, '丑', '前程亨通安泰，朝阳正上三竿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2341, '丑', '兄弟二人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2342, '丑', '流年坎坷，多少蹉跎。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2343, '丑', '洞庭月色近中秋，好暗佳人可邀游。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2344, '丑', '几番风雨好，依旧花鲜明。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2345, '丑', '夏天风嘉鼓吹，或时笑或时哭。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2346, '丑', '图圖之中有忧疑，金马徒劳有所思。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2347, '丑', '代婿经营，贤能莫及。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2348, '丑', '真假六人，逆老三枝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2349, '丑', '时有指南车，攸往无不利。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2350, '丑', '壮年劳劳碌碌，老年成家无安闲。', '[80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2351, '丑', '斯年无小利，不若且消停。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2352, '丑', '骏马交驰，不能安逸。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2353, '丑', '一江风雨暗，平地起波涛。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2354, '丑', '奇谋奇策千般遂，于万贯金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2355, '丑', '观池得水时，则龙鱼变化。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2356, '丑', '贵人指引，前程利就名成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2357, '丑', '炎气薰人，凉风自至。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2358, '丑', '优闲皆无事，不必羡神仙。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2359, '丑', '桂兰香里自含胎。', '[87, 88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2360, '丑', '花边宝马跃金鞍，剪剪轻风阵阵寒。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2361, '丑', '流星殒落，应乎其凶。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2362, '丑', '宝鼎起青烟，线线行行薰翠袖。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2363, '丑', '妻生木火之子，妾生水火之儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2364, '丑', '命多印绶，两外翁姑。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2365, '丑', '足高楼，更上一层。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2366, '丑', '谋事无成，马头烟雨。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2367, '丑', '井中水涸，汲者兴嗟。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2368, '丑', '灾晦陡至不自知，幽魂早已入黄泉。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2369, '丑', '梧落金井运，秋风起日愁。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2370, '丑', '姊妹四人，二人早亡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2371, '丑', '兄弟三人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2372, '丑', '圆月到五更生魄，其光渐减成昏昏。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2373, '丑', '萱草有刑，孝服相侵。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2374, '丑', '山高石倾，行人有惊。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2375, '丑', '名销利关最缚人，长亭云暗掩风尘。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2376, '丑', '车马并集，门庭热闹。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2377, '丑', '其手拘挛，前生果报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2378, '丑', '驾鹤乘云去，飘然竟不归。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2379, '丑', '此刻读诗书，土年应入学。', '[7]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2380, '丑', '中夜起舞，乐也何如。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2381, '丑', '劫杀凶人，家室有害。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2382, '丑', '寒窗苦读书，终生为世用。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2383, '丑', '白玉藏废土，琢玉放光豪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2384, '丑', '花落鸟啼，指深惆怅。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2385, '丑', '初配不终老，半道而别离。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2386, '丑', '病余痨疾症，因花露沾衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2387, '丑', '无忧季子运不前，欢针遂意后十年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2388, '丑', '作事不成功，奇谋反成拙。', '[38, 39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2389, '丑', '将星天定，三军司令。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2390, '丑', '苍天赐我一青无，寂寞寒窗又十年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2391, '丑', '玉笛之声，反成落梅之曲。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2392, '丑', '妻配鸡命，可免其刑。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2393, '丑', '休嗟行路难，虎笑入渡关。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2394, '丑', '安常处顺，猿啼余闷。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2395, '丑', '夫命属水，配夫年属木。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2396, '丑', '一领青，得却防失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2397, '丑', '一霄风雨，梧桐凋谢。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2398, '丑', '作是反成非，奇谋反成拙。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2399, '丑', '天罗地网，昏昏暗中有灾厄。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2400, '丑', '人事变错，虎头蛇尾。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2401, '丑', '迷离烟雨生滩头，今日晴明同上钩。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2402, '丑', '病符相照，灾意外来。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2403, '丑', '收成一子属木，凡遇金水终当去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2404, '丑', '马乘其，车行千里。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2405, '丑', '万顷波涛驾巨舟，吞天沐日过江头。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2406, '丑', '疏灯夜雨，一隙之光。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2407, '丑', '执鞭之士，我独为之。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2408, '丑', '吹落黄花弄笛声，愁人听后思难禁。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2409, '丑', '暖日薰人，门前色新。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2410, '丑', '自知力少，勿谓任重。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2411, '丑', '故有相与日，慷慨自无究。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2412, '丑', '寒虫苦唧唧，助人之叹息。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2413, '丑', '洋洋喜庆如春至，滚滚财源似水流。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2414, '丑', '兄弟八人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2415, '丑', '衡门之下可栖迟，今日徒劳狂费思。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2416, '丑', '猛虎怒威，人见有忌。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2417, '丑', '祖业守成兴复发，财源有分去还来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2418, '丑', '始生木命，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2419, '丑', '景物阳和，胜赏甚多。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2420, '丑', '此年名利双收。', '[50, 51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2421, '丑', '得近帝王之身。', '[52, 53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2422, '丑', '名登黄甲。', '[66, 67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2423, '丑', '花逢春景千般艳，月到中秋分外明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2424, '丑', '离乡别井，创立成家。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2425, '丑', '根基似浮萍，水面随风转。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2426, '丑', '前妻金水之子，后妻土木之儿。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2427, '丑', '演武及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2428, '丑', '一轮明月高，阴气渐消磨。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2429, '丑', '无忧运未通，转行遇顺风。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2430, '丑', '和气乖离，因小致大。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2431, '丑', '问名未成，问利有益。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2432, '丑', '此刻注定读书人，得时便可上青云。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2433, '丑', '际遇得周全，牛背横吹过得村。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2434, '丑', '酉戌二科，武举联捷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2435, '丑', '暗里飞箭来，须防有个伤。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2436, '丑', '五方鬼现，兔走鸟飞。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2437, '丑', '风飘万点正愁人，又见春来春色新。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2438, '丑', '入山樵童喜，得地又得时。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2439, '丑', '晚景安康，可乐余年。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2440, '丑', '月有圆缺，人有离别。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2441, '丑', '反复蹉跎，即是宰仙可奈何。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2442, '丑', '家室吉庆，大小咸宜。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2443, '丑', '前为社稷之臣，今为林下之客。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2444, '丑', '一线如丝，结乱如麻。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2445, '丑', '欲上高楼未有梯，不能举走莫能扶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2446, '丑', '此刻注定贵人基，木年水年夫得贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2447, '丑', '其年有刑伤，骨肉伤凄凉。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2448, '丑', '灾之未已，伤之有失。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2449, '丑', '就之出自无穷，寻之见而可喜。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2450, '丑', '山前山后皆明月，江北江南总是春。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2451, '丑', '扁舟江风挂帆来，千里程途顷刻回。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2452, '丑', '入泮之喜，少年得意。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2453, '丑', '此刻定明经，金年初步木年成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2454, '丑', '禄马往来，常多庆吉。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2455, '丑', '凭高远望，东指西顾。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2456, '丑', '一颗明珠夜有光，主人会袭夜行藏。', '[85, 86]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2457, '丑', '兄弟三人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2458, '丑', '归来之外，非亲非戚。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2459, '丑', '鸟困于樊笼，神喜而不旺。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2460, '丑', '天台迷路，渔郎问津。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2461, '丑', '一天风雨任黄昏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2462, '丑', '枕边之人曾见忧，半年床足半年头。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2463, '丑', '幼年失母，继母相依。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2464, '丑', '应尽崎岖道路遥，登山涉水恨无桥。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2465, '丑', '乡科及第。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2466, '丑', '好个春光，偏恨妒风嫉雨。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2467, '丑', '事欲速反，坚守乃得。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2468, '丑', '晴天忽有暗云生，募地雷鸣恐一惊。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2469, '丑', '冤仇相报，贵人解救。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2470, '丑', '可恨灾星不可逃，阴阳度祸相招。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2471, '丑', '数有五子，一子送终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2472, '丑', '其人之亡，定在八月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2473, '丑', '两妻已死料，三妻上午而亡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2474, '丑', '杏花生艳，雨露初晴。', '[42, 43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2475, '丑', '堪嗟姊妹缘分浅，数中纵有也分离。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2476, '丑', '万事成空。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2477, '丑', '丈夫得志日，方逐男志时。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2478, '丑', '中流多风雨，操辑费着力。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2479, '丑', '再养浩然之气，且加克已之功。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2480, '丑', '招风惹柳，曾作出墙红杏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2481, '丑', '线财人手难为得，破耗忧愁不可言。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2482, '丑', '数有十二男，送老二子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2483, '丑', '夫妻本是同林鸟，不幸雄者竟先飞。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2484, '丑', '山下过时逢猛虎，不伤人身也惊人。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2485, '丑', '花枝凋零怕东风，秋雨吹残满地中。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2486, '丑', '生木火年，终于金水年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2487, '丑', '中年生子，莫嫌迟。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2488, '丑', '东黄菊，桂绽秋香。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2489, '丑', '有酒盈樽，及时行乐。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2490, '丑', '暗中行路迷，途有流萤引。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2491, '丑', '父母同年生同年死。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2492, '丑', '兄弟三人，数注前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2493, '丑', '灾晦缠身，眉头愁未开颜。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2494, '丑', '草木零落月秋，一阳初动水痕收。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2495, '丑', '老来得子，双喜临门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2496, '丑', '深山迷路，樵童指引东西。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2497, '丑', '好运催人，吉利相从。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2498, '丑', '几点疏星落，南楼见太阳。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2499, '丑', '再升巡府。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2500, '丑', '朝三暮四，苦心度日。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2501, '丑', '数该生子。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2502, '丑', '行人得中，邑人之咎。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2503, '丑', '为人丰姿俊雅气，轩昂行藏谨慎事。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2504, '丑', '胸藏绵绣腹蕴珠，文进黄贾学周程。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2505, '丑', '坐于暗定，幸有流萤之光。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2506, '丑', '江上早潮，因风相送。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2507, '丑', '此刻受二妻，土命金年娶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2508, '丑', '高飞促征雁，千里带霜回。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2509, '丑', '迟日桃源春正浓，莺啼燕语媚流香。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2510, '丑', '闺中调雅乐，彻幽人之致。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2511, '丑', '春风若到，春色依旧满皇州。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2512, '丑', '读尽诗书命不宜，宛然拙守托相知。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2513, '丑', '前妻生木水之子，后妻生金火之儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2514, '丑', '相安无事日，屋漏鬼欺人。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2515, '丑', '良霄有酒无人赏，空余红烛伴黄昏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2516, '丑', '凛冽虎帐似春风，一片浮云在碧空。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2517, '丑', '有商贾之望，无功名之分。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2518, '丑', '一庭红紫斗芳菲，昨夜西风吹折枝。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2519, '丑', '有梯有板，高楼直上不难。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2520, '丑', '靖固四方，无疆场之患。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2521, '丑', '进退有所制，若惊又若恐。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2522, '丑', '三番四覆自家知，根长东来叶落西。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2523, '丑', '将星照命，武举可必。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2524, '丑', '一胎二子，数中不爽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2525, '丑', '居安思危，思则有备。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2526, '丑', '苍蝇有翅翼，风起飞腾不远来。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2527, '丑', '岁聿已云暮，惟愿一阳生。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2528, '丑', '数中生七子，二子送老。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2529, '丑', '心之劳竭，做事不成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2530, '丑', '正妻木年已克，次妻火年娶方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2531, '丑', '劳劳为苦读，学而时习之。', '[16, 17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2532, '丑', '太岁当头，不测自来。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2533, '丑', '寂寞相如病茂陵，卢医再出便回生。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2534, '丑', '跨著赛驴，蹈道途。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2535, '丑', '栖移三转，一枝可栖。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2536, '丑', '落日微风动，帘开引燕来。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2537, '丑', '横赋诗，虽武而娴雅儒术。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2538, '丑', '双双燕侣两分飞，不想夫君命不归。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2539, '丑', '星斗乱鸦啼，处处见朦胧。', '[5960]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2540, '丑', '鱼跃于渊。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2541, '丑', '柳外莺嘀闹落花，兰房寂寞日西斜。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2542, '丑', '天性豁达良知敏，气质清纯礼义通。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2543, '丑', '和风雨日时时乐，进喜添财事事通。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2544, '丑', '武曲当头，弓马入泮。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2545, '丑', '厨下火起，灾及室人。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2546, '丑', '一掷千金浑身胆，家徒四壁不知贫。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2547, '丑', '云开雨雾，万里光华。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2548, '丑', '进甚难退甚易，乾乾而夕惕。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2549, '丑', '生得多雅丽，益子荣夫发家起。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2550, '丑', '罢却人爵修天爵，治国不如齐家高。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2551, '丑', '无边红紫，大地阳春。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2552, '丑', '荆棘塞道路，莫问津。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2553, '丑', '三年换东风，律转换荣华。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2554, '丑', '风雨暴至，长途泥滑。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2555, '丑', '冰清玉洁实堪夸，益子荣夫发大家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2556, '丑', '德重乡党允，称学门大耆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2557, '丑', '阡陌田园百亩桑，三公不换此风光。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2558, '丑', '门前喜鹊噪，喜事逐门来。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2559, '丑', '名列庠序，弓马入泮。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2560, '丑', '兄弟九人，秦楚不同盟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2561, '丑', '凶相欺吉，神皆拥护。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2562, '丑', '与人无求，快然自乐。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2563, '丑', '克勤克俭，利有攸往。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2564, '丑', '若迫若缓，徘徊不前。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2565, '丑', '渔舟一叶半江中，饮酒相看乐意浓。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2566, '丑', '名进宫墙，弓马入泮。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2567, '丑', '鬼神无情，灾毒不息。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2568, '丑', '复西又复东，踪迹若飘蓬。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2569, '丑', '名高先歌唱，秋风赴宴鸣。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2570, '丑', '日照样光簇锦纹，高歌白雪与阳春。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2571, '丑', '牡丹花开早，双双产白眉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2572, '丑', '剪发延宾能内助，断机教子早登科。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2573, '丑', '咬牙切齿虚，在人生之忧。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2574, '丑', '一片丹心，报孝社稷。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2575, '丑', '一愿惟知匡社稷，无如年来古稀时。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2576, '丑', '一树梅花破玉开，风吹几点是妆点。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2577, '丑', '婚姻多议禄，不合招极迟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2578, '丑', '挣挫度桥来，前境已半陷。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2579, '丑', '醉而不醒，昏昏沉沉度日过。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2580, '丑', '霏霏细雨逐轻尘，阳台关上送行人。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2581, '丑', '叔夜无心，被孙登之消。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2582, '丑', '有妻似无妻，娶妻靠有妻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2583, '丑', '风吹浮萍，随波上下。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2584, '丑', '负调之才：终须小试。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2585, '丑', '春光度草，庭前遍绿荫。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2586, '丑', '日夜迎宾宴客回，犬吠主人心有悔。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2587, '丑', '雁行无伴，挺卓自持。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2588, '丑', '尘埋镜露光，不与用时同。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2589, '丑', '命有偏才，偏房必要。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2590, '丑', '真假三子，二子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2591, '丑', '奔驰千里路，登高而伫足。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2592, '丑', '消闲无事，安享其福。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2593, '丑', '细雨并无逾，征夫怪夜驱。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2594, '丑', '阳和明景，事业更新。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2595, '丑', '行过山兮水又兮，相看前陌有长堤。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2596, '丑', '崎岖交变，处置诚难。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2597, '丑', '未行而先止，脚收其益知。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2598, '丑', '牡丹初发，其根已萎。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2599, '丑', '发财可喜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2600, '丑', '好树枝疏覆绿阴，行人至此漫消停。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2601, '丑', '三春花节，半在风雨中。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2602, '丑', '风吹白玉梅花飞，骚人相约叩柴扉。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2603, '丑', '和气洋溢，事皆相宜。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2604, '丑', '兄弟八人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2605, '丑', '虽日三时休苦，其实耕稼为先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2606, '丑', '身居烟火地，愁暑不愁人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2607, '丑', '画堂终夜烛生花，药彩光摇透绛纱。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2608, '丑', '名登黄甲。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2609, '丑', '长江虽有浪，一苇渡行人。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2610, '丑', '收养一子实属金，总然土木难成人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2611, '丑', '命带文昌，正当入泮。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2612, '丑', '四人位导二，耕读君为先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2613, '丑', '远近青山，回环千里。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2614, '丑', '可借是个女流辈，也有良人不似他。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2615, '丑', '鹊噪新睛，帘前佳音。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2616, '丑', '隔江风起秋阴早，晚征夫子仔细行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2617, '丑', '午夜以报，食而以空。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2618, '丑', '挨排度日，未见笑颜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2619, '丑', '兄弟四人，数注皆贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2620, '丑', '马无缰，未可以行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2621, '丑', '名利两成，身游泮水。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2622, '丑', '独坐黄错谁是伴，紫蔬花对紫薇郎。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2623, '丑', '招得一子金，二子木。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2624, '丑', '书窗春缓，桂籍生香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2625, '丑', '乡榜题名。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2626, '丑', '年来时又高，饮酒乐富豪。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2627, '丑', '副魁而司教，铎食禄天朝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2628, '丑', '三子生年属金，四子生年属木。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2629, '丑', '此刻生人，妻宫带疾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2630, '丑', '登月宫扳丹桂，饮鹿鸣会嫦娥。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2631, '丑', '不从文武科中出，命有小人更员行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2632, '丑', '兄弟十一人，数有六贵。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2633, '丑', '招得水火之子，妻巧金土方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2634, '丑', '得进门，少年可喜。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2635, '丑', '红炉不断燧皇火，羽扇频摇少女风。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2636, '丑', '巷鼓舞乐尧天。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2637, '丑', '小桥泮藜，书香门第。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2638, '丑', '名登黄甲。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2639, '丑', '生金水之子，妻配土木方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2640, '丑', '兄弟十二人，数有六贵。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2641, '丑', '晚潮失早潮兴，夹岸苍海水平。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2642, '丑', '丰年粮足，家室宁康。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2643, '丑', '多艺多能，衣食足用。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2644, '丑', '傲物气高，多所不合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2645, '丑', '以监而选知县，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2646, '丑', '屈指计前程，程程查不成。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2647, '丑', '蔓荆当道，步步纠缠。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2648, '丑', '灾晦相侵，流年不宁。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2649, '丑', '初授知县，必有变迁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2650, '丑', '吉神切莫对凶神，对敌祸深而福浅。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2651, '丑', '命带文昌，正当入泮。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2652, '丑', '兄弟五人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2653, '丑', '索绚成盛，时早图。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2654, '丑', '罗网内张，外来无良。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2655, '丑', '无男无女，在家出家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2656, '丑', '鸿飞冥冥笑，数泽之戈人。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2657, '丑', '波浪虽高，弧舟系得住。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2658, '丑', '数有十二子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2659, '丑', '风平浪息，正好行舟。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2660, '丑', '言慎行微，未可傲物。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2661, '丑', '太岁无情，凶多吉少。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2662, '丑', '事不劳心，谋略凑合。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2663, '丑', '乐得足优闲，多为情义士。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2664, '丑', '兄弟六人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2665, '丑', '问艺岂能成大业，笙歌空误少年行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2666, '丑', '当忧不忧，吉神解救。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2667, '丑', '倚窗吟寂正愁人，风动帘笼暗有惊。', '[46, 47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2668, '丑', '清宵鹤唳，凄凉为怪物。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2669, '丑', '一泓清水碧琉璃，鱼跃波纹惊若疑。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2670, '丑', '风雨明晦，昼夜不分。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2671, '丑', '医星高照，悬壶得名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2672, '丑', '四字切忌：锲而不舍。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2673, '丑', '木火之年当得贵，此刻生人定不差。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2674, '丑', '度过藤桥路径通，人声掩映绿阴中。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2675, '丑', '朝夕奔驰，愁怀莫释。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2676, '丑', '劫神操权，威镇三军。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2677, '丑', '天祜吉人闲，中福寿康宁。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2678, '丑', '白家负涂，灾入室中。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2679, '丑', '此刻生人，死于土方年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2680, '丑', '腰间虽有黄金甲，犬头鼠脚也惊人。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2681, '丑', '行径盘恒，进退未安。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2682, '丑', '锦堂开寿域，儿孙称贺福绵绵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2683, '丑', '主张和有人，进取尚有益。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2684, '丑', '兄弟十人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2685, '丑', '到处有逢迎，马足几千里。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2686, '丑', '钥琐相连不须疑，丹桂须扳第一枝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2687, '丑', '富贵荣华称寿考，尺壁寸金木为宜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2688, '丑', '暖衣饱食，可以永日。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2689, '丑', '比武举而选千总，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2690, '丑', '人事蹉跎惆怅多，怎能消遣可如何。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2691, '丑', '雷振东南，不及掩耳。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2692, '丑', '天地宠耀，位至三公。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2693, '丑', '鬼神赫怒，天降之祸。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2694, '丑', '连建不世奇功，合当世爵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2695, '丑', '东风有信，长安十里杏花香。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2696, '丑', '背灯一部书，未可言得意。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2697, '丑', '相亲不相见，相见不相知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2698, '丑', '醉起舞婆娑，安然乐意多。', '[87, 88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2699, '丑', '小桥扶藜，曲转绿杨溪。', '[12, 13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2700, '丑', '鸥鸟自相亲，橹声摇曳不为惊。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2701, '丑', '五福咸臻，儿孙绕室。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2702, '丑', '驱牛烦热最难当，放下阴处可纳凉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2703, '丑', '先花后果，早子逢凶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2704, '丑', '春色恼人闷，眉头锁不开。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2705, '丑', '骨肉伤情，多病人心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2706, '丑', '晦气消除人事通，谋为皆善合相逢。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2707, '丑', '命中偏才，偏房可立。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2708, '丑', '丧门相照，忧及严亲。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2709, '丑', '妻配犬命生，不至中途分。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2710, '丑', '恩命天来，救受封赠。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2711, '丑', '潭溪一转，流水溶溶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2712, '丑', '多仓多箱，福禄无疆。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2713, '丑', '笔走龙蛇高万丈，一举扬名应富豪。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2714, '丑', '暑气薰人，待时可解。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2715, '丑', '不以年迈自而，惟知赤心报国家。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2716, '丑', '兄弟七人，数有六贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2717, '丑', '雨雪霏霏，长途泥滑。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2718, '丑', '乡科及第。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2719, '丑', '万事得周全，夕阳东下水流西。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2720, '丑', '禄耀职照，官升职显。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2721, '丑', '自约出家，前缘所报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2722, '丑', '可限灾星不可逃，阴阳度更相遭。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2723, '丑', '奎星高照，一举冠群英。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2724, '丑', '余寒犹未减，何必问东风。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2725, '丑', '数有五子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2726, '丑', '逾垣而进，守以中正。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2727, '丑', '牛羊相触，祸伏萧墙。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2728, '丑', '盈盈花落，泪及红妆。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2729, '丑', '江头昨夜报潮生，来往奔驰势未能。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2730, '丑', '况而复滞，百般巧计。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2731, '丑', '此年多灾星，宝镜被尘埋。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2732, '丑', '一生享用多丰足，万事无求福自来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2733, '丑', '晋升知县。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2734, '丑', '早花方秀丽，风雨又相催。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2735, '丑', '即鹿无虎，徒枉取难。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2736, '丑', '稀更稀今朝，长别待何时。', '[77]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2737, '丑', '不得其志，渊明东归。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2738, '丑', '谋事无成破损多，凡为无遂怎如何。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2739, '丑', '效该生子。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2740, '丑', '隆隆三伏暑，金风一夜爽人怀。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2741, '丑', '时运颠倒，行人暂停。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2742, '丑', '通都大邑，万物咸备。', '[58, 59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2743, '丑', '前程有厄，退之为得。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2744, '丑', '南园风烈烈，昨夜桂花风吹折。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2745, '丑', '虽得东风便，一夜渡扁舟。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2746, '丑', '真假二子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2747, '丑', '阴阳调和，沾濡雨露。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2748, '丑', '利用咸宜，东西南北也相宜。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2749, '丑', '出谷黄莺，最好佳音。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2750, '丑', '求之不得生，浊浪卷浮云。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2751, '丑', '命犯天囚决配，徒流出外州。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2752, '丑', '早失双亲根抵孤，生涯又薄少良图。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2753, '丑', '四方之利，白手兴家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2754, '丑', '科甲及第。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2755, '丑', '皓月十分圆，光明千里遍山川。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2756, '丑', '已知其足，自然无欲。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2757, '丑', '秋水照龙门，春风吹桃李。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2758, '丑', '木火之年俱生子，无奈金水尽克去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2759, '丑', '此刻注定有贵子，土木之年得功名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2760, '丑', '东风拂寒来，其年事多端。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2761, '丑', '春酒已熟，无日不足。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2762, '丑', '常怀共忧虑，日后享安舒。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2763, '丑', '中奎辕上碧琉璃，万里光明路不迷。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2764, '丑', '此刻注定贵妇人，土木之年夫大发。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2765, '丑', '淡云色青青，春梦正悠悠。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2766, '丑', '夕阳西下，牧人忘牛。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2767, '丑', '豕惊蹈，灾晦相侵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2768, '丑', '年来颇相得，日里耕夜织。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2769, '丑', '祸福无常，内外交错。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2770, '丑', '声唧唧，妇叹于室。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2771, '丑', '东君犬吠，吃着一惊。', '[90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2772, '丑', '破却家财出外州，贵人相助不须忧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2773, '丑', '人事问兴，然乐意浓。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2774, '丑', '披襟凉亭上，渐渐爽气来。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2775, '丑', '命薄红颜一树花，春风已抱曲琵琶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2776, '丑', '运至时行，家道渐兴。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2777, '丑', '兔狡脱间，雉取罹罗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2778, '丑', '夫别阳间去，干愁泪两行。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2779, '丑', '经营早晚苦劳心，脱却劳心幸有成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2780, '丑', '马蹄逐尘，驰驱千里。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2781, '丑', '细雨霏霏，前途泥滑。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2782, '丑', '五子土六子水。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2783, '丑', '从容乐意，自适余年。', '[82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2784, '丑', '此年事不宁，灾晦又相侵。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2785, '丑', '同舟共乐，前有风波。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2786, '丑', '律法精明人品异，案头文卷逐条彰。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2787, '丑', '过了崎岖路，尽是舟渡行。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2788, '丑', '科甲及第。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2789, '丑', '屠行并非美业，放下屠刀成佛。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2790, '丑', '得失无关，安然进步。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2791, '丑', '中年得子莫嫌迟，惟喜迟儿庆有余。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2792, '丑', '劳心又劳力，挑担未有人。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2793, '丑', '乱落桃花舞风时，春来去少三五枝。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2794, '丑', '数有四子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2795, '丑', '时授府左，堂郎官列。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2796, '丑', '桃李带雪满园开，红红白白报春来。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2797, '丑', '乔木来仪，文明之象。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2798, '丑', '扬子江头一小舟，轻风相送顺流行。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2799, '丑', '春色十分浓，水流花落鸟威风。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2800, '丑', '前去有风波，行人仔细过。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2801, '丑', '安闲岁月，无事不悦。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2802, '丑', '风吹禅灯，半明半暗。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2803, '丑', '庭前草色，红绿交加。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2804, '丑', '如醉初醒，人事开展。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2805, '丑', '秋风萧然，满地黄花。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2806, '丑', '日照楼台，浮云渐开。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2807, '丑', '辛苦拮据，白手成家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2808, '丑', '灵符相照，绵绵浮灾意外来。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2809, '丑', '赏花有年，风吹孝服三年忧。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2810, '丑', '事业不专，进三退四。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2811, '丑', '房孝之年。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2812, '丑', '梦之未醒，或颠或倒。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2813, '丑', '大数已停，好花开尽。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2814, '丑', '妻命火年生方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2815, '丑', '朱衣点头马，所威北山。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2816, '丑', '优之复喜，先难后易。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2817, '丑', '晓望山前霁色开，俄然风起雨又来。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2818, '丑', '前后拥护，履之不意。', '[83, 84]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2819, '丑', '焚香晨诵法，点烛夜谈经。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2820, '丑', '德惠流芳，兰蕙生香。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2821, '丑', '雪摊兰关，独疑不前。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2822, '丑', '非僧非道，优游逸民。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2823, '丑', '夫妻应偕老，琴瑟得和鸣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2824, '丑', '人事今朝得畅怀，春风丽日好花开。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2825, '丑', '云收雨散，可问行藏。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2826, '丑', '走到半途路若迷，其中一着点先机。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2827, '丑', '名登黄甲。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2828, '丑', '空中伏火烟，笼中紫燕飞。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2829, '丑', '无意多运穷，人做小勾连。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2830, '丑', '花落又花开，春风次第来。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2831, '丑', '其年不利，官事勾连。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2832, '丑', '山川火发，殃及千人。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2833, '丑', '徒弟十人，送老五人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2834, '丑', '谋事方齐，春风又送子规啼。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2835, '丑', '晦气及人，减却精神。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2836, '丑', '交错声笛，梅花开落。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2837, '丑', '到此数难留，整顿别离愁。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2838, '丑', '兄弟五人，数当尽贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2839, '丑', '流年驳杂事，纷纷紫竹敲。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2840, '丑', '谋事未通行，船遇打头风。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2841, '丑', '有食有余，乐于晚年。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2842, '丑', '春光虽好，风雨堪悲。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2843, '丑', '山头饥虎蹲，行人须仔细。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2844, '丑', '双亲俱有寿，母先赴瑶池。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2845, '丑', '身在公门寻活计，运来自有贵人扶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2846, '丑', '晦气相侵，狂风骤雨。', '[12, 13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2847, '丑', '声名显宇宙，皇都得意回。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2848, '丑', '进退咸无位，不如守其中。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2849, '丑', '兰膏已尽，一室昏暗。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2850, '丑', '初任主事之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2851, '丑', '五行最有刑，出胎便丧母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2852, '丑', '开门似水，信哉磨磷。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2853, '丑', '外错不知，忧之如何。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2854, '丑', '否之既进，忧之复来。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2855, '丑', '风外康节，祯祥之福。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2856, '丑', '可得伶之子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2857, '丑', '兄弟十人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2858, '丑', '生涯不若破家业，破耗一似绵张风。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2859, '丑', '洛阳为报十分春，杨柳依依绿荫。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2860, '丑', '虎怒成风，山木皆惊。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2861, '丑', '罗列高堂，汪然渺茫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2862, '丑', '湘江烟火尧波涛，二雁高飞任去来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2863, '丑', '童运未坚，早入黄泉。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2864, '丑', '行事无阻，行舟顺风。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2865, '丑', '生计已尽，梦入华胥。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2866, '丑', '知已将来不用求，龙泉磨利射斗牛。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2867, '丑', '一胎生三子，世上罕有事。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2868, '丑', '科甲及第。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2869, '丑', '恶曜攻身，须防危险。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2870, '丑', '生涯寂寞，凄凉无诊。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2871, '丑', '有日似刀锋，原来性不凶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2872, '丑', '相见有悲啼，一夜凄凉泪别情。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2873, '丑', '画虎于墙，有惊无灾。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2874, '丑', '六阴极处水凝冰，造物分明未有形。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2875, '丑', '事事多語，静听自得宜。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2876, '丑', '一杯春酒一杯水，坚守为高事可宜。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2877, '丑', '为着别故人，空作有年计。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2878, '丑', '兄弟十人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2879, '丑', '居上克昨，为下克忠。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2880, '丑', '十年以前事纷纷，此后图谋事遂心。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2881, '丑', '镜中之花，遇而不遇。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2882, '丑', '春水鱼儿游，一跃而变化。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2883, '丑', '谋事费工夫，反覆几蹉跎。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2884, '丑', '一天星斗甚光明，十里长亭一夜行。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2885, '丑', '有心领青，已知一生届。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2886, '丑', '招得金水土之子，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2887, '丑', '出转回溪便连当，夹岸绿杨更已新。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2888, '丑', '美运辐，财帛相臻。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2889, '丑', '所为皆合，谋事有益。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2890, '丑', '今朝来喜太平年，解放眉头开笑颜。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2891, '丑', '围炉烘火，暖气薰人。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2892, '丑', '一步崎岖，高低不平。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2893, '丑', '画饼充饥，谋悉成虚。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2894, '丑', '霜霜霏罪，长途泥滑。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2895, '丑', '德裕经邦，才优济世。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2896, '丑', '昏迷朦胧，未分东西。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2897, '丑', '春夏秋冬，寒暖相迁事不同。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2898, '丑', '遍舟一叶渡，东南风正狂。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2899, '丑', '风雨霏霏，长途崎岖。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2900, '丑', '浮云飞去，依旧晴明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2901, '丑', '科甲及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2902, '丑', '流年凶星，灾晦相侵。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2903, '丑', '土年母终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2904, '丑', '喜之未已，忧之又随。', '[90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2905, '丑', '冷落离披，雨中桃李。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2906, '丑', '炉烟消尽化成灰，一缕云生化气回。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2907, '丑', '璞出于石，无人识别。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2908, '丑', '谋事难成，徒劳心力。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2909, '丑', '进士及第。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2910, '丑', '祖业不靠，白手成家。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2911, '丑', '妻生一子，亲生二子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2912, '丑', '通霄风雨，十分春色便珊珊。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2913, '丑', '习业儒读萧何略，身在公门乐意多。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2914, '丑', '太岁相冲，纵喜也凶。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2915, '丑', '有征无战，光王之师。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2916, '丑', '前去路迢迢，何须问变化。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2917, '丑', '事业问萧曹，功名亦可得。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2918, '丑', '乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2919, '丑', '却空篱落，探春回还。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2920, '丑', '利不可求，动而见忧。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2921, '丑', '妻命属猪，中途而去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2922, '丑', '名登黄甲。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2923, '丑', '青青草色，又得一番风雨滋。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2924, '丑', '黄昏不辨，幸逢朗照。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2925, '丑', '兄弟八人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2926, '丑', '多少未了事，件件挂心怀。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2927, '丑', '马在山南，人在山北。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2928, '丑', '束装西归，鸿唱送离歌。', '[77]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2929, '丑', '耿耿不寐，搔首谁语。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2930, '丑', '马头羊尾，跋涉多风雨。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2931, '丑', '千里寄书来，疑吉又疑凶。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2932, '丑', '塞外风物滥关情。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2933, '丑', '蛇绕虹腾民，仰中天法曜。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2934, '丑', '改换门间事更新，锦衣玉食福仍臻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2935, '丑', '腰横金作带，符剑玉为邻。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2936, '丑', '阳数满难回，定作黄泉客。', '[77]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2937, '丑', '炎热已蒸人，爽气已侄秋信至。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2938, '丑', '优情种种人无殊，获屈蛇蝎志未舒。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2939, '丑', '授九童之造命，统百万之雄兵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2940, '丑', '蜃吻虽黄，破处重重讼。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2941, '丑', '大车无辙，小车无轨。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2942, '丑', '破财耗散，事多变迁。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2943, '丑', '洞房之喜，定在此年。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2944, '丑', '小人相欺，夫端降害。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2945, '丑', '黄淡饭可疗饥，竹茅舍乐有余。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2946, '丑', '明月见星，说法谈经。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2947, '丑', '苦雨入凄风，令人不堪闻。', '[91]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2948, '丑', '秋寒苦旱，然下雨足精神。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2949, '丑', '红妆冷落，秋草焦枯。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2950, '丑', '数有六子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2951, '丑', '财帛丰盈，一世我忧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2952, '丑', '双飞紫燕两分飞，夫君不幸命先归。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2953, '丑', '喜气宠袭，终难一遇。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2954, '丑', '新竹破苍苔，成竿指日来。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2955, '丑', '皓月正当空，清光自不同。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2956, '丑', '孝服三年，于此不免。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2957, '丑', '此刻孔门人，金年当入泮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2958, '丑', '富贵两全，人间之福。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2959, '丑', '复任知县。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2960, '丑', '病符照命，灾意外来。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2961, '丑', '母终于金年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2962, '丑', '事业不专，半进半退。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2963, '丑', '天高地迥，不可叹穷愁。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2964, '丑', '夕阳初下，数已尽矣。', '[77]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2965, '丑', '钱财陡发，驷马驰来。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2966, '丑', '当有三母之称。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2967, '丑', '瑞气融融，门庭喜庆。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2968, '丑', '药飞片片，寒冬趣煎。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2969, '丑', '一江春水送行舟，万里云山极目游。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2970, '丑', '孝服相侵，流年肖咎。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2971, '丑', '六亲少靠，骨肉寡缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2972, '丑', '父母生来，独自一个。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2973, '丑', '心之忧寂，最难度日。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2974, '丑', '富裕且康，惟田惟桑。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2975, '丑', '花蕊初红，暴风疾雨。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2976, '丑', '连遭时不利，欲进不能行。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2977, '丑', '精修玄妙法，子里仰纯阳。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2978, '丑', '生辰八字造化，五行生克卜荣枯。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2979, '丑', '优闲岁月，斯为多福。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2980, '丑', '晓烟迷杨柳，长堤远溟蒙。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2981, '丑', '前途应有渔郎渡，不必停去问津。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2982, '丑', '兴至三杯酒，闲时一局棋。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2983, '丑', '传得松筠，新逢桃节花。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2984, '丑', '雪与梅花并，又见一番香。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2985, '丑', '有针无线用，欲空无成衣。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2986, '丑', '升迁理刑郎，官列宿命宫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2987, '丑', '朝功暮课，种得清净福。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2988, '丑', '园中花畔闻啼鸟，此时天命非久长。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2989, '丑', '著新结排，列大规模。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2990, '丑', '弃偏途而就正道，来日尽光明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2991, '丑', '观颜察色分贫富，验气凝气神识英雄。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2992, '丑', '三星在户，喜事频来。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2993, '丑', '鼓舞之福，安然终朝。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2994, '丑', '欲成来生佛，早晚须诵经。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2995, '丑', '乐事从心，眉头喜生。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2996, '丑', '早涉风霜苦，运来发财自兴家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2997, '丑', '大厦要扶持，还须得一本。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2998, '丑', '已得静中趣，安然与世殊。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (2999, '丑', '为人素有刚柔性，处世机亲出从伦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3000, '丑', '钗于奁内，玉在框中。', NULL);
