INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3574, '寅', '有口难言，前生所致。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3575, '寅', '官至都司，必有变迁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3576, '寅', '大小安然，福禄绵绵。', '[87, 88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3577, '寅', '能文知字，女中丈夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3578, '寅', '一母一母又一母，前有母后有母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3579, '寅', '迁向西方，随遇而安。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3580, '寅', '朦胧如醉，作事乘时。', NULL);
