INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3651, '寅', '横进资财，凑合开来。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3652, '寅', '黑云密布，恨天不雨。', '[63, 64]');
