INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3654, '寅', '春花取次看，马蹄得意回。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3655, '寅', '草森萌芽，春风转绿。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3656, '寅', '兄弟九人，方合此刻。', NULL);
