INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3665, '寅', '天然之乐，安享清平。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3666, '寅', '子登科甲。', '[67, 68]');
