INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3672, '寅', '打算为活计，经纪作生涯。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3673, '寅', '子息五旬外，得之方始。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3674, '寅', '占下之时，未有洞房之喜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3675, '寅', '水火相刑，死在舟中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3676, '寅', '子登科名。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3677, '寅', '此年游远道。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3678, '寅', '数注当坏一足。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3679, '寅', '灾晦缠身，有犯太岁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3680, '寅', '父母替日，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3681, '寅', '吩咐东君好护持，奇花遭雨坏离披。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3682, '寅', '官至知县，以道终身之乐。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3683, '寅', '白雪纷飞，高低路岐。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3684, '寅', '好鸟鸣春，东风快人。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3685, '寅', '十里青山火已流，沛然下雨晚凉收。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3686, '寅', '父子不和，家门伏祸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3687, '寅', '取用有余，快然无恨。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3688, '寅', '一身闲似水，逍遥出世尘。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3689, '寅', '红妆簇簇锦云路，十里池塘菱荷香。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3690, '寅', '官至理卿而致仕。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3691, '寅', '云归故碧天空，光照逢门日色洪。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3692, '寅', '日中斗观，灾毒渐生。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3693, '寅', '一日愁天百事多，心中烦恼乱如麻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3694, '寅', '西方自有人携引，苦守三时滞乃通。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3695, '寅', '得亲知己气相求，从此营谋不用忧。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3696, '寅', '灾晦交侵，眉头交。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3697, '寅', '谋为近成锦，绣映入耳目。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3698, '寅', '室至守府，不能高擢。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3699, '寅', '树根基浅，为风所拔。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3700, '寅', '兄弟六人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3701, '寅', '掌朝廷大政，声名播四海。', '[56, 57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3702, '寅', '少年失母，方合此刻。', '[12, 13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3703, '寅', '经德化民，是感不应。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3704, '寅', '一只扁舟直早潮，布帆初挂在江阜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3705, '寅', '夜雨初晴连日笑。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3706, '寅', '细寸飞丝，滞而不明。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3707, '寅', '愁多没处排，春风次第来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3708, '寅', '花开遭风雨，寒气伤心扉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3709, '寅', '叩门急是非，一见官归根。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3710, '寅', '狂风飘落叶，何处是归根。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3711, '寅', '春色有脚还未去，鹤报东君喜信来。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3712, '寅', '左右得人扶，险处可无妨。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3713, '寅', '一瓶一钵，到处生涯。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3714, '寅', '朦胧皎月，云去云来。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3715, '寅', '钦授知县，修政爱民。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3716, '寅', '幼年生子，世上难逢。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3717, '寅', '前生过逼，举止皆错。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3718, '寅', '数有四子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3719, '寅', '东边日出西边雨，一朝几度尤怨言。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3720, '寅', '随缘度日，猿鸟相亲。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3721, '寅', '奔奔碌碌，忧之如何。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3722, '寅', '是非相寻，无日得安。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3723, '寅', '万恶淫为首，当戒酒声气。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3724, '寅', '喜事相遇，乐边鸦噪又逢凶。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3725, '寅', '钓得鱼儿已上钩，俄然跃起水中游。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3726, '寅', '一重欢喜一重惊，道是无情却有情。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3727, '寅', '谈禅风拂座，听经石点头。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3728, '寅', '太阳相照，好事临头。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3729, '寅', '项庄舞剑，意在沛公。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3730, '寅', '火星入宅，不安之象。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3731, '寅', '正妻无子，妾生一儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3732, '寅', '切莫睹中行，虚子利有名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3733, '寅', '千古科名。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3734, '寅', '天嗣天经，子当正副。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3735, '寅', '姊妹九人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3736, '寅', '运逢转处，春花依旧向阳开。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3737, '寅', '吉里有灾耗，喜运未称心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3738, '寅', '守静为吉，动而见忧。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3739, '寅', '运逢阳九，利见大人。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3740, '寅', '草木久遗霜，太阳一照自春光。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3741, '寅', '错于事理，投之皆乘。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3742, '寅', '其人之亡，定在十二月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3743, '寅', '九子生年水，十子生年金方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3744, '寅', '拂拭尘镜半又明，天长依旧又昏沉。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3745, '寅', '谢却人间礼法正，晨钟暮鼓福无双。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3746, '寅', '妻生一子，妾生一儿。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3747, '寅', '前夫死于木火之年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3748, '寅', '金水之年，克夫方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3749, '寅', '数有偏估，身带暗疾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3750, '寅', '科场选举。', '[18, 19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3751, '寅', '数该生子。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3752, '寅', '乡榜题名。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3753, '寅', '天罗地网正非常，使人消磨不可当。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3754, '寅', '妻宫多报，子有前后。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3755, '寅', '种田原正作，但苦谷不丰。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3756, '寅', '金木相克，悬梁而死。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3757, '寅', '善夺夫权，治家能归。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3758, '寅', '房考之年。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3759, '寅', '桃李成，万性沾福花之惠。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3760, '寅', '颠倒流离，穷苦自如。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3761, '寅', '五子生年属土金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3762, '寅', '和气映画常，桂兰乐安康。', '[83, 84]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3763, '寅', '苍松一生，现有青山。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3764, '寅', '妻生一子，妾生三儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3765, '寅', '兄弟七人，数注五贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3766, '寅', '万绪千端，宝镜当磨仔细看。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3767, '寅', '优闲无事纳祯祥，几朵梅花扑鼻香。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3768, '寅', '初授令尹。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3769, '寅', '中途险过，稳步宫墙。', '[40, 41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3770, '寅', '陷于泥沙，难以举步。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3771, '寅', '可恨灾星不可逃，阴阳度祸相遭。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3772, '寅', '南山鸟鸣，北山张罗必有惊。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3773, '寅', '辛苦经商，四海家业足一生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3774, '寅', '不及二七数，惜乎亡矣。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3775, '寅', '半世虚名末有成，原来数定晚年兴。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3776, '寅', '手扳弱柳，不可着力以致伤。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3777, '寅', '铮铮然中由性质，拘拘然中子规模。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3778, '寅', '兄弟六人，数有四贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3779, '寅', '福禄无常，人子有变。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3780, '寅', '狐欲渡河濡，实难济顺舟。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3781, '寅', '田土之乐利，一生常有贵人扶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3782, '寅', '三子生年属金木方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3783, '寅', '红日已出云又暗，长逛迢迢何时旦。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3784, '寅', '长子木年生，次子土年生方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3785, '寅', '云观五色，喜事光临。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3786, '寅', '新竹成竿，扶摇直上。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3787, '寅', '花满池塘，香气异常。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3788, '寅', '水年母终方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3789, '寅', '佳节年华三月天，红红绿绿快人心。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3790, '寅', '子登科名。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3791, '寅', '坦然一往总无惊，驾驭驰驱有驷马。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3792, '寅', '檐前鹊噪定，是来报喜事。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3793, '寅', '天刑人数眼中来，海中仙果结子迟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3794, '寅', '老景多啾唧，斯年少吉利。', '[81, 82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3795, '寅', '爵初高迁，恩自九重。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3796, '寅', '数该生子。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3797, '寅', '老年夫妇，不免凄凉之悲。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3798, '寅', '父故于水年，母尚茂木年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3799, '寅', '春色皇州次第花，开到中秋自然息。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3800, '寅', '钦命典试。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3801, '寅', '身荣八品职，略遂平生志。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3802, '寅', '初年入泮。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3803, '寅', '年至耳顺，政治劳民。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3804, '寅', '言公而不寻，一见便生嗔。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3805, '寅', '事多得合，可以施为。', '[36]');
