INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3942, '寅', '早年家业尽消磨，晚岁凄凉奈若何。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3943, '寅', '子当登科。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3944, '寅', '年逢太岁，不测灾来。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3945, '寅', '终日为人谋，何不自为计。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3946, '寅', '生来无义方之训。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3947, '寅', '风夜度行程，明朝风又生。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3948, '寅', '秋草靡芜，严霜所苦。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3949, '寅', '恍恍惚惚，不但人嗔且有鬼。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3950, '寅', '灯花结蕊，喜事重来。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3951, '寅', '一身活计在湖边，衣食无亏身不安。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3952, '寅', '身荣翰林，人生大幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3953, '寅', '新荷出水，亭亭直上。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3954, '寅', '际遇淹留，只多烦恼。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3955, '寅', '土木之年，荣任知县。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3956, '寅', '好树滋培，会成梁材。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3957, '寅', '数有七子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3958, '寅', '枯苗无雨色如焦，一旦沱勃然秀。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3959, '寅', '阳和风动，万物发荣。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3960, '寅', '子占高魁。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3961, '寅', '克恭克俭，自然天祜吉人。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3962, '寅', '名列宫墙，文明之象。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3963, '寅', '少上白发志不哀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3964, '寅', '错足前途三十里，回来度倦又重新。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3965, '寅', '晚年为孤子，世上堪难得。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3966, '寅', '母日云亡，守制孝堂。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3967, '寅', '疾病每相侵，流年处有疵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3968, '寅', '金水之年点翰林。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3969, '寅', '撑之东墙，倾之西墙。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3970, '寅', '灾杀相侵，人子纠缠。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3971, '寅', '子当登科。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3972, '寅', '路上有艰难，平阳莫问津。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3973, '寅', '子占科名。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3974, '寅', '乡试中式。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3975, '寅', '雨顺风调，大有之庆。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3976, '寅', '黄烛独月色，光明正在天。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3977, '寅', '数定其妻，死于非命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3978, '寅', '徒弟四人，三人送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3979, '寅', '作入幕宾，损德无益。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3980, '寅', '隐居青云路，马头带剑回。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3981, '寅', '烛泪淋漓，哭夫早逝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3982, '寅', '数该生子。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3983, '寅', '花蕊放红，怎堪风雨。', '[4]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3984, '寅', '连年晦滞今朝释，自今更换又重新。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3985, '寅', '斯年春闹大捷。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3986, '寅', '七二称衰年，人生一大奇。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3987, '寅', '子中科名，善之所至。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3988, '寅', '月朗梅争秀，风和柳吐青。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3989, '寅', '吉星照耀，官职高升。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3990, '寅', '安然老景胜中年。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3991, '寅', '早运迟迟后运美，梅花只到雪时奇。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3992, '寅', '数定生子，阴阳中来。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3993, '寅', '子当登科。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3994, '寅', '兄弟七人，数有四贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3995, '寅', '数有三子，依次金木水。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3996, '寅', '远近依依物有情，花好开向值清明。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3997, '寅', '老树萌芽，人生长寿。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3998, '寅', '斯时妻安，亦是安然。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (3999, '寅', '终于一百零四年，拍掌大笑变登仙。', '[104]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4000, '寅', '有哀悲之忧。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4001, '卯', '斯时运已通，做事必成功。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4002, '卯', '自成自立自支持，可谓须眉大丈夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4003, '卯', '公道世间为白发，贵人头上不曾饶。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4004, '卯', '寒暖不寻常，小处终不免。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4005, '卯', '惟知务礼宜，家晏安然乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4006, '卯', '盈盈秋水，淡淡青山。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4007, '卯', '而今撑过羊肠道，周道倭迟事不难。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4008, '卯', '束之高阁，莫为儿孙。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4009, '卯', '学宗朱程术出场，曾为人祜富寿增。', '[6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4010, '卯', '万象更新，韶光明媚。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4011, '卯', '鸾凤和谐，中在一笑。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4012, '卯', '由熙由广，利涉大川。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4013, '卯', '君子嘉遁，古无不利。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4014, '卯', '万卉正芳菲，韶光处处宜。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4015, '卯', '拨山超海，缘木求鱼。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4016, '卯', '君子谋道，小人谋食。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4017, '卯', '兄弟八人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4018, '卯', '独彼无处有清流，来喜应求来破愁。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4019, '卯', '没有规范，不成方圆。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4020, '卯', '子命属水方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4021, '卯', '名登龙虎榜。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4022, '卯', '满腹文章贯斗牛，乡榜题名独占先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4023, '卯', '项庄舞剑，意在沛公。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4024, '卯', '运逢佳境，如花遇春。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4025, '卯', '老来无恙是多福。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4026, '卯', '龙德相扶，大吉大象。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4027, '卯', '仲伯之德，由德正直。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4028, '卯', '名登金榜。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4029, '卯', '劫杀相逢，死于刀下。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4030, '卯', '兄弟五人，中断离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4031, '卯', '名登虎榜。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4032, '卯', '方当出仕又阻抑。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4033, '卯', '人坐春风，其乐融融。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4034, '卯', '乡榜题名。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4035, '卯', '为人依本分，言行两无亏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4036, '卯', '胸中锦绣人难及，曾魁天下是君子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4037, '卯', '涵濡五露荣，花信有春色。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4038, '卯', '宴饮鹿鸣。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4039, '卯', '度过崎岖路，攸往是坦夷。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4040, '卯', '坤人之运造化奇，一天星斗见光辉。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4041, '卯', '不假推移，安然进步。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4042, '卯', '春时日日好，深闺淑气佳。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4043, '卯', '刘郎莫恨蓬山远，驿使传书已到门。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4044, '卯', '颜回之寿，少四年而归。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4045, '卯', '暮年为政，从心所欲。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4046, '卯', '月在水中，可玩不可捉。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4047, '卯', '父命木年生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4048, '卯', '深院锁黄昏，阵阵芭蕉雨。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4049, '卯', '烟暖初出冥，晚来景色新。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4050, '卯', '龙逢浅水，虎落平壤。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4051, '卯', '数该生子。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4052, '卯', '解神切莫听凶神，破去钱财又费心。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4053, '卯', '进取梁施，贵人得扶持。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4054, '卯', '此数推为性最华，身近候伯早堪夸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4055, '卯', '天毓其才人，莫并金谐选。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4056, '卯', '瑞气融融，景象非前。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4057, '卯', '佳人有正副，正副不和睦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4058, '卯', '父子千总，人生在幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4059, '卯', '南院枯枝，复发其荣。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4060, '卯', '喜气盈门，物色更新。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4061, '卯', '朱雀衔符至，勿引是非来。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4062, '卯', '分有前母，生我是庶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4063, '卯', '百总升千总，祖庇有余德。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4064, '卯', '见龙在田，普其润泽。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4065, '卯', '年年事事通，枯枝稿木皆发荣。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4066, '卯', '风行水面，旋起波涛。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4067, '卯', '公义以行为，一方之保障。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4068, '卯', '得人与他为活计，傍个贵人发大家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4069, '卯', '犬有两口，哭泣之哀。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4070, '卯', '伐木丁丁笃求友，直谅多闻同气求。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4071, '卯', '瑞气凝于庭，休微交应中。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4072, '卯', '武曲照命，把总升守备。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4073, '卯', '事事从容，眉头喜色。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4074, '卯', '徒弟五人，三个送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4075, '卯', '从事从容，谋略有功。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4076, '卯', '水年克妻，木年再娶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4077, '卯', '檐前喜鹊噪，报喜又报晴。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4078, '卯', '保固业精练，兵器以御甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4079, '卯', '父母水年生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4080, '卯', '四字切忌：暗箭难防。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4081, '卯', '安居为福，幽人贞吉。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4082, '卯', '母命金年生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4083, '卯', '夫妻偕老，数由前生定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4084, '卯', '鸟鸣，饮啄自得时。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4085, '卯', '密云不雨，烦闷人心。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4086, '卯', '花开未久春光尽，可惜枝头一旦倾。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4087, '卯', '一轮明月，光照九州。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4088, '卯', '一轮明月映秋林，无边风景爽气生。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4089, '卯', '不须卜甲子，五旬之外人。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4090, '卯', '雌雄相守岁，林稳得优游。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4091, '卯', '筒有衣仓，粟生食足。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4092, '卯', '甲子之年，乡榜题名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4093, '卯', '志在四方，锦衣归故里。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4094, '卯', '磐石之安，言其未动。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4095, '卯', '艺术依人显，能得福自臻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4096, '卯', '振基业于当时，播芳名于后世。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4097, '卯', '不许千金数，实许七百数。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4098, '卯', '一贡成名，少年得意。', '[1314]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4099, '卯', '如金如锡，如圭如壁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4100, '卯', '风清日丽，山静禅闲。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4101, '卯', '辟雍成名，祖宗荫德。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4102, '卯', '深秋黄菊，晚节馨香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4103, '卯', '夫当入泮。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4104, '卯', '四岁无父，难免泣血。', '[4]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4105, '卯', '韩信受跨下之时。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4106, '卯', '无登科甲，坤人之幸。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4107, '卯', '驿使传消息，门庭喜色新。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4108, '卯', '花开胜似去年红，满院丛中铺锦绣。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4109, '卯', '时哉不可失，时乎不再来。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4110, '卯', '明月清风，人情舒畅听钟声。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4111, '卯', '少年辟雍，乐莫大焉。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4112, '卯', '山外青山名可求，前程进步在他州。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4113, '卯', '夫当入泮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4114, '卯', '舟人不备。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4115, '卯', '父亡矣陡生悲。', '[36, 37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4116, '卯', '他年平地风波起，远避桃源免祸殃。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4117, '卯', '夫登科甲。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4118, '卯', '昨夜征夫路上来，梅花千里护楼台。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4119, '卯', '少年依贡世难逢。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4120, '卯', '世事不明，谬迷于性。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4121, '卯', '数有三母之称。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4122, '卯', '姻缘有跷蹊，不合明媒娶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4123, '卯', '人寿年来有动摇，定名不足莫心高。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4124, '卯', '特立扬媚日，人将何取笑。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4125, '卯', '数该生子。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4126, '卯', '升迁干总。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4127, '卯', '根深蒂固，有为之时。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4128, '卯', '龙年生子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4129, '卯', '春光在日，无日不足。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4130, '卯', '夫当登科。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4131, '卯', '花棉衬雕鞍，日月春光定。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4132, '卯', '月色放青光，遍体精神爽。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4133, '卯', '复补百总。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4134, '卯', '飞檐为祸又为灾，啾唧无端水破财。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4135, '卯', '四龄一跃成文士。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4136, '卯', '夫当入泮。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4137, '卯', '寿喜年高一百余。', '[100]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4138, '卯', '寿余百岁有三春，悠悠一梦。', '[103]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4139, '卯', '月中仙子，可望不可及。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4140, '卯', '迷于穷途，转之路通。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4141, '卯', '母命木年生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4142, '卯', '夫登科甲。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4143, '卯', '金珠为质画为饰，写出丹青凤羽仪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4144, '卯', '温温恭人，维德之基。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4145, '卯', '命中注定七女。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4146, '卯', '数年立志鸡窗下，一旦标名性字香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4147, '卯', '父母生土年终于水年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4148, '卯', '辉宗祖之基，扬子孙之名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4149, '卯', '一生做事，粗晓有失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4150, '卯', '深秋黄菊，晚节馨香。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4151, '卯', '夫当入泮。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4152, '卯', '不思游泮青云路，只图家业乐终身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4153, '卯', '秉性常清净，存心碣慈和。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4154, '卯', '夫登科甲。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4155, '卯', '勿得因人屡变迁，后悔无边。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4156, '卯', '运际其亨，无往不利。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4157, '卯', '寿域同登九十年，寿星昨夜现中天。', '[90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4158, '卯', '金鳞不是池中物，一遇风云化作龙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4159, '卯', '波平风静，正当行舟。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4160, '卯', '家前牛后，弟先终命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4161, '卯', '崎岖路漫，推车停留马足斜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4162, '卯', '享现成福，任意逍遥。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4163, '卯', '夫当入泮。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4164, '卯', '运逢知命，何期镜钗分。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4165, '卯', '终日眉头，愁怀准解救。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4166, '卯', '家室安宁，心字意稳。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4167, '卯', '夫当登科。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4168, '卯', '履丝织编，任意逍遥。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4169, '卯', '辟雍成名。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4170, '卯', '人在中途，飘飘雨中。', '[20, 21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4171, '卯', '当依贡期。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4172, '卯', '美景良辰君莫负，及时行乐且安然。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4173, '卯', '知己相遇，足慰离愁。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4174, '卯', '是非未有停，财帛多破耗。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4175, '卯', '饱食暖衣，无求之乐。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4176, '卯', '名当登科。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4177, '卯', '濡濡仅固得自如，少年常似老来时。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4178, '卯', '瑞气护兰芬，其年大吉庆。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4179, '卯', '命照文星，夫当入泮。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4180, '卯', '心慈好善，福禄诸缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4181, '卯', '辟雍成名。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4182, '卯', '安常处顺，入纳桢祥。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4183, '卯', '少年依贡。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4184, '卯', '项王欲转江东去，谁想乌江不渡人。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4185, '卯', '夫当入泮。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4186, '卯', '兄弟三人，奏楚不同盟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4187, '卯', '科名之星，独当步文场。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4188, '卯', '以监而经历，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4189, '卯', '五子原是金水火，若生土命是虚花。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4190, '卯', '存慈悲心，获修齐志。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4191, '卯', '风前之烛，光摇不定。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4192, '卯', '夫登科甲。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4193, '卯', '兄弟三人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4194, '卯', '万紫千红，更新有兴。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4195, '卯', '命中有七子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4196, '卯', '朝耕夕织，勤俭持家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4197, '卯', '披麻无情，门庭开乱。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4198, '卯', '春风得意，利禄盈盈。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4199, '卯', '鼓盆之歌，再见于斯。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4200, '卯', '国学题名。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4201, '卯', '当页之期。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4202, '卯', '兄弟九人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4203, '卯', '疯病之灾，宿年有咎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4204, '卯', '三子属土与木金，若生水年亦不真。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4205, '卯', '祸去还有灾，阴雨渡阴天。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4206, '卯', '当贡之期。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4207, '卯', '数有三妻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4208, '卯', '身处叔季，俨然律吉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4209, '卯', '数有六子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4210, '卯', '月上栏杆，半明半暗。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4211, '卯', '生长名门，不愧曹族。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4212, '卯', '一段愁怀入莫识，空留明月与人知。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4213, '卯', '命当繁华，一世安康。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4214, '卯', '结子开花树有根，春风蔼快人情。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4215, '卯', '夫入泮宫。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4216, '卯', '运至时行，诸事凑巧。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4217, '卯', '风卷浮云，中天月色。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4218, '卯', '四时佳处，如春如花。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4219, '卯', '韶光新景，足畅我怀。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4220, '卯', '蝉声断续送人矣，一去无踪莫计程。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4221, '卯', '兄弟五人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4222, '卯', '青年朱弦断，鸳鸯再会难。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4223, '卯', '云横秦岭家何在，雪拥蓝关马不前。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4224, '卯', '夫当登科。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4225, '卯', '愁难作解苍茫人，病人不怜人次第。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4226, '卯', '日尽歌呼在，高山流水足逍遥。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4227, '卯', '新竹成竿，扶摇直上。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4228, '卯', '趋吉避凶，须知吉里藏凶。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4229, '卯', '纳宠须知，色重贪花。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4230, '卯', '八卦加一，大数止矣。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4231, '卯', '国学标名。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4232, '卯', '言行不谨慎，有意外之危。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4233, '卯', '火年木年生三子，若生金年是虚花。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4234, '卯', '洋洋自得，旁若无人。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4235, '卯', '骑马渐且高，勿想上高楼。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4236, '卯', '多福多禄，斯年寿足。', '[93, 94]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4237, '卯', '姐作商人，妹入侯门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4238, '卯', '一若求珠沧海上，纵不虚求也是难。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4239, '卯', '当贡之期。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4240, '卯', '有子还无字，无遣讨债儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4241, '卯', '泮池之年。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4242, '卯', '避嫌思退，不堕猜疑。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4243, '卯', '扁舟一叶在江中，顷刻溟溟烟霞红。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4244, '卯', '花开正当赏，风雨又相催。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4245, '卯', '知心相负，暗地有戈。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4246, '卯', '一百零六，不食人间。', '[106]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4247, '卯', '以受道书君馨香，长安城内姓名扬。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4248, '卯', '许进勿退，退得其胜。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4249, '卯', '吉庆重来，门庭纳福。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4250, '卯', '虽有浮云，不掩明月。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4251, '卯', '姊妹三人，先损其一。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4252, '卯', '存心仁慈，立志修齐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4253, '卯', '缓步徐行福自随，室中空信几危灾。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4254, '卯', '鲲鹏展翼，扶摇直上。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4255, '卯', '夫登科第。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4256, '卯', '高下无求，往来春秋。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4257, '卯', '鸟集高枝，无烦啄食。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4258, '卯', '通往直前，却无阻挡。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4259, '卯', '妻命属金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4260, '卯', '辟雍成名。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4261, '卯', '为人忠通，慷慨大方。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4262, '卯', '甲午之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4263, '卯', '冤愁纷纷，抄扰不宁。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4264, '卯', '官至学院尊，尚未心满足。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4265, '卯', '当依贡期。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4266, '卯', '以监而选州官，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4267, '卯', '正路入问福，忽做南柯梦。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4268, '卯', '口舌交争，昼夜不宁。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4269, '卯', '大椿八千岁，庄子游仙境。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4270, '卯', '夫当入泮。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4271, '卯', '风息云收，阳和日暖。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4272, '卯', '官星相照身，近内台天子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4273, '卯', '仁慈好善，广种福田。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4274, '卯', '行年人事齐，春色草姜姜。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4275, '卯', '天哭催人事，有伤骨肉情。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4276, '卯', '姻缘前定，必然亲上加亲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4277, '卯', '春深莫恨无颜色，最喜葵榴映日红。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4278, '卯', '三岁丧父，义方之训恨无人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4279, '卯', '数该生子。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4280, '卯', '晓日紫云上绿楼。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4281, '卯', '几点疏星照，南楼见太阳。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4282, '卯', '快乐又无边，风月春光满目前。', '[93, 94]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4283, '卯', '寂寞有余，财产地僻。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4284, '卯', '夫当登科。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4285, '卯', '夫妻反目，乖戾不和。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4286, '卯', '以监而选知州，数注由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4287, '卯', '黄甲传宣，春间奏捷。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4288, '卯', '莫道天常晴，要时又生风。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4289, '卯', '恩星相照，福自随人。', '[82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4290, '卯', '内外顺和，深得夫唱妇随义。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4291, '卯', '削发为僧，脱却当年景。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4292, '卯', '辟雍成名。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4293, '卯', '时亨运济，无往不利。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4294, '卯', '当依贡期。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4295, '卯', '正途而近贵，自有前程路。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4296, '卯', '东风送和气，花柳媚春辉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4297, '卯', '早岁沉淹运通，梅花只到雪奇中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4298, '卯', '中运经营，家室饱暖。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4299, '卯', '乙西拜师方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4300, '卯', '落地喊三声，未喊父已逝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4301, '卯', '曲曲冈路通行人，行人急急赴春回。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4302, '卯', '危转为安，祸消为福。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4303, '卯', '嫩柳不经三月雨，奇花曾耐社前霜。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4304, '卯', '搔首问青天，人事得周全。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4305, '卯', '夫当入泮。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4306, '卯', '忧以消除，得来凑巧。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4307, '卯', '一轮新皎月，数朵乌云遮。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4308, '卯', '五马翩翩，人羡阳春。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4309, '卯', '夫登科第。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4310, '卯', '初任知府，转身部属。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4311, '卯', '名列辟雍。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4312, '卯', '出门图活计，活计水中生。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4313, '卯', '步高来一步低，高低之处有忧疑。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4314, '卯', '六合多相得，春风到处清。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4315, '卯', '虽然未遂青云志，只图事业作富翁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4316, '卯', '数载科场，一朝得志。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4317, '卯', '求则得之，颇遂其志。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4318, '卯', '其安其顺，乐境相忘。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4319, '卯', '门庭寂寞转兴隆，南北东西处处同。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4320, '卯', '不利而利，无往不利。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4321, '卯', '亲戚无缘，朋友胜亲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4322, '卯', '欢娱度年，万事乃合。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4323, '卯', '父死玄武有变。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4324, '卯', '谢却人间事，常纳祯祥福。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4325, '卯', '所遇老境，优中扰病。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4326, '卯', '举人终身，一生乐事。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4327, '卯', '父不父子不子，中间有个不完妻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4328, '卯', '祯祥叠见阳，无日不从容。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4329, '卯', '长安世上，姓名飘香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4330, '卯', '乡科独步。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4331, '卯', '夫当入泮。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4332, '卯', '财帛莫强求，宽然不用忧。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4333, '卯', '水年克妻，木年再娶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4334, '卯', '假如三场客，今人作故人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4335, '卯', '癸亥拜师方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4336, '卯', '洋江之水伏龙蛇，家室康宁财禄多。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4337, '卯', '超升重任，参于政事。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4338, '卯', '花间酌酒邀明月，石上题诗扫绿苔。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4339, '卯', '夫登科第。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4340, '卯', '事事强扶持，酪酊醉他乡。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4341, '卯', '一点银灯照路来，循循而走问行藏。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4342, '卯', '辟雍成名。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4343, '卯', '一犬一犬又一犬，命重犯刑孤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4344, '卯', '劳心劳力苦奔驰，究竟奔驰力已疲。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4345, '卯', '当贡之期。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4346, '卯', '鼠楼梁上，须忧其耗。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4347, '卯', '夫入伴宫。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4348, '卯', '机会得来事偶然，童年入泮占人先。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4349, '卯', '进取无功，退守为高。', '[41, 42]');
