INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4518, '卯', '数该生子。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4519, '卯', '池荷花，亭亭直上。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4520, '卯', '举头初见太阳升，左右求谋事事成。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4521, '卯', '数年立志鸡窗下，一贡成名得显扬。', '[49, 50]');
