INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4545, '卯', '命入文昌，有学堂份。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4546, '卯', '曲径山蹊，桃源之景。', '[31, 32]');
