INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4600, '卯', '无是无非，随缘度日。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4601, '卯', '辟雍成名。', '[55, 56]');
