INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4619, '卯', '忧喜相逢，愁颜变笑容。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4620, '卯', '未遇其时，莫与有为。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4621, '卯', '夫当登科，晚年之福。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4622, '卯', '职司高爵，事宜项其斟酌。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4623, '卯', '瑞气隆隆，门庭喜庆。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4624, '卯', '辟雍成名。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4625, '卯', '此刻生人必刑妻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4626, '卯', '官至春坊，不能拜相。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4627, '卯', '命拱耀星，职司通政。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4628, '卯', '月缺易圆，镜破难合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4629, '卯', '身带疾厄，解得安。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4630, '卯', '当依贡朝。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4631, '卯', '竟梦黄梁，异乎痛哉。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4632, '卯', '生计庸常，宽然有度。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4633, '卯', '六阴停极，消长不一。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4634, '卯', '身心舒泰，福禄臻。', '[97, 98]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4635, '卯', '运至高强，图谋异常。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4636, '卯', '丁卯之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4637, '卯', '财帛随人来，图谋必周全。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4638, '卯', '夫当入泮。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4639, '卯', '数当此尽。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4640, '卯', '财帛逐日进，物色更从新。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4641, '卯', '新绿枝头可问禅。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4642, '卯', '夫登科第。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4643, '卯', '半作生涯半作田，一生衣禄靠心坚。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4644, '卯', '数该生子。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4645, '卯', '犬当入泮。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4646, '卯', '满园花茂盛，事来称人怀。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4647, '卯', '母先故于木年，父后故于土年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4648, '卯', '两妻生双子，双喜临门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4649, '卯', '一枯一荣，二子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4650, '卯', '夫登科甲。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4651, '卯', '洛阳花似锦，清风送佳音。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4652, '卯', '朝歌夕乐，克享成福。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4653, '卯', '数该生子。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4654, '卯', '妻命属火。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4655, '卯', '春风依旧到江城，又见江城锦绣丛。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4656, '卯', '慕廉颇李牧之风，学孙武直之术。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4657, '卯', '琼林之宴，抢元之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4658, '卯', '当依贡期。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4659, '卯', '让得前头一人口，杏花十里马蹄轻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4660, '卯', '事事添花锦，荣华自可夸。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4661, '卯', '衣钵一身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4662, '卯', '衣钵一身闲，四时尘不染。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4663, '卯', '流年顺遂，谋事有功。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4664, '卯', '朝起遇顺风，随时帆挂到江东。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4665, '卯', '俭约守之犹不足，过而不改其能乎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4666, '卯', '和气洋溢，室家吉庆。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4667, '卯', '朝烟夕霞，转眼淹留。', '[9, 10]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4668, '卯', '只宜守已，不可妄为。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4669, '卯', '日日笑颜开，财通福自来。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4670, '卯', '此刻生人必刑夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4671, '卯', '夫当入泮。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4672, '卯', '一梦归西别阳台。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4673, '卯', '家室安乐，事事更新。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4674, '卯', '谋事有喜意，年来迥不同。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4675, '卯', '夫登科甲。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4676, '卯', '顺水行舟，瞬息千里。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4677, '卯', '喜事祯祥天意来，阴阳调合百花开。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4678, '卯', '稳足无求，往来春秋。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4679, '卯', '夫当入泮。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4680, '卯', '当依贡期。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4681, '卯', '春寒秋热，光景无多。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4682, '卯', '桃红柳绿薏春风。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4683, '卯', '巧利巧利，不逢自达。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4684, '卯', '兄弟怡怡，又入泮宫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4685, '卯', '行到桃源流水处，绿扬阴里任君眠。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4686, '卯', '合杯中浮绿蚁，玉栏杆上醉春风。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4687, '卯', '尘埃掩镜台，母先赴瑶池。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4688, '卯', '新月挂松梢，清风送佳音。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4689, '卯', '早岁平安，将来大垢。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4690, '卯', '春到自然花烂熳，花开随处月光辉。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4691, '卯', '春风依阳到阳城，处处花开锦绣明。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4692, '卯', '退险而夷，逢凶化吉。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4693, '卯', '数刻生子。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4694, '卯', '皓月当空，清光不同。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4695, '卯', '囊中宜检点。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4696, '卯', '金枝玉叶大家女。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4697, '卯', '金枝毓秀，玉树生春。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4698, '卯', '无事无求安乐业。', '[83, 84]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4699, '卯', '事业不专，进三退四。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4700, '卯', '问利三旬之外，取之左右逢原。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4701, '卯', '小小兴家自富，微微立业有成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4702, '卯', '别却阳间长，往西方而短。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4703, '卯', '一生无患处，底事自安然。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4704, '卯', '美貌佳人难共老，琵琶拨出数肠声。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4705, '卯', '年照文昌，领得青衫换布衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4706, '卯', '家无但石之储，忽起万金之富。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4707, '卯', '登山有路，沿级而上。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4708, '卯', '苍松石柏，难免根枯。', '[83, 84]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4709, '卯', '身居翰苑紫微宿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4710, '卯', '一阵暖风，消除寒气。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4711, '卯', '荷花出水，风来飘动不相宜。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4712, '卯', '虽然未遂青云志，姓字终沾雨露深。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4713, '卯', '珠沉沧海，镜破钗分。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4714, '卯', '真假三子，二子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4715, '卯', '虽然未遂青云志，终须国学列诸生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4716, '卯', '二九之年丧，母先天定数。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4717, '卯', '数该生子。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4718, '卯', '晚年暮景宁，无莹独之忧。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4719, '卯', '得上贵之大，可力图其大用。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4720, '卯', '气象峥嵘，门庭赫奕。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4721, '卯', '风雨溟蒙，杨柳失色。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4722, '卯', '子当辟雍。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4723, '卯', '问文无益，问武有余。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4724, '卯', '摇曳轻风，不劳自举。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4725, '卯', '管弦歌里度春风，兆民欢呼乐意浓。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4726, '卯', '擢星相照，非科即道。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4727, '卯', '子当辟雍。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4728, '卯', '年迈五旬，告命相赠。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4729, '卯', '气象峥嵘，门庭赫奕。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4730, '卯', '不劳心力，谋事克济。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4731, '卯', '成家多握掌，立志无息肩。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4732, '卯', '琴瑟调和，一弦忽断。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4733, '卯', '景能无边一一收，春山秋水醉高楼。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4734, '卯', '晚景融融，自作笙歌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4735, '卯', '不须卜甲子，甲子有余零。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4736, '卯', '少乐多忧，常处不足。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4737, '卯', '困于族藜，不见其妻。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4738, '卯', '披麻相照，孝服临身。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4739, '卯', '七八年未有小晦，九十之时日已晴。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4740, '卯', '行人休息绿阴中，前去桃花处处同。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4741, '卯', '出身平常百姓家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4742, '卯', '财多堆积，事多相得。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4743, '卯', '其人数尽，定在十月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4744, '卯', '春到自然花烂熳，秋来随处月光辉。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4745, '卯', '操舟遇风，江心颠倒。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4746, '卯', '父母全死于火年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4747, '卯', '事事添花锦，荣华可富身。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4748, '卯', '门中龙虎，阁上麒麟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4749, '卯', '运至北方地，功名重于时。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4750, '卯', '辛卯之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4751, '卯', '闷苦无事，正可谈经。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4752, '卯', '大道推车，坦然进步。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4753, '卯', '怀抱安舒，际遇相安。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4754, '卯', '大限已尽。', '[85, 86]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4755, '卯', '晚景更高强，东篱黄菊自生香。', '[81, 82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4756, '卯', '再升县令。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4757, '卯', '随取随足，老运安康。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4758, '卯', '年年景色不相同，欢笑声中乐意浓。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4759, '卯', '际会荣景，寅天之福。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4760, '卯', '子当辟雍。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4761, '卯', '正副佳人，欢娱老景。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4762, '卯', '试问寿光何日尽，九旬已上有余年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4763, '卯', '光景非前日，内外总安然。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4764, '卯', '天喜照临，宜室宜家。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4765, '卯', '往来康庄，洋洋自得。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4766, '卯', '龙归大海，虎入深山。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4767, '卯', '春台日永，宝鼎生香。', '[2930]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4768, '卯', '数该生子。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4769, '卯', '妻生命属木。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4770, '卯', '春来万物生，天地造化融。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4771, '卯', '享万年社席之安，释上方焦劳之苦。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4772, '卯', '初任选庶吉，翰林声价值千金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4773, '卯', '文星照命，自然成名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4774, '卯', '母逝父在，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4775, '卯', '疾病相缠，神佑得安全。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4776, '卯', '金谷园中秋色老，繁华洞里世间花。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4777, '卯', '迷场不可入，易散而难聚。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4778, '卯', '走到亲肠，得人指引。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4779, '卯', '萱花茂盛，谁知今日孝服来。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4780, '卯', '娶得相如妇，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4781, '卯', '三更漏尽早收星，便见东方日已明。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4782, '卯', '闲得每相侵，晨昏未得寝。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4783, '卯', '其中有刑克，俱是先天数。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4784, '卯', '子当辟雍。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4785, '卯', '到底赁虚总是空，几度凄凉雨又蒙。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4786, '卯', '散步重山去，山奇水亦奇。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4787, '卯', '年将六秩，破耗其财。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4788, '卯', '登楼未有梯，举步却徘徊。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4789, '卯', '初任守备。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4790, '卯', '爽气生秋色，烦器顿解除。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4791, '卯', '风雨凄凄，桃红柳绿减精神。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4792, '卯', '数该生子。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4793, '卯', '破军星入限，流年有咎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4794, '卯', '仁途变幻，官讼交加。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4795, '卯', '洗净菱花暗锁烟，翻然光景倍光明。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4796, '卯', '芙蓉秋菊，晚景生春。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4797, '卯', '思难图易，事乃克济。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4798, '卯', '莫恨妻儿无缘分，命中惟带一孤神。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4799, '卯', '但遇东方远，功名垂千古。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4800, '卯', '相逢知己言，日日笑颜开。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4801, '卯', '命中注定六女。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4802, '卯', '无是无非，安闲岁月。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4803, '卯', '春入三阳，万物荣昌。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4804, '卯', '拨贡终身，以结一生之局。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4805, '卯', '回也之寿，君亦如之。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4806, '卯', '人度峡山，挣持之力。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4807, '卯', '少年登科。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4808, '卯', '路逢曲径人心迷，视日便知东与西。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4809, '卯', '舟行浅滩，午潮正落。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4810, '卯', '时运未通，事多反复。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4811, '卯', '父无多娶，家门之幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4812, '卯', '月德星临门，庭前嘉气新。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4813, '卯', '渐赌已破，输中难胜。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4814, '卯', '谋事多反覆，大运未遇时。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4815, '卯', '水土之年，纳八品方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4816, '卯', '学纯而粹，气大而刚。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4817, '卯', '谋事皆通，不劳心力也成功。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4818, '卯', '山桥曲转，鼎新路阻。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4819, '卯', '中天物色，照耀光华。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4820, '卯', '寿止于此矣。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4821, '卯', '出水荷花，亭亭直上。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4822, '卯', '其人之亡，定在十一月。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4823, '卯', '财帛破盗耗，无奈天数定。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4824, '卯', '财帛辐暗中来，坦然安乐笑颜开。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4825, '卯', '好花正赏，岂期夜雨又风吹。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4826, '卯', '好事多磨，有情人终成眷属。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4827, '卯', '草色姜萋，东风吹绿。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4828, '卯', '姻缘长短皆前定，月缺花残数不饶。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4829, '卯', '母命水年生，方合此刻。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4830, '卯', '当入泮宫。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4831, '卯', '夫当登甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4832, '卯', '无事平安。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4833, '卯', '子命土年生，方合此刻。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4834, '卯', '全凭筋骨力，断取一生财。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4835, '卯', '绍忠孝传家之宝，干谋略建国之心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4836, '卯', '喜气上眉端，其年事事安。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4837, '卯', '白发遮黄老，银须新紫袍。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4838, '卯', '财散因好博，此地不可乐。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4839, '卯', '数尽于此。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4840, '卯', '犬当入泮。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4841, '卯', '运已从人事，不妨猛图而遂事。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4842, '卯', '韶光荏苒易长生。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4843, '卯', '财帛定有耗，预知免一半。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4844, '卯', '仁义有亏，减寿减禄。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4845, '卯', '阳和春景称人怀，花洒满园次第开。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4846, '卯', '兄弟三人，折了一个。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4847, '卯', '帆遇顺风，瞬息千里。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4848, '卯', '未知袁颜道，不胜又输人。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4849, '卯', '新竹成竿，凌空而上。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4850, '卯', '文星照命，当入泮宫。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4851, '卯', '此日多得成，贵人指引喜盈盈。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4852, '卯', '流年容易度，相遇乐平安。', '[4546]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4853, '卯', '曲路推车，进退两难。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4854, '卯', '依贡终身，以结一生之局。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4855, '卯', '本艺学成归发达，半为生理半为田。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4856, '卯', '喜气盈盈，家室安宁。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4857, '卯', '乡榜题名。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4858, '卯', '风急卷波涛，扁舟已近岸。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4859, '卯', '但行西方运，名就利亦成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4860, '卯', '子命金年生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4861, '卯', '春宵夜长，空闺侧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4862, '卯', '名登金榜。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4863, '卯', '以监而选州官数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4864, '卯', '犬生两口，白染罗巾。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4865, '卯', '风宪行台，得意之时。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4866, '卯', '慎固卦守，以康四海。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4867, '卯', '四字切记：莫失良机。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4868, '卯', '乐事从容，日日笑颜。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4869, '卯', '幼年登科。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4870, '卯', '祸生意外，岂知意外不成空。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4871, '卯', '仗尔辛勤力，依人小利财。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4872, '卯', '勃然而兴，门庭吉庆。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4873, '卯', '财帛破耗，留之不住。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4874, '卯', '不暖不寒，平和景色。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4875, '卯', '楼头砧已无声，滴漏壶中曙色明。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4876, '卯', '癸酉之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4877, '卯', '货殖通名利，资财日发兴。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4878, '卯', '九苞瑞气凤，五色麒麟祥。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4879, '卯', '暖日融融，流光迅速。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4880, '卯', '诗文为生，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4881, '卯', '春风布暖，和气称怀。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4882, '卯', '潇潇洒洒图欢乐，货财耗去悔过迟。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4883, '卯', '财退如潮去，神亦不能资。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4884, '卯', '弃去功名志，朝夕作闲人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4885, '卯', '癸酉之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4886, '卯', '发财凭运至，货物自生辉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4887, '卯', '子木年生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4888, '卯', '听凯歌于载路，嘉卓异于九重。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4889, '卯', '未出胎而亡父，抱天之恨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4890, '卯', '恩星相照，光明福随。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4891, '卯', '为人深怀，修养已到。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4892, '卯', '丁酉之年，鹿鸣宴饮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4893, '卯', '招牌原写公平字，银钱交接便生心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4894, '卯', '财在吾身何等稳，鬼催人睹散如何。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4895, '卯', '王事靡监，不将父。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4896, '卯', '财帛勃发，天意从人。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4897, '卯', '大顺小逆，顺逆不一。', '[40, 41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4898, '卯', '财星居官禄，纳粟成名声。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4899, '卯', '散财无常，雨遇风。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4900, '卯', '数尽于此。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4901, '卯', '朝夕费跨，从劳亦空虚。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4902, '卯', '时运财散，有口不言。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4903, '卯', '数该生子。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4904, '卯', '推车周旋，辗转如意。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4905, '卯', '落落市中，经营限未通。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4906, '卯', '举步皆得意，求谋事事通。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4907, '卯', '雨足郊原草，萌芽尽舒展。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4908, '卯', '融融三月景，姜姜百草芳。', '[77]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4909, '卯', '巨船出大海，布帆无恙挂西风。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4910, '卯', '场中散白壁，因心是贪玩。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4911, '卯', '行舟遇风，无往不利。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4912, '卯', '沉滞不解，两眉强舒。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4913, '卯', '腾腾散财，何耗之速。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4914, '卯', '年华始尽，大数已终。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4915, '卯', '优居稳地，可去无咎。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4916, '卯', '市尘微利好，但恨富难成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4917, '卯', '月出南楼，光明照耀。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4918, '卯', '怀断断休休之度，仕巍巍荡荡之朝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4919, '卯', '锦绣丛中，事乐融融。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4920, '卯', '报晓梦初醒，枝头听鸟鸣。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4921, '卯', '莫道世无神，输钱皆是鬼。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4922, '卯', '寻常同一样，不必别姻缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4923, '卯', '手艺惟精熟，人求福自生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4924, '卯', '淑人君子，其德不渝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4925, '卯', '如鸟伤翼，不能远举。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4926, '卯', '甘雨和风三月天，游人乐无边。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4927, '卯', '未识为人好与丑，但看行事假和真。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4928, '卯', '名登金榜。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4929, '卯', '数有五子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4930, '卯', '月至初弦，其光半掩。', '[81, 82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4931, '卯', '一堆金与银，场中一半入人手。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4932, '卯', '否转为泰事更新，残冬去后有阳春。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4933, '卯', '流年悲星照，破我许多财。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4934, '卯', '明月正当空，弯弯曲曲转西东。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4935, '卯', '到处是追随，祥光映紫微。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4936, '卯', '花落又花开，春风次第来。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4937, '卯', '莫恼繁华不到年，早安淡薄后来荣。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4938, '卯', '退财只为想人财。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4939, '卯', '风紧遇波浪，波浪几番愁。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4940, '卯', '大怀开展，繁华耀目。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4941, '卯', '十事谋来九事空，年年踪迹若飘蓬。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4942, '卯', '官事相探，所为有咎。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4943, '卯', '万里晴空，光明大道。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4944, '卯', '双新辞世在何年，他日哀哉母为年。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4945, '卯', '数该生子。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4946, '卯', '数定有灾缠，神祜度流年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4947, '卯', '谋为顺遂，万事呈祥。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4948, '卯', '高楼擢司，进退而审。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4949, '卯', '原是恨不可，所以退此财。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4950, '卯', '心好事烦，家终朝复。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4951, '卯', '一湾春水，溶溶无穷活计开。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4952, '卯', '天上转星临，试赌散黄金。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4953, '卯', '燕鸟于飞哺，出巢而堪宿。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4954, '卯', '欲东而欲西，心中多少事。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4955, '卯', '日月初光华，宇宙景色新。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4956, '卯', '得失皆前定，已失不须恨。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4957, '卯', '忘想他人财，自己反成破。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4958, '卯', '玉蕴于荆山，未得圭璋选。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4959, '卯', '泉清松影瘦，月白李花香。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4960, '卯', '读书应有分，白发始逢升。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4961, '卯', '四字切记：当机立断。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4962, '卯', '好将善决传儿辈，乐我消闲一片心。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4963, '卯', '饮酒茹荤无我份，数中注定一道人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4964, '卯', '小往大来，中正和平。', '[5960]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4965, '卯', '破耗忽生，数所定也。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4966, '卯', '超升部属，会转京堂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4967, '卯', '阴阳颠倒，财迷场散。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4968, '卯', '极止千红万紫，七零八落。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4969, '卯', '行到桃源流水处，绿杨影里任君眠。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4970, '卯', '劳而有功，能事克济。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4971, '卯', '龙泉利器，淬锋未试。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4972, '卯', '富来有基业，不必费跨。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4973, '卯', '芬芳春将尽，南枝鸟倦啼。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4974, '卯', '火罗入限，流年有咎。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4975, '卯', '父故于木年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4976, '卯', '文章入泮。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4977, '卯', '博绿呼红不是好，定数输了始仿徨。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4978, '卯', '鸟呼树枝上，乘时乐意来。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4979, '卯', '不必问行藏，老运不安康。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4980, '卯', '韶光明媚，物色文章。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4981, '卯', '有利攸往，甘愿如今。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4982, '卯', '华盖相逢刑克重，数定披头去修行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4983, '卯', '物色逢春至，桃源正及时。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4984, '卯', '财帛自然发，运行天凑合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4985, '卯', '莫闲微致恨，只作未闻香。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4986, '卯', '安乐无惊人，舒畅听钟声。', '[86, 87]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4987, '卯', '无祸无灾，明星璀灿。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4988, '卯', '文明之象，时当有为。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4989, '卯', '骨肉相刑，西风洒泪。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4990, '卯', '妻妾子众神仙难，断子仪命世上有。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4991, '卯', '出家除俗累，解脱入空门。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4992, '卯', '官至兵部，以乐终身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4993, '卯', '天祐吉人，乐事有功。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4994, '卯', '幼年行事实难为，逆水行舟又遇风。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4995, '卯', '财帛勃发，谋事凑合。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4996, '卯', '村村花柳，到处吹呼。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4997, '卯', '利物利平，生意兴隆。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4998, '卯', '恩星相照，闺中福随。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (4999, '卯', '重重如关锁，进退不得意。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5000, '卯', '儿女有喜，满门炽昌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5001, '辰', '姊妹二人，木年生方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5002, '辰', '兄弟九人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5003, '辰', '欲借杨枝水，几尘不染心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5004, '辰', '翰林而拜相，老来衣锦还乡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5005, '辰', '灾晦缠身，有犯太岁。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5006, '辰', '先得而后失，秋色更朦胧。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5007, '辰', '水中月色可玩，不可计多无成。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5008, '辰', '积德数注全，兄弟庆同年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5009, '辰', '旱草焦枯，俄然复苏。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5010, '辰', '力能创业耐艰辛，不是萎靡不振人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5011, '辰', '君弃世从此，红尘不沾巾。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5012, '辰', '一日言再日昌。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5013, '辰', '如日之升，如月永恒。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5014, '辰', '兄弟十人，数有六贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5015, '辰', '公平正直，力担重任。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5016, '辰', '人事有不足，日月有盈亏。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5017, '辰', '有子先折，赖孙送终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5018, '辰', '如川之方，可保平安。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5019, '辰', '数有二子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5020, '辰', '徒弟六人，一人送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5021, '辰', '金风一起枝头动，欲渡清溪欠便舟。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5022, '辰', '周道坦坦，进可安全。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5023, '辰', '阳菊生秋色，无日不悠悠。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5024, '辰', '寒山秋浦月，肠断杜鹃声。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5025, '辰', '官至巡抚而致仕。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5026, '辰', '薄伐独，以奏谓公。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5027, '辰', '日进无疆，与时偕行。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5028, '辰', '无语对芳樽，肠断到黄昏。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5029, '辰', '座中无物不清凉，别是人门洞府仙。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5030, '辰', '长江避风波，一水万里长。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5031, '辰', '片时欢娱且相亲，阴暗阴晴无定处。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5032, '辰', '暗中福人庇，终始得安康。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5033, '辰', '事有成局，利禄从心。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5034, '辰', '百尺竿头堪进步，君能辗转莫迟回。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5035, '辰', '一日平再日安。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5036, '辰', '三阳方始泰，君子道亨通。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5037, '辰', '数有三子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5038, '辰', '泰利顺贞，君子攸行。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5039, '辰', '安居思危，凡事顺遂。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5040, '辰', '福享安然，事无阻碍。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5041, '辰', '不枝不求，终日悠悠。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5042, '辰', '门外声豪豪，垂帘不高照。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5043, '辰', '云开日出自光辉，进步前程有渡舟。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5044, '辰', '时有可为，乘机敏锐。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5045, '辰', '富彩日新，位至品卿。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5046, '辰', '一家和气运兴隆，谋事多成财自丰。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5047, '辰', '君子日更新，相逢大吉人。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5048, '辰', '肥马轻裘，少年行乐。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5049, '辰', '浪平风静，正好行舟。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5050, '辰', '平安之福，门庭之器。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5051, '辰', '如饮醇，其味深厚。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5052, '辰', '三边提督，将相威振。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5053, '辰', '进退咸宁，东西有得。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5054, '辰', '德润于身，无往不吉。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5055, '辰', '优游闲岁月，不管落花飞。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5056, '辰', '乘驹干里行，风帆指顾中。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5057, '辰', '利有攸往，昔愿如今。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5058, '辰', '凿井未得泉，弃之而废力。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5059, '辰', '终朝啸傲南窗下，自是羲皇上古人。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5060, '辰', '宜享日前福，莫虚日后忧。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5061, '辰', '享其寿福，自在逍遥。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5062, '辰', '有弓无箭，欲射不能。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5063, '辰', '沟中有深味，不与别人同。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5064, '辰', '龙剑出尘射斗牛，财源辐利亨通。', '[50, 51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5065, '辰', '人有福泽前生定，不必迟疑自己行。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5066, '辰', '君子受祯，其旋元吉。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5067, '辰', '碑而富贵，昌且大吉。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5068, '辰', '君子日更新，相逢大吉人。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5069, '辰', '衣禄丰盈，室家安宁。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5070, '辰', '满目韶光观不尽，一旦无常作故人。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5071, '辰', '终日经营，吉利相从。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5072, '辰', '心闲身乐，宜室宜家。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5073, '辰', '独守孤灯，心步月疏。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5074, '辰', '凤凰来仪，祯祥之兆。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5075, '辰', '皇道荡荡，君子贞吉。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5076, '辰', '不为世所累，享平安之福。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5077, '辰', '萱花先萎，椿树后折。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5078, '辰', '绿竹骑猗，清风明月。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5079, '辰', '视履考祥，其旋元寺。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5080, '辰', '际遇亨通，所谋皆遂。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5081, '辰', '荷花出水，亭亭玉立。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5082, '辰', '东处得来西处失，得失不一。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5083, '辰', '泪欲尽时人难语，情关骨肉恨如何。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5084, '辰', '官至将军禄位高，光前裕后显富豪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5085, '辰', '原来无事费心机，还是君家运未齐。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5086, '辰', '忽然而贵忽然贱，运有高低月缺圆。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5087, '辰', '欲作表心福，清晨一柱香。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5088, '辰', '鸠一声鹃一声，鸠鹃好伤情。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5089, '辰', '母先故于金年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5090, '辰', '三子送老，一枝挺秀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5091, '辰', '大人豹变，文人之炳。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5092, '辰', '数有四子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5093, '辰', '忽闻鹊噪两三声，声里藏凶未有音。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5094, '辰', '既往蹉跎，将来顺利。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5095, '辰', '鱼游涸辙，但望时雨而升阳。', '[55, 56]');
