INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5097, '辰', '何时方可得见非，无是也无非。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5098, '辰', '东风初送暖，春草绿生光。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5099, '辰', '数有五子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5100, '辰', '兄弟九人，数有六贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5101, '辰', '贤惠迪吉，随从逆凶。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5102, '辰', '波浪虽高，孤舟系得牢。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5103, '辰', '人事从容，家门迪吉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5104, '辰', '数有六子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5105, '辰', '官至都统，威权重职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5106, '辰', '亭午日光，文明之象。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5107, '辰', '兄弟八人，数有七贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5108, '辰', '礼文章，温良得度。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5109, '辰', '兰亭修高，贤醉寻花乐。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5110, '辰', '指挥如意待时亨，万物峥嵘福自随。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5111, '辰', '借问一生身外事，遇虎之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5112, '辰', '无福无灾，安身福来。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5113, '辰', '靡芜秋色，一阳初动便生芽。', '[41, 42]');
