INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5115, '辰', '机会相从，安康惟兆。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5116, '辰', '数有七子，一子送老。', NULL);
