INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5125, '辰', '入限无关，津江寂寞断行人。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5126, '辰', '狡兔投林，灾晦相侵。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5127, '辰', '幼年入泮，人生大幸。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5128, '辰', '学礼学诗，知东道西。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5129, '辰', '事未可料当，因祸而得福。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5130, '辰', '天哭催人，刑克老母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5131, '辰', '官至总河而致仕。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5132, '辰', '数有九子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5133, '辰', '朝欢暮乐及歌诗，鼓舞春风又及时。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5134, '辰', '此年丧母，二年泣血。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5135, '辰', '计功图利，得失相兼。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5136, '辰', '时运称怀，顺福自来。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5137, '辰', '化日舒长，人民乐意。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5138, '辰', '数有十子，一子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5139, '辰', '民安物阜咸，均平人得全。', '[55, 56]');
