INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5141, '辰', '老年丧母，三年泣血。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5142, '辰', '吉利相从，鸢飞鱼跃。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5143, '辰', '情疏种有年，疾风莫相催。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5144, '辰', '徒弟四人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5145, '辰', '无是无非，安闲岁月。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5146, '辰', '无本生意，厚福悠悠。', NULL);
