INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5148, '辰', '命与道相同，独子送终天注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5149, '辰', '入户春风送和气。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5150, '辰', '一举成名，天降麟儿。', '[29, 30]');
