INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5289, '辰', '计事无功破局多，十无一就其奈何。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5290, '辰', '武曲照命，三场中选。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5291, '辰', '青云得路，天赐佳儿。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5292, '辰', '解神相见喜和同，凶曜消除福正隆。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5293, '辰', '闺中未消停，重云日闷沉沉。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5294, '辰', '事事称心怀，无日不精神。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5295, '辰', '年来寿运增，好景清净吉。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5296, '辰', '名登金榜。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5297, '辰', '南北东西无不通，往来无事福相从。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5298, '辰', '流萤有光，可以照路。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5299, '辰', '借民财以克已，立刑法以行宽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5300, '辰', '数有五子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5301, '辰', '兄弟二人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5302, '辰', '如花不久，徒增父母悲。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5303, '辰', '名登金榜。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5304, '辰', '扫尽风云一占无，中天高照有金星。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5305, '辰', '飞来横祸恼人怀，恨未无情有破财。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5306, '辰', '仕途变幻，官讼莫加。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5307, '辰', '心事安闲，家室康宁。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5308, '辰', '方当壮年，及时猛进。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5309, '辰', '灯光明朗照人行，步步周旋事不惊。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5310, '辰', '衣服饶足，心安意稳。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5311, '辰', '好树扶疏衬绿阴，行人至此慢消停。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5312, '辰', '数该生子。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5313, '辰', '数有六子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5314, '辰', '进退维谷，祸相逐阻。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5315, '辰', '妻配兔命，方得偕老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5316, '辰', '是非虽有财也有，等闲一梯上高楼。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5317, '辰', '年值半旬，啾唧不免。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5318, '辰', '数有七子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5319, '辰', '五子原全属五行，二土二金一火真。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5320, '辰', '十月怀胎，我多一月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5321, '辰', '数有八子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5322, '辰', '祖宗植根深，子当发富贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5323, '辰', '曳据豪门，兼收名利。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5324, '辰', '一树梨花白玉开，妒风吹下落楼台。', '[59]');
