INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5334, '辰', '退而结网自，不必临渊羡有鱼。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5335, '辰', '扰扰怀多事，得五而退十。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5336, '辰', '科甲及第。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5337, '辰', '年来与甲岁不同，内外熙熙乐意浓。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5338, '辰', '当谐鸾凤，如鱼得水。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5339, '辰', '红鸾相照，洞房花烛。', NULL);
