INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5348, '辰', '注定三子属水土，儿若值木不为福。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5349, '辰', '饮酒食肉，天与之福。', '[77, 78]');
