INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5404, '辰', '黄花逢老景，犹有晚节香。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5405, '辰', '鸟鸣声，春风赖有情。', '[19, 20]');
