INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5419, '辰', '好花离枝，妒雨相催。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5420, '辰', '六旬加八载，一去料不回。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5421, '辰', '日圆月缺恨无常，人事浮沉没主张。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5422, '辰', '妻命属土金年娶，其后已丧在水年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5423, '辰', '醉酒寻花，赏心乐事。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5424, '辰', '一别亲朋万古愁，青山绿水空悠悠。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5425, '辰', '春光明媚，物色更新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5426, '辰', '劝君勤习读诗文，莫将技艺浪青春。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5427, '辰', '柳媚花明，赏心乐事。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5428, '辰', '一点银灯暗处飞，若明若暗照庭门。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5429, '辰', '化纸为宝，无所祈祷。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5430, '辰', '短命之儿已有友，其后土年倾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5431, '辰', '灾晦相侵，流年之咎。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5432, '辰', '数有十子，六子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5433, '辰', '家业兴隆，运至时通。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5434, '辰', '山川之毓秀，莹润掌中珠。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5435, '辰', '守定钱库，毫厘不失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5436, '辰', '雁许河东过齐田，入梦相让退一环。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5437, '辰', '足高楼上，更上一层楼。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5438, '辰', '双双鸿雁翱翔飞，一生立在松顶尖。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5439, '辰', '短命之儿已有友，其后土年倾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5440, '辰', '历险崎岖路坦夷，前程指引可行车。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5441, '辰', '不疾不徐，从容马啼。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5442, '辰', '数有八子，七子送终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5443, '辰', '乌云一卷见青天，日色融融花正妍。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5444, '辰', '结交非其人，不但初心负', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5445, '辰', '莲花映日色，自是不寻常。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5446, '辰', '功名事就，福享余年。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5447, '辰', '好运初转，人能造福。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5448, '辰', '驿丞之职，数内先知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5449, '辰', '旭花天时便凋残，恨杀无情风雨催。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5450, '辰', '老骥伏，志在千里。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5451, '辰', '谋事顺意，动止安详。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5452, '辰', '始终好事得周旋，今年行事理先年。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5453, '辰', '行船走马防风浪，不是人差命亦差。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5454, '辰', '寿享八旬，悠悠而往。', '[80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5455, '辰', '云开山色丽，风静竹枝安。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5456, '辰', '南北东西无不通，往来有利得相从。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5457, '辰', '妻当出家，数内先知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5458, '辰', '子许一丁先抱女，原来有数定先知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5459, '辰', '老骥伏枥，志在千里。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5460, '辰', '数有九子，七子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5461, '辰', '森森玉树庭前立，满院桂花晚节香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5462, '辰', '绿树阴浓夏日长，凉亭轩爽荷香。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5463, '辰', '曾戴日月山，家本不了局。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5464, '辰', '金木土火成五子，惟是水命不宜儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5465, '辰', '数有九子，六子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5466, '辰', '萱花阴庇得长年，椿树风吹定在先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5467, '辰', '皓月澄清，千里一碧。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5468, '辰', '天心来复转三阳，黄道初出日渐长。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5469, '辰', '细雨微微霏，似有似无泾人衣。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5470, '辰', '乐事人怀，祯祥福来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5471, '辰', '无是无非，三春花柳。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5472, '辰', '景色快人情，垂杨遍绿阴。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5473, '辰', '复任守备。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5474, '辰', '子丧严亲，随母从人。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5475, '辰', '数中不幸，父母死于非命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5476, '辰', '运有乖违，花枝风雨催。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5477, '辰', '禅门自有春光景，寒气侵人未及回。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5478, '辰', '老骥伏，志在千里。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5479, '辰', '月光千里照人行，夜色灯青到处明。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5480, '辰', '水火相刑，落水复生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5481, '辰', '萱花经霜萎，妒雨又相催。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5482, '辰', '春到南枝，白有微阳相应熙。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5483, '辰', '天哭催人，老母虽故而有寿。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5484, '辰', '秋声听鹿鸣，又兆熊黑庆。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5485, '辰', '为问仕途人，不知林下泉。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5486, '辰', '数有不幸，母嫁作尼姑。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5487, '辰', '如花开处锦披霞，院宇精华是丽华。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5488, '辰', '弄折桂枝，子今同恨。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5489, '辰', '权望照命，巡职甚任。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5490, '辰', '整顿笙歌会，春暖日融融。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5491, '辰', '数该生子。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5492, '辰', '飞狂为思又为灾，啾唧无端水破财。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5493, '辰', '凶星不侵，流年之庆。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5494, '辰', '朱雀绕户，破害相侵。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5495, '辰', '人生七十古来稀。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5496, '辰', '数生九子，七子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5497, '辰', '水年科甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5498, '辰', '晦气侵人，禅房冷淡。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5499, '辰', '快足无求，老景悠悠。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5500, '辰', '无意栽花花正发，易成易立不消停。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5501, '辰', '断弦之悲。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5502, '辰', '终日持竿不得鱼，江中风雨草萎萎。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5503, '辰', '走遍江山又是关，道途涉事又艰难。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5504, '辰', '南柯太守梦正长。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5505, '辰', '不明不暗，有情无遂。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5506, '辰', '大数已定，何必复问。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5507, '辰', '一程又一程，无处不阳春。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5508, '辰', '三阳回万象，幽谷自生春。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5509, '辰', '锦似河阳院里花，春风到处映荣华。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5510, '辰', '名花锦色，可堪人意。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5511, '辰', '酒醉复醒，优乐同行。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5512, '辰', '行乐顺境，吉利相得。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5513, '辰', '所求不遂，进当复退。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5514, '辰', '初授狱官，事宜斟酌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5515, '辰', '花开遇雨无颜色，月明还被黑云遮。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5516, '辰', '初阳出云表，曜色照堂前。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5517, '辰', '谋未成时天欲催，成成如寄福白云。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5518, '辰', '土年配夫金年克。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5519, '辰', '南极吉星临，喜气到门庭。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5520, '辰', '翩翩五子属金星，若中海金终须去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5521, '辰', '此刻生人，萱花犹茂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5522, '辰', '姐象慈母，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5523, '辰', '赋性刚直，仁心仁慈。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5524, '辰', '福来不必求，安然得悠悠。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5525, '辰', '屈贾于长沙，时之未遇时。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5526, '辰', '昔日徘徊有不前，今日快马再加鞭。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5527, '辰', '入山樵木，得地得财。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5528, '辰', '命主刑夫，出家而能寿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5529, '辰', '子有四位木火土，纵有炉火生而去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5530, '辰', '蝶宿花房愁难语，自怜春去几时回。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5531, '辰', '青去得路，天赐佳儿。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5532, '辰', '喜自天来，无心之处得逢财。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5533, '辰', '怡情泽畔心如镜，栖迟衡门每赋诗。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5534, '辰', '进三退四却为何，眼下迟疑反覆多。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5535, '辰', '春花正好游，饮酒乐忘忧。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5536, '辰', '春花冉冉，物色更新。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5537, '辰', '难之又忽易，转便饶生计。', '[22, 23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5538, '辰', '子早妻早，人生大幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5539, '辰', '意外烦恼之忧。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5540, '辰', '春色无恨锦丛中，花鸟相亲事不同。', '[56, 57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5541, '辰', '喜有五子火土金，若生木命主灾运。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5542, '辰', '官至参政，仕途变幻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5543, '辰', '珠玉金屋，享福过人。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5544, '辰', '兄弟俱出家，原来有数定先知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5545, '辰', '借用无成，时之未遇。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5546, '辰', '大运既亨，相时而动。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5547, '辰', '圆转而用环不穷，一歌一曲笑春风。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5548, '辰', '一子不见，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5549, '辰', '问子三旬外，得之始方贵。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5550, '辰', '枯苗得雨，勃然而兴。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5551, '辰', '此年数尽。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5552, '辰', '静中心地泰，春色上眉端。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5553, '辰', '莫道秋容花冷淡，春风遥送暗香来。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5554, '辰', '时不至兮运不通，拾得黄金变作铜。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5555, '辰', '只好安闲家里坐，岂知门外闹声嚣。', '[7980]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5556, '辰', '八旬未足，何竟归西。', '[79]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5557, '辰', '职居丞驿，禄多事烦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5558, '辰', '福禄无空，终须常有。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5559, '辰', '财破而免灾，不幸中有幸。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5560, '辰', '城墙之上挂灯笼，诸事亨兮财自亨。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5561, '辰', '云中月，雨中花。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5562, '辰', '镜与人去，镜归人不归。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5563, '辰', '才大难为用，婆婆两鬓明玉梦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5564, '辰', '丰衣足食，锦绣之花。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5565, '辰', '生子之年。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5566, '辰', '家室康宁，平安之庆。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5567, '辰', '借问一生身外事，遇鸡之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5568, '辰', '芳草姜姜春正深，遍郊红绿称人怀。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5569, '辰', '三军司令威权重，细柳营中主帅明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5570, '辰', '无物不从容，乐于管弦中。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5571, '辰', '徒弟四人，二人送老。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5572, '辰', '清闲无事，啸傲林中。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5573, '辰', '一团冷气透菩提。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5574, '辰', '牡丹开得正荣华，胜意当年千万家。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5575, '辰', '夫命属土，配年火丧夫年木。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5576, '辰', '羡君今日促离妆，惟向当年快有常。', '[79]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5577, '辰', '春花秋月，无不欢欣。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5578, '辰', '四儿原来水火土，金木纵饶不与数。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5579, '辰', '赤日空红色逐，绿柳深处得停车。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5580, '辰', '不图宫殿扳丹桂，只效肖曹更名扬。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5581, '辰', '嫡母所生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5582, '辰', '红灯照路，行人去复无徘徊。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5583, '辰', '不幸严君先辞世，幸逢母命寿元长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5584, '辰', '国有绵长庆，民增纯休。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5585, '辰', '秋风落叶，暗自消然。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5586, '辰', '不劳其心力，安享其冰福。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5587, '辰', '风风雨雨恨无凭，桃红柳绿损精神。', '[7]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5588, '辰', '乡试中选。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5589, '辰', '有子传家真富足，闲评棋局醉春风。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5590, '辰', '灾晦相侵，流年不利。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5591, '辰', '闷然不乐，雷雨交加。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5592, '辰', '清晨鸦鹊噪，凶报不可闻。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5593, '辰', '夏雨初晴看白莲，亭亭欲立小池边。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5594, '辰', '惟笑时光，春风海棠。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5595, '辰', '马未铺鞍，高低盘桓。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5596, '辰', '弹断瑶琴丝，其限有刑伤。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5597, '辰', '花开遇雨，人生有难。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5598, '辰', '兄弟五人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5599, '辰', '兵甲于胸中，经论于掌上。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5600, '辰', '车帷暂驻，其栽遥临。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5601, '辰', '畅快宽舒，往来垣夷。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5602, '辰', '曲道推车，进退两难。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5603, '辰', '马到坡，车必出辙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5604, '辰', '丹桂花香，秋风扫落。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5605, '辰', '异路功名，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5606, '辰', '豺狼当道，不宜前进。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5607, '辰', '马走危途，回道蹉跎。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5608, '辰', '福寿绵绵九十八，试看往脚少三春。', '[95]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5609, '辰', '九九之年数已尽，幽冥魂魄入泉中。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5610, '辰', '既载以功，车服以庸。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5611, '辰', '冯驭未老，买信有期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5612, '辰', '命犯孤鸾奈若何，甘心淡薄为尼姑。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5613, '辰', '兄弟四人，一人过房。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5614, '辰', '土命水命子其后，木年水年去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5615, '辰', '异路功名，吏员可喜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5616, '辰', '官至监司，数已注定。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5617, '辰', '五台星照，任推尚书。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5618, '辰', '无物不从容，乐于管弦中。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5619, '辰', '昨夜朔风高，江山千里过琼瑶。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5620, '辰', '人有偏财，命有福禄。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5621, '辰', '藤有蔓延花，破财两相牵。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5622, '辰', '婉转随时，得合中意。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5623, '辰', '父当出家，数内先知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5624, '辰', '有梯有板，高楼直上不难。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5625, '辰', '停步东风里，郊原处处香。', '[5, 6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5626, '辰', '凶神得解福星狭，祸自消除福自来。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5627, '辰', '朝云朝来，财聚财散。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5628, '辰', '数到头来总是空，金银财宝化为铜。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5629, '辰', '脱绝牵绳，举步轻便。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5630, '辰', '六旬欠二人冥乡，虽效孔明礼斗难。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5631, '辰', '耕田贸易两相宜，运好两般皆生计。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5632, '辰', '运至时通，事皆得意。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5633, '辰', '风清月朗，情怀畅怀。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5634, '辰', '龙泉利器，淬锋未试。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5635, '辰', '决外烦恼忧，赖有吉神解。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5636, '辰', '三子送老，贤愚不等。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5637, '辰', '春风绮罗，翻翻得意。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5638, '辰', '松筠节操，天赐其麻。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5639, '辰', '戊戊之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5640, '辰', '双喜临门，弄璋采芹。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5641, '辰', '杨花飞柳花飞，春深寂莫鸟不啼。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5642, '辰', '无祸无灾，安居福来。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5643, '辰', '饱暖无求乐，轻风送小舟。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5644, '辰', '锦乡堂中列绮筵，暖风相送鸟声和。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5645, '辰', '彩云照耀，画堂春色。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5646, '辰', '仁心仁慈，尽善尽美。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5647, '辰', '此命出于偏房方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5648, '辰', '天理常存，年岁始尽。', '[88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5649, '辰', '再任知州。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5650, '辰', '富极无高，以尽人间福。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5651, '辰', '出门无所求，求之皆遂意。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5652, '辰', '生子之年。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5653, '辰', '晦里照命，室中有损。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5654, '辰', '甲辰之年，名登金榜。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5655, '辰', '子许三丁先抱女。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5656, '辰', '大耗小耗，破财遇盗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5657, '辰', '财帛福具备，子孙满画堂。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5658, '辰', '三春杨柳正绿阴，又防风雨打枝头。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5659, '辰', '玲珑台阁备，壮丽之观景。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5660, '辰', '晴风暑气消，日头上梢头。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5661, '辰', '月缺恐难圆，浮云蔽目前。', '[79]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5662, '辰', '兄弟死于非命。', '[79]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5663, '辰', '娶妾之年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5664, '辰', '赌搏中年改，福禄自天来。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5665, '辰', '借问一生身外事，遇龙之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5666, '辰', '崎岖误行人，东西南北不差分。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5667, '辰', '得授序班，何等光辉。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5668, '辰', '一字切忌日白，当止则止。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5669, '辰', '年当耳顺，佐理国政。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5670, '辰', '暖风正熏人，桃李正妍新。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5671, '辰', '中馈人忘，心怀寂寞。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5672, '辰', '花遇阳春逢泰运。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5673, '辰', '行年不惑，大限已终。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5674, '辰', '滞而不明，萎花蒙尘。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5675, '辰', '寒滞侵入，流年欠顺。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5676, '辰', '无祸无灾，明星灿灿。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5677, '辰', '财帛难入手，从有便消磨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5678, '辰', '安享祖荫，恩隆把总。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5679, '辰', '前妻生一子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5680, '辰', '鸿雁一群展双翅，抢得一巢栖。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5681, '辰', '一朵萱花晓色寒，霜飞冷落玉栏杆。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5682, '辰', '常因妻忧，快然安舒。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5683, '辰', '真假八子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5684, '辰', '居安思危，思则有备。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5685, '辰', '富贵之有余，春风模样丽人居。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5686, '辰', '静中心地泰，人事得安舒。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5687, '辰', '风吹椿树折，三年泣血。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5688, '辰', '其人之亡，定在四月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5689, '辰', '名登金榜，老来之荣。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5690, '辰', '明月上弦，其光渐圆。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5691, '辰', '妻配牛命，可许谐老。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5692, '辰', '兔走鸟飞，背换布衣。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5693, '辰', '和气近人，雅至相得。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5694, '辰', '庚辰年科甲及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5695, '辰', '真假四子，三子送老。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5696, '辰', '数该生子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5697, '辰', '道尔兹基，不如乘时耕作。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5698, '辰', '父寿白头，孝子上山。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5699, '辰', '丰衣足食，家中乐意。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5700, '辰', '明月照闺中，家庭承露浓。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5701, '辰', '气象温和，量大度阔。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5702, '辰', '乐事从容，处处风光。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5703, '辰', '来来往往，难期一遇。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5704, '辰', '坦道无碍，驰驰可前。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5705, '辰', '职居固山，一旗之主。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5706, '辰', '守定根基启后人，后人昌盛旧还新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5707, '辰', '大小咸臻祸不侵。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5708, '辰', '班马文章才独擅，实从理学渊源家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5709, '辰', '事就且高歌，饮酒舞婆娑。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5710, '辰', '严亲早丧，人子不幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5711, '辰', '事事从容怀抱宽，金风一阵生寒。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5712, '辰', '异路功名，得授典史。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5713, '辰', '财积如山福自生，春风花满洛阳城。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5714, '辰', '步履皆平坦，何必问风波。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5715, '辰', '用心凿石才成玉，着意淘沙始见金。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5716, '辰', '乐意称人怀，祯祥福自来。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5717, '辰', '萱花时遇光，浓雨又来催。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5718, '辰', '气宇宏深，神机伟俊。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5719, '辰', '无日不春风，胸中事不穷。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5720, '辰', '锦绣喜重重，花开满园红。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5721, '辰', '妻早子早名利迟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5722, '辰', '椿萱并茂在堂前，他日终然父命坚。', '[79]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5723, '辰', '以监面选县丞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5724, '辰', '盘桓而进，守以中正。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5725, '辰', '财帛积有余，安然得安居。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5726, '辰', '青宫沉马，致仕还乡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5727, '辰', '数该生子。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5728, '辰', '儿孙满目绕堂前，寿如松柏福南山。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5729, '辰', '挺眉幸有人，人可差强人。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5730, '辰', '火罗入限，流年有咎。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5731, '辰', '流年灾不侵，内外得安居。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5732, '辰', '白虎在门，灾毒不免。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5733, '辰', '再娶生一子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5734, '辰', '甲戌之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5735, '辰', '官至知府，不能高摧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5736, '辰', '颠倒无常今有常，行人一夜过羊肠。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5737, '辰', '笃志寒窗年又年，名利宫谢平安。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5738, '辰', '人如醉梦醒，方觉其外还。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5739, '辰', '学识两全，犹如渊源。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5740, '辰', '云收雨过，日月光明。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5741, '辰', '事得所欲，无为不足。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5742, '辰', '当谐鸾风，如鱼得水。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5743, '辰', '恶曜攻身，须防危险。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5744, '辰', '真假五子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5745, '辰', '飞符夹死符，啾唧总不宜。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5746, '辰', '时进时退，天道循环。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5747, '辰', '喜事可以，逍遥悠悠。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5748, '辰', '半夜潮生犬不惊，但得财聚又成名。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5749, '辰', '该生一子。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5750, '辰', '苦功用尽脑，泮水自生香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5751, '辰', '福禄褪人，健旺精神。', '[7980]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5752, '辰', '椿树已成风木恨，难免三年泣血悲。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5753, '辰', '谋事有人成，得意马蹄轻。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5754, '辰', '事事从容怀抱宽，金风送暑得清凉。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5755, '辰', '东西路可通，行船遇顺风。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5756, '辰', '浮云卷尽月重明，灾晦消除福自生。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5757, '辰', '坚木皎结，舟倾中流。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5758, '辰', '恶曜攻身，须防危险。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5759, '辰', '浓霜连夜落，萱花被凋残。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5760, '辰', '居官不如居家，治国不如治家。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5761, '辰', '事得所欲，无所不足。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5762, '辰', '硕人堪赋，裘马翩翩。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5763, '辰', '父先母后，抱天之恨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5764, '辰', '名登黄甲。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5765, '辰', '祖业不靠，自创家园。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5766, '辰', '数定室入难共老，琵琶拨断听弦声。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5767, '辰', '孤舍猿啼，令人恐惊。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5768, '辰', '我生不辰，今年丧父。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5769, '辰', '正妻从未得结子，娶得偏房许生儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5770, '辰', '百日竿头，如日中天。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5771, '辰', '马走高低路，反复多回轩。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5772, '辰', '才得圆时又复亏，循环不一。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5773, '辰', '犬吠皇皇，名进宫墙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5774, '辰', '子规啼落楼台月，一枕鸳鸯梦不成。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5775, '辰', '纸窗因迪破，名花恨雨催。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5776, '辰', '不遇之遇，物饶生趣。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5777, '辰', '参领一旗，干城之选。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5778, '辰', '娶得妻时即便离，命是刑克有何医。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5779, '辰', '前妻生二子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5780, '辰', '福禄来时不用求，在前在后总悠悠。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5781, '辰', '花甲已凋尘世隔，不能回产见阳人。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5782, '辰', '禅室庆长春，无奈多风雨。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5783, '辰', '大小长健，春光无限。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5784, '辰', '恩星照命，官职高升。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5785, '辰', '春满洛阳城，高低锦绣丛。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5786, '辰', '有得有失，事多反覆。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5787, '辰', '空门无虑谷，不免是非来。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5788, '辰', '山路崎岖，一步高来一步低。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5789, '辰', '全不费精神，生涯得称心。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5790, '辰', '言行不谨慎，是非而破财。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5791, '辰', '配得金水之夫，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5792, '辰', '太平无事，悠悠顺意。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5793, '辰', '时通时赛，或进或退。', '[50, 51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5794, '辰', '所谋不合，图之何益。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5795, '辰', '而今燕喜连绵至，柳絮栎花共一园。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5796, '辰', '经谈松树下，得意月长明。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5797, '辰', '有经营之才，无经营之运。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5798, '辰', '风云一时新，桃花柳絮青。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5799, '辰', '泽萼桃蕊初，春风草欲青。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5800, '辰', '过步而周旋，春风备马鞭。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5801, '辰', '幼年失，父母双亡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5802, '辰', '破耗虽不幸，失中方人得。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5803, '辰', '将军功成，耀祖扬宗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5804, '辰', '幼年行乐，无日不悠。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5805, '辰', '协领之职，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5806, '辰', '严父早折，母又重婚。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5807, '辰', '日色融融，几度清风。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5808, '辰', '借问一生身外事，遇猴年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5809, '辰', '玉折兰催，古今同根。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5810, '辰', '一字切忌日金，利在其中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5811, '辰', '乡科中选。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5812, '辰', '一盏余灯烟未消，金风依旧异香飘。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5813, '辰', '妻配鼠命，方能白首飞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5814, '辰', '莲花晓日色，自是不寻常。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5815, '辰', '一片白云飞转过，蟹未行见晴明。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5816, '辰', '忧疑自转，欢喜中来。', '[3738]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5817, '辰', '前妻生三子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5818, '辰', '年年事事通，内外喜欢福自隆。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5819, '辰', '佩玉锵锵，童年厚福。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5820, '辰', '一父三母，独继香灯。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5821, '辰', '牡丹吐秀，有女如男。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5822, '辰', '事得谐合，不劳心力便成功。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5823, '辰', '富贵黄金比石崇，鼎新事业福兴隆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5824, '辰', '乍合乍离，愧见鸳鸯鸟。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5825, '辰', '意外调和，鼓舞婆娑。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5826, '辰', '暖气洋洋溢，春风色融融。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5827, '辰', '太岁有情，自然逢凶化吉。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5828, '辰', '闺中又无求，快乐得悠悠。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5829, '辰', '初授县丞之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5830, '辰', '十月怀胎，生我欠一。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5831, '辰', '外似风光内实愁，许多不足在心头。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5832, '辰', '名登科甲。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5833, '辰', '前妻生四子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5834, '辰', '枯荣得失皆前定，何必尤怨不如人。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5835, '辰', '名之不可求，求之彼阻悔无休。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5836, '辰', '超升知县。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5837, '辰', '灼灼桃花天，丽色如锦绣。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5838, '辰', '日正当午，光明浩大。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5839, '辰', '数该生子。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5840, '辰', '拙守有不足，韩信未遇时。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5841, '辰', '镊钵花开，菩提叶茂。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5842, '辰', '再娶生二子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5843, '辰', '补任半吉实难凭。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5844, '辰', '补授知府之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5845, '辰', '数到头来不自由，白云千岁空悠悠。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5846, '辰', '得意防失意，辗转无凭据。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5847, '辰', '数有五子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5848, '辰', '虑事而动，动而不藏。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5849, '辰', '袜履悠悠，家门清吉。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5850, '辰', '一生衣禄足，富厚享荣华。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5851, '辰', '一夕金风，烦暑顿除。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5852, '辰', '乡试中式。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5853, '辰', '人事和平，画堂彩色。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5854, '辰', '月光初缺处，稍稍减夜明。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5855, '辰', '光曜三台，高升禄位。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5856, '辰', '此刻生人，堂前双亲并茂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5857, '辰', '何时志忧疑，然后亨安舒。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5858, '辰', '昔日根基今日消，根基非倚旧时依。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5859, '辰', '前妻生五子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5860, '辰', '事无牵累，终日悠悠得意。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5861, '辰', '心力交，空叹奈何。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5862, '辰', '光风霁月，鼓舞婆娑。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5863, '辰', '勾滕照命，牵害交加。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5864, '辰', '出则安居，入则安舒。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5865, '辰', '再娶生二子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5866, '辰', '时雨遍效原，万物尽沾恩。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5867, '辰', '发妻伴终身，福禄怡怡随。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5868, '辰', '其从之亡，定在六月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5869, '辰', '正满九旬，大数已定。', '[90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5870, '辰', '千里风光，万里悠悠。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5871, '辰', '数该三子。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5872, '辰', '宝撞重磨，依旧光辉。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5873, '辰', '辉煌之害，衍业之荣。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5874, '辰', '嫩竹独竿已透墙，会看指日拂云长。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5875, '辰', '前夫生木子，后夫生金儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5876, '辰', '大往小来，君子未遇。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5877, '辰', '儿孙满目，席前舞斑斓。', '[87]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5878, '辰', '红鸾相照。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5879, '辰', '财帛虽有余，到老多劳苦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5880, '辰', '中年戒淫，晚年安舒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5881, '辰', '兄土年生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5882, '辰', '春花秋月，无不堪夸。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5883, '辰', '机会不来，进三退四。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5884, '辰', '再任州官。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5885, '辰', '运来有笑容，处处遇春风。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5886, '辰', '破耗不能，皆因耗入运。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5887, '辰', '人生不幸，泣血三年。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5888, '辰', '百花解云，万卉争妍。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5889, '辰', '丁未之年，进士及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5890, '辰', '财在场中去，耗星突然来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5891, '辰', '醉鬼无时间。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5892, '辰', '吹花遍碎锦，拂起簇烟波。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5893, '辰', '财帛破耗，急急回头。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5894, '辰', '流年顺利，春花笑日。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5895, '辰', '姐水年生方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5896, '辰', '小水滩头阻去舟，徒然费力莫追求。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5897, '辰', '鬼怪出相侵，凡事三思休可疑。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5898, '辰', '宽洪其性，温柔莫并。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5899, '辰', '云开日现，风静波平。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5900, '辰', '仍然不守温公训，致令场中散货财。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5901, '辰', '若问寿元事，六旬加四是归期。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5902, '辰', '此刻生人男可拈花，女可惹草。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5903, '辰', '更漏残报已开明，月落星疏早晓行。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5904, '辰', '小富得从动处积，数注其人得黄金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5905, '辰', '升选知州。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5906, '辰', '五六有破财，运去耗星徘。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5907, '辰', '无心福自来，春风有意好花开。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5908, '辰', '辛丑之年，名登黄甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5909, '辰', '清波有舟，而登彼岸。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5910, '辰', '异路功名，再授主簿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5911, '辰', '心间得安舒，欣然福自如。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5912, '辰', '居安思危，思则有备。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5913, '辰', '燕子分飞，春深桃李。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5914, '辰', '虚名虚利百无成，浪迹萍踪已半生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5915, '辰', '官至州判，不能高擢。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5916, '辰', '祸患而自取，举尔有虚惊。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5917, '辰', '南楼惟报三更月，半夜子规尚且啼。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5918, '辰', '洛阳三月景，楼台柳阴丛。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5919, '辰', '徒弟五人，四人送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5920, '辰', '物色更新，锦乡上林。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5921, '辰', '财去财来不可悲。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5922, '辰', '再任把总。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5923, '辰', '耗星入限，不赌何散。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5924, '辰', '整顿离妆，渺渺茫茫入故乡。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5925, '辰', '否极秦来，造化还转。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5926, '辰', '再娶生四子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5927, '辰', '轻暖轻寒，紫色无边。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5928, '辰', '乡科中选。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5929, '辰', '事体多端，心中未宽。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5930, '辰', '心中带有疑，问神又占卜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5931, '辰', '裘马翩翩，往来金玉。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5932, '辰', '破星入限，流年大破财。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5933, '辰', '禄勋星现特，封一品之举。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5934, '辰', '小人谋财，君子谋道。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5935, '辰', '碧天云静，月转琉璃。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5936, '辰', '花开将尽香犹在，菊残犹有傲霜枝。', '[91, 92]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5937, '辰', '东西不辨，空徒驱逐。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5938, '辰', '命带指皆杀，恩泽反为伊。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5939, '辰', '朝谋夕算，明日东西。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5940, '辰', '寿止命尽。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5941, '辰', '举事斟酌，大有所获。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5942, '辰', '小人谋财，君子谋道。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5943, '辰', '前后有阻，居止无所。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5944, '辰', '风物如桦柏，岁寒节更坚。', '[95, 96]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5945, '辰', '钱财如粪土，人意值千金。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5946, '辰', '无益之言休著口，不当已事莫当头。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5947, '辰', '花发满林春日长，东风料峭晚凝香。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5948, '辰', '不怕尘埃何怕寒，不愁风雨不愁霜。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5949, '辰', '红日东升，自有光明。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5950, '辰', '人生一世，草木一春。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5951, '辰', '恩父不见，泣血三年。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5952, '辰', '财帛难免散耗。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5953, '辰', '杨柳花飞已暮春，上下楼台物色新。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5954, '辰', '鱼下碧潭随浪舞，马滕青嶂插寒飞。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5955, '辰', '财滚滚兮财自旺，喜匆匆也福自隆。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5956, '辰', '杨柳含烟堤上绿。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5957, '辰', '因贪反成害，财帛席上耗。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5958, '辰', '辛丑之年，名登黄甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5959, '辰', '人逢喜事精神爽，花遇春风瑞气香。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5960, '辰', '是年别故偶，将红来比素。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5961, '辰', '财去财来，天道回环。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5962, '辰', '月明无暇玉，光辉日渐生。', '[9]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5963, '辰', '履道坦坦，君子贞洁。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5964, '辰', '一尘不染，四大本空。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5965, '辰', '菊吐秋天千万朵，梅一腊月几千枝。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5966, '辰', '得选仓宫，前数已定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5967, '辰', '不费工夫事有成，福来相凑喜相逢。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5968, '辰', '元亨利贞，百事吐吉。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5969, '辰', '招妻在本年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5970, '辰', '入场妄想，反耗其财。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5971, '辰', '官至同知，不能高擢。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5972, '辰', '破星入限，耗财损人。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5973, '辰', '赌星入限，频频破财。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5974, '辰', '当有五母之称。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5975, '辰', '春花带雨，流年不美。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5976, '辰', '赌星入限，破财伤人。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5977, '辰', '可借当年事无穷，今朝低首向西风。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5978, '辰', '耗星入限，破财之源。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5979, '辰', '安常处顺，得意之时。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5980, '辰', '乙丑之年，名登黄甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5981, '辰', '不利不利，破耗破耗。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5982, '辰', '一掷千金浑身胆，家无四壁不知贫。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5983, '辰', '老当益壮，宁知白首之心。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5984, '辰', '龙嘘气直上，五色云呈祥。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5985, '辰', '事起从心头，内外得意浓。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5986, '辰', '当年凶星照命，赌钱不利终日愁。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5987, '辰', '课雨占晴，天意顺人。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5988, '辰', '欲左欲右，光明度日。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5989, '辰', '黄莺在谷，载好佳音。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5990, '辰', '是非无挂念，逍遥出自然。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5991, '辰', '淑贤内助得安康，衣禄无忧福寿长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5992, '辰', '东西南北，无往不利。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5993, '辰', '三阳回万象，幽谷自生春。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5994, '辰', '数有不幸，天死非命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5995, '辰', '破财不利，此年有咎。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5996, '辰', '限中一似雨中雷，难成事业败如云。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5997, '辰', '今日晴时明日阴，情伤颠倒是迷途。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5998, '辰', '官至吏部尚书，不能拜相。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (5999, '辰', '卜君阳年，终于九六。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6000, '辰', '一字切忌日青，用不得。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6001, '巳', '一生衣禄勤俭，钱财广于晚年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6002, '巳', '柏舟自失，心坚似冰。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6003, '巳', '几点芭蕉雨，一声愁闷不堪开。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6004, '巳', '祥光映画堂，获福自思量。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6005, '巳', '熟读萧公律，功深自可求。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6006, '巳', '云里月，雨中花。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6007, '巳', '官至尚书，至尊至贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6008, '巳', '命中多内助，家室有孟光。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6009, '巳', '壮年劳老年闲，名利场中不用贪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6010, '巳', '心本太虚，一尘不染。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6011, '巳', '数有三子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6012, '巳', '前妻一子，后妻无儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6013, '巳', '为所当为，独之大利。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6014, '巳', '凶神为吉吉又凶，凶之无害吉成功。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6015, '巳', '徒弟四人，许具送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6016, '巳', '无害有益，无劳心力。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6017, '巳', '上承下接，财帛广积。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6018, '巳', '庆父已死，云开见日。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6019, '巳', '有针无线用，欲穿未成衣。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6020, '巳', '易乎其易，事功有济。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6021, '巳', '无甚灾凶恶难，亦是常年之喜。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6022, '巳', '四业读书，陶情花涵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6023, '巳', '前途尽是坦夷路，一任邀游自在行。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6024, '巳', '经父纬母，独把之财。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6025, '巳', '如圭如譬，如金如锡。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6026, '巳', '君子是则，永受其福。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6027, '巳', '与人亦求佣，检身若不及。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6028, '巳', '腾文则野，先进之风。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6029, '巳', '川下火起，灾毒不减。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6030, '巳', '伯牛有疾，君亦如之。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6031, '巳', '景色晴明，芙蓉开展。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6032, '巳', '兄弟二人，其乐融融。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6033, '巳', '有箭无弓，欲射不能。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6034, '巳', '月上初弦渐光明，若到中旬倍十分。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6035, '巳', '云里月，雨中花。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6036, '巳', '碧天万里浮无云，月对栏杆水有阴。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6037, '巳', '梦魂不扰，际遇相安。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6038, '巳', '眉头开展，事得施为。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6039, '巳', '有斐君子，终不可喧。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6040, '巳', '伊耕于有萃，野未逢汤聘。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6041, '巳', '数有三子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6042, '巳', '坎坷度流年，机会几变迁。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6043, '巳', '发福千秋至，运广积财帛。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6044, '巳', '流年更不同，桃花与柳浓。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6045, '巳', '喜庆得相逢，谋之便有功。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6046, '巳', '乡科及第。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6047, '巳', '始忧终悦，良辰美景。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6048, '巳', '背有曲驼，前生恶报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6049, '巳', '犬生两口，请君详之。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6050, '巳', '爵虽武曲，业本儒行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6051, '巳', '财帛耗散，积蓄为难。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6052, '巳', '成家贵人扶，一身安乐永无忧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6053, '巳', '悉闻啼鸟叫，跃马过檀溪。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6054, '巳', '芙蓉未了变忧容，花正开时忽遇风。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6055, '巳', '春风桃李花开日，秋雨梧桐叶落时。', '[81, 82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6056, '巳', '手艺要高九流内，都在人间第二流。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6057, '巳', '几年撑过安宁日，将来自有佳景图。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6058, '巳', '血光潮热时年气，五六前后不能容。', '[5, 6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6059, '巳', '有为之时，事及克济。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6060, '巳', '洞房之喜。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6061, '巳', '东风转西风，昼夜暖寒自不同。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6062, '巳', '恩星照命，吉利安宁。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6063, '巳', '香生帘幕清风转，花覆宫墙淑气多。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6064, '巳', '问利问名，两收其益。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6065, '巳', '离合春光老已无，颜色逢秋又稿枯。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6066, '巳', '精传茅山法，普救世间人。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6067, '巳', '刚断而任，气象峥嵘。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6068, '巳', '恩星相扶，增福进爵。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6069, '巳', '祸去祸来，灾毒尽梢。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6070, '巳', '不须忧虑，守分安常。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6071, '巳', '缥缈梦魂，蝴蝶分飞。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6072, '巳', '烦恼无人识，惟欠东风个人知。', '[44, 45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6073, '巳', '匪直也人，秉心塞渊。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6074, '巳', '葵花偏爱日，掩映不为光。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6075, '巳', '惆怅关山外运限，有奇灾神力可保。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6076, '巳', '不意之中福自臻，恩星相照福来临。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6077, '巳', '命带文昌，名登金榜。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6078, '巳', '时运不通，连遭几度。', '[5, 6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6079, '巳', '金风除暑气，心舒喜自如。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6080, '巳', '嫡母庶母，命中注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6081, '巳', '偶因行事徒差错，误了终身识未知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6082, '巳', '半为儒者半为医。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6083, '巳', '妻早子亦早，人生大幸好。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6084, '巳', '华年凋谢天地老，人生多情偏悲思。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6085, '巳', '蟋蟀最无知，亦悲年运穷。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6086, '巳', '超然物外时，时梅月松风。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6087, '巳', '闷闷不堪言，足不知前。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6088, '巳', '一往因飘蓬，俯仰又似悲。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6089, '巳', '东西任所之，宇宙何其宽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6090, '巳', '时乖命亦乖，浑沌无心绪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6091, '巳', '用之帝王师，不用岩谷叟。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6092, '巳', '烦恼认人识，惟欠东风个人知。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6093, '巳', '问之父母全，卜他之年父先去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6094, '巳', '严霜上鬓，东风吹去。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6095, '巳', '童子五岁，难免灾晦。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6096, '巳', '此刻生人，兄弟有疾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6097, '巳', '穷通皆由命，切莫强求谋。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6098, '巳', '达将连驷骋，穷即蓬华行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6099, '巳', '凉风暑气除，心安舒自如。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6100, '巳', '妇命能操持，生涯能安居。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6101, '巳', '五彩绳牵月老话，画眉京兆许张郎。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6102, '巳', '灾星相照，啾唧自知。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6103, '巳', '仕途变迁，正当郑重明。', '[3940]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6104, '巳', '不必问行藏，进五而退十。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6105, '巳', '乘车而往按徐行。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6106, '巳', '莫道少年淡，自然光景辉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6107, '巳', '游神问名利，自叹费无成。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6108, '巳', '川下火起，灾殃自至。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6109, '巳', '童子五六岁，香芬物色新。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6110, '巳', '照光正阳和，定和景物多。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6111, '巳', '寒窗之苦皆经历，何时案上姓名香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6112, '巳', '亢龙有悔，勿用于时。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6113, '巳', '安心乐意，出人头地。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6114, '巳', '有弓无箭，欲射不能。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6115, '巳', '恼烦无端好忧心，自知自立自沉吟。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6116, '巳', '财帛有余，一生足用。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6117, '巳', '平安可保，不问行藏。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6118, '巳', '犬生两口，孝服之忧。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6119, '巳', '一日修好德，二日利大川。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6120, '巳', '际遇有主张，行人遇羊肠。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6121, '巳', '数注其人，田园万顷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6122, '巳', '枯苗得雨，家业光隆。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6123, '巳', '腰缠万贯，一生足用。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6124, '巳', '庭前草色知君早，暗里栽培透毓新。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6125, '巳', '数注其人福禄臻，心逸身劳得干金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6126, '巳', '登科及第。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6127, '巳', '前村遥望杏花红，指引来时有牧童。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6128, '巳', '仕途变幻，举动多变。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6129, '巳', '绿林深处有渔舟，漫卷丝纶着意收。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6130, '巳', '衡门之下可栖迟，泌水洋洋可乐饥。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6131, '巳', '小宋应熊黑，三子喜可见。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6132, '巳', '炊白梦回伤寂莫，中流不见采苹人。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6133, '巳', '际遇渐亨通，轻风送转蓬。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6134, '巳', '发创千金富，儿孙世代昌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6135, '巳', '烦恼结心头，愁绪满眉端。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6136, '巳', '雨遇增山色，云散月华明。', '[7, 8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6137, '巳', '利不可求，动而见忧。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6138, '巳', '兄弟四人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6139, '巳', '古稀欠三春，夫死泪沾襟。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6140, '巳', '数注其人富，白手发千金。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6141, '巳', '皓首风波。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6142, '巳', '君子坦荡荡，小人常喊喊。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6143, '巳', '欲知几度蟠桃熟，七九加二数已尽。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6144, '巳', '一字切忌日黑，不利矣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6145, '巳', '一品当朝，名扬四海。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6146, '巳', '瑞气重重至，门庭吉庆多。', '[24, 25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6147, '巳', '乐昌破镜难再会，珠沉合浦几时还。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6148, '巳', '迷途而得转，好花深处有盘旋。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6149, '巳', '圆缺因时有不同，主张头上有天公。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6150, '巳', '真假四子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6151, '巳', '待人真诚，受人欺侮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6152, '巳', '苗而不秀，秀而不实。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6153, '巳', '愁怀未可言，因为皆有恨相连。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6154, '巳', '啾唧不免，一暗一明。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6155, '巳', '乡科及第，天赐麟儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6156, '巳', '夫妇寡绿，弃妻重妾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6157, '巳', '造化有循环，剥极自然复。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6158, '巳', '好花开芍药，一泓秋水浸芙蓉。', '[2526]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6159, '巳', '难聚易散名日津。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6160, '巳', '吉凶不由人，可知次第行。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6161, '巳', '翩翩足五行，重水必然有。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6162, '巳', '走至逆横，事事皆闷。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6163, '巳', '财帛有余，当年不必问。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6164, '巳', '苍蝇点破无瑕玉，不费财钱也费心。', '[87, 88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6165, '巳', '阴气盘桓晦气催，灾之不已又还灾。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6166, '巳', '生子之年。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6167, '巳', '患难遍相随，为祸又为灾。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6168, '巳', '道路难行，前荆后棘。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6169, '巳', '兄弟九人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6170, '巳', '荫祖公道，少年荣华。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6171, '巳', '失恬光嗟情惨切，断机惟笑孟母前。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6172, '巳', '盘旋复盘旋，渔郎引路前。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6173, '巳', '福寿双全，精神倍爽。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6174, '巳', '一生多博学，性情守已乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6175, '巳', '太阳出沧海，欢呼乐意浓。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6176, '巳', '每日乐优游，寻常不用求。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6177, '巳', '日日乐优游，安常乐忘忧。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6178, '巳', '兄弟九人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6179, '巳', '既乘其时，当长其志。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6180, '巳', '今年胜去年，人事幸无。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6181, '巳', '家藏干金，勤俭所积。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6182, '巳', '明月到中天，画堂自光辉。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6183, '巳', '以监而司职，数由此定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6184, '巳', '舍了一场灾，几度忧警害。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6185, '巳', '一品当朝，声扬四海尽知名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6186, '巳', '祥光叠叠现，偏照锦堂春。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6187, '巳', '妻生一子，妾生二儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6188, '巳', '春寒秋熟，光景无多。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6189, '巳', '君生六子土水金，若生火星便为去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6190, '巳', '好花将开，风雨又来。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6191, '巳', '葵花偏向日，浮去半掩不为凶。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6192, '巳', '官至都堂，荣归华堂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6193, '巳', '瑞气隆隆起，家门吉庆多。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6194, '巳', '人中龙虎，阁上麒麟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6195, '巳', '荫受知州，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6196, '巳', '人逢美运，花放遇春。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6197, '巳', '吉庆临门，乐意相从。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6198, '巳', '荟苔雨遇滑如油，行人仔细便无忧。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6199, '巳', '兄弟五人，先损一丁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6200, '巳', '不用劳力，安然衣食。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6201, '巳', '双亲同白鬓，父母定其宗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6202, '巳', '坎坷有风流，数定几变迁。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6203, '巳', '为知白壁方为宝，更起黄金又交接。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6204, '巳', '流年更不同，桃花映日新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6205, '巳', '柳媚花明，赏心时节。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6206, '巳', '乡科及第。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6207, '巳', '喜事更相逢，谋之便有功。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6208, '巳', '锦绣花丛发，开放满园红。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6209, '巳', '童亦安舒，无甚别事。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6210, '巳', '桃红柳绿，略称心怀。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6211, '巳', '兄弟九人，中断离群。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6212, '巳', '真假六子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6213, '巳', '灾毒不生，流年之庆。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6214, '巳', '人逢美景地，花开又遇春。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6215, '巳', '自有高人轻借力，两台门户尽光辉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6216, '巳', '福履悠悠，家门迪吉。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6217, '巳', '春光冉冉，物色交新。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6218, '巳', '财帛骤发，好运时行。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6219, '巳', '荷花出水，亭亭玉立。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6220, '巳', '生来欠发达，儿孙创田园。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6221, '巳', '佛祖降生，方人扳依。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6222, '巳', '无是无非，三春花柳。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6223, '巳', '恩星照命，吉利相从。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6224, '巳', '花申欠二春，夫花泪沾襟。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6225, '巳', '凶星夹党，居安虑危。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6226, '巳', '高山路可通，费力定成功。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6227, '巳', '乡科及第。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6228, '巳', '官至试院而致仕。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6229, '巳', '数该生子。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6230, '巳', '事就怕有人，相欺恨无依。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6231, '巳', '龙德相扶，必有所获。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6232, '巳', '数该生子。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6233, '巳', '瑞气融融，景象非凡。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6234, '巳', '徒弟四人，三人送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6235, '巳', '哀哀泣泣，正是刑伤。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6236, '巳', '喜事临门，事业更新。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6237, '巳', '月明不怕云遮掩，花艳何妨蝶乱飞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6238, '巳', '事事添花锦，荣华自可夸。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6239, '巳', '步步履泥途，挣挫费。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6240, '巳', '遇马之年方进步。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6241, '巳', '羊刃重逢，刀兵之害。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6242, '巳', '为所欲为，美利巨获。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6243, '巳', '官至吏部尚书。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6244, '巳', '三旬外入泮，方合此刻。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6245, '巳', '前途尽是通行路，一任逍遥自在行。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6246, '巳', '瑞气隆隆，门庭吉庆。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6247, '巳', '数有不幸，应死非命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6248, '巳', '好鸟鸣春，东风暖人。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6249, '巳', '老来丧母之年。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6250, '巳', '虎榜题名，熊黑叶梦。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6251, '巳', '无枝无求，终身悠悠福有余。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6252, '巳', '君子日更新，相逢大吉人。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6253, '巳', '波浪铉息，正好行舟。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6254, '巳', '不枝不求，安乐悠悠。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6255, '巳', '进士及第。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6256, '巳', '闲度余岁月，不管落花飞。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6257, '巳', '登科之年。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6258, '巳', '谢却忧颜转花容，时来无物不相同。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6259, '巳', '清明花发正芳菲，恨杀无情风雨催。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6260, '巳', '金水之年，弓马入泮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6261, '巳', '运至时行，知君获福。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6262, '巳', '安心乐意，出人头地。', '[40, 41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6263, '巳', '倚马雄才到午年，运程发韧泮池边。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6264, '巳', '数该生子。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6265, '巳', '进士及第。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6266, '巳', '兄弟十人，中断离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6267, '巳', '十事谋来九事成，春风得意马蹄轻。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6268, '巳', '金水之年，国学成名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6269, '巳', '当道有荆棘，举步有滞碍。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6270, '巳', '木火之年，弓马入泮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6271, '巳', '红日上三竿，前程有庆幸。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6272, '巳', '兄弟三人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6273, '巳', '路遇一知音，携手相扶物色新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6274, '巳', '兄弟五人，秦楚不同盟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6275, '巳', '荣枯提失皆前定，何必怨天又尤人。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6276, '巳', '前妻生四子，后妻竟无儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6277, '巳', '财帛蓄积不求人，上下欢然物色新。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6278, '巳', '哀哀泣血几经年，原来母先父后亡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6279, '巳', '数注双喜，一胎生二子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6280, '巳', '父母离巽方生，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6281, '巳', '历尽几年奇学术，不如终作一星巫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6282, '巳', '太岁当头，流年稳妥。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6283, '巳', '一岁为泉客，徒增父母悲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6284, '巳', '数有偏枯，子当发疾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6285, '巳', '真假六子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6286, '巳', '水中捞月事皆空，尽精神也枉功。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6287, '巳', '图谋顺遂，足畅所怀。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6288, '巳', '老来丧母之年。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6289, '巳', '祖业命当招，田基莫摇动。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6290, '巳', '五彩绳牵月老话，画眉京兆许张郎。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6291, '巳', '一隙之光可借明，隙光难比月华明。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6292, '巳', '四宫吉曜奇，数注一胎生二子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6293, '巳', '利不可求，动而招尤。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6294, '巳', '犬生两口，主有哀声。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6295, '巳', '半吉半凶，吉凶难倚。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6296, '巳', '徒弟六人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6297, '巳', '生计得安然，何劳忧兴煎。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6298, '巳', '当有三母之称。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6299, '巳', '山久矣路盘桓，行遇山蹊路坦夷。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6300, '巳', '兄土年生，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6301, '巳', '乍暖还寒，心常不乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6302, '巳', '事有攸理，千头万绪。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6303, '巳', '难晨鸣，由雄不惧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6304, '巳', '灾晦消除福自臻，烟云卷尽碧空云。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6305, '巳', '父母故于犬年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6306, '巳', '并蒂双莲出，风光共白头。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6307, '巳', '大数将停莫可为，一朝春尽红颜老。', '[80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6308, '巳', '白虎照命，是年有灾。', '[4]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6309, '巳', '异路功名，授吏之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6310, '巳', '乡科及第。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6311, '巳', '初任知县，再升钦取。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6312, '巳', '徒弟五人，一人送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6313, '巳', '阴暗既分，方可言行。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6314, '巳', '红莲初水来，花发正阳春。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6315, '巳', '闲坐松阴，乘阴纳凉。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6316, '巳', '阴云日，能使人愁。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6317, '巳', '虽然富贵，子嗣艰难。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6318, '巳', '贤儿成鼎志，终身可无虞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6319, '巳', '西风忽东风，昨夜今朝事不同。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6320, '巳', '兄弟三人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6321, '巳', '且沉且浮，事物纷纷未有头。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6322, '巳', '到处花开春色新，洛阳不比寻常景。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6323, '巳', '家资百万休嫌少，斗稍之辈我还高。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6324, '巳', '命中四子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6325, '巳', '鸟得其所，饮啄自如。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6326, '巳', '花蕊初红，风雨相催。', '[8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6327, '巳', '天光机会，物有祥云。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6328, '巳', '祖父倍增荣，晚年兴发增。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6329, '巳', '七岁少三春，萱花落暗尘。', '[4]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6330, '巳', '数有偏枯，妻当眼目不甚明。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6331, '巳', '兄弟十人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6332, '巳', '衣巾遂愿，不必他求。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6333, '巳', '父母生于火年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6334, '巳', '一子午年生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6335, '巳', '既望之月，其光渐减。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6336, '巳', '蛊命丧身，前生注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6337, '巳', '当年之事不堪闻，弹出新声别有音。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6338, '巳', '轻舟飘大浪，时有浮沉惊。', '[3, 4]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6339, '巳', '欲上高楼未有梯，不能举步上扳。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6340, '巳', '急流勇退，晚景逍遥。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6341, '巳', '指引得以相，应转折人心。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6342, '巳', '风寒消除暖风生，梅花枝头见阳春。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6343, '巳', '官至千总，不能高摧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6344, '巳', '兄弟两家祀，不离本族宗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6345, '巳', '事机宜谨慎，方免是非忧。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6346, '巳', '次第花枝雪里开，梦魂应不染尘埃。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6347, '巳', '百事和谐，五音叶律。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6348, '巳', '有子先弃世，赖孙而送终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6349, '巳', '平静无风雪。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6350, '巳', '黄泉无客店，今夜宿谁家。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6351, '巳', '谢却人间事，红尘不染心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6352, '巳', '粟陈贯朽几年余，富似陶朱苦拮据。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6353, '巳', '闲看棋杆消白昼，觉来经卷脱红尘。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6354, '巳', '烛影辉煌，照耀画堂。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6355, '巳', '其人田园广，一生乐无边。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6356, '巳', '好运交来事得宜，无心财聚可乘机。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6357, '巳', '时气相侵，流年不利。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6358, '巳', '可怜白壁染风尘，仰问苍天惧不平。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6359, '巳', '人事相通，内呼外应。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6360, '巳', '创之规模总是勤，十年前事一书生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6361, '巳', '钦命典试。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6362, '巳', '钦授干总，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6363, '巳', '吉星照文场，领袖青矜换紫衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6364, '巳', '以责而选经历，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6365, '巳', '登山力却，犬有挣挫。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6366, '巳', '到此停秋风，无限别离情。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6367, '巳', '座中无物不清凉，别是人间洞府香。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6368, '巳', '小桥泮藜，书香门第。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6369, '巳', '左财右财，心神自佑。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6370, '巳', '治家有法，冰清玉洁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6371, '巳', '整顿行装，不负良辰美景。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6372, '巳', '田财二曜，精奇数享万全福。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6373, '巳', '困道未可言，步步若流连。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6374, '巳', '步步履泥途，挣挫费。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6375, '巳', '结鬓未能同并老，再婚夫妇得齐眉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6376, '巳', '精于医道，不亚儒术。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6377, '巳', '一品之元老，莲花座上仙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6378, '巳', '逆风而摇撸，天转其风帆。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6379, '巳', '春而复夏又秋冬，寒暑更迁事不同。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6380, '巳', '一生好学，功成名就。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6381, '巳', '孟姜送罢寒衣后，万盏金樽醉自知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6382, '巳', '去路茫茫不可知，贵人指引不迷途。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6383, '巳', '官到知州，不能高摧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6384, '巳', '时至出头地，膳自从天来。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6385, '巳', '结发未能同并老，重婚夫妇许生儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6386, '巳', '德厚饶施，政平公理。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6387, '巳', '文昌祠畔有猿啼，一领青衫换布衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6388, '巳', '命如浮蚁，死在一周。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6389, '巳', '春寒秋热，光景无多。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6390, '巳', '其人有心，善医济人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6391, '巳', '海棠着雨，泪湿胭脂。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6392, '巳', '数该生子。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6393, '巳', '虽是庶出，兄弟最长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6394, '巳', '兄弟九人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6395, '巳', '交差交差，门前绿竹尽生花。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6396, '巳', '福曜相扶，当展其用。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6397, '巳', '光点红灯灯已阑，长途暗里有艰难。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6398, '巳', '惟听鸟燕啼，春雨泪沾衣。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6399, '巳', '朱提无足自至，青蚨无翅也飞来。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6400, '巳', '人随天意，万事周济。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6401, '巳', '知足漫无足，鬼神驱使悠悠福。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6402, '巳', '君家要出人头地，异路功名可称怀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6403, '巳', '年年花卉春光放，花卉今朝开得早。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6404, '巳', '藜杖相扶得过桥，昨朝霜露未曾消。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6405, '巳', '安常之福，无日不足。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6406, '巳', '问文不足，问武有余。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6407, '巳', '兄弟十二人，终断惜离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6408, '巳', '命带将军箭，十二便身亡。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6409, '巳', '前妻生二子，后妻竟无儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6410, '巳', '虽喜还无喜，逢凶不见凶。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6411, '巳', '灾晦潜消官事伏，平安有度无拘束。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6412, '巳', '承荫父业，仕途可望。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6413, '巳', '造化有循环，春风吹牡丹。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6414, '巳', '乡试中式。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6415, '巳', '不从文武科中出，应升总督一大厅。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6416, '巳', '朱衣点头，得意琼林。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6417, '巳', '弥缝不及又弥缝，纵若谋成总是空。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6418, '巳', '和气克临，流年顺利。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6419, '巳', '子息未必运俱齐，有人赛滞有人宜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6420, '巳', '春深鱼游，跳跃自如。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6421, '巳', '守持之戒，名日上僧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6422, '巳', '登山足跋，力喘而上。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6423, '巳', '官至总督，不能相拜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6424, '巳', '举动迷路，恶梦风起。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6425, '巳', '颜子少一春，一梦见阎君。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6426, '巳', '芍药开时又遇风，凋残无限锦丛中。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6427, '巳', '运至时来，富丽顿开。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6428, '巳', '名登金榜。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6429, '巳', '路可通修，行乃有功。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6430, '巳', '驳杂无常，进退有损。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6431, '巳', '财帛虽有，满而不溢。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6432, '巳', '年逢古稀零有四，谢却阳间去。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6433, '巳', '兄弟十一人，数有五贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6434, '巳', '无事得安舒，欢然得自如。', '[5758]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6435, '巳', '无是无非，光阴渐移。', '[5, 6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6436, '巳', '虽然武终须革去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6437, '巳', '父故于金年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6438, '巳', '一子虎年生方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6439, '巳', '江村三月景，处处绿阴浓。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6440, '巳', '栖止得所，轻风日午。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6441, '巳', '莫笑冯唐无晚景，斯君老运享荣华。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6442, '巳', '命犯白虎，夫当受克。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6443, '巳', '天喜命相逢，往来最有功。', '[7]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6444, '巳', '晋升千总。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6445, '巳', '山坡前有挺，杖几为所害。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6446, '巳', '翁姑先死，妇之不幸。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6447, '巳', '进不过进退不退，进退无常以醉。', '[8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6448, '巳', '著意图谋总是虚，无心之处得成功。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6449, '巳', '枯木逢春之象。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6450, '巳', '兄弟十二人，同父不同母。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6451, '巳', '上菀春花遍锦丛，日日追风随马蹄。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6452, '巳', '数遇纯阳，文娄尽去。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6453, '巳', '心之忧戚，履步未舒。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6454, '巳', '亦算平稳。', '[8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6455, '巳', '露色溟朦雨，远人未及回。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6456, '巳', '中年采芹青云路，再积阴功人钦敬。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6457, '巳', '安然无事纳祯祥，几朵梅花扑鼻香。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6458, '巳', '云收风静，日照深闺。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6459, '巳', '问君阳年何日止，六旬加五是归期。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6460, '巳', '经史饱餐归国学，阴功积可到中宫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6461, '巳', '兄弟虽众，助人却寡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6462, '巳', '得个渔翁指路迷，天台不远又何疑。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6463, '巳', '天生天夺，父母之悲。', '[7]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6464, '巳', '问利三旬之外，方得遂意。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6465, '巳', '千古作文家，泰山北斗星。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6466, '巳', '家室欢乐，事纳祯祥。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6467, '巳', '冻已消除日渐融，池边杨柳弄轻风。', '[8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6468, '巳', '初任百总之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6469, '巳', '鸳鸯一对两分飞，自恨良人不齐眉。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6470, '巳', '流年顺利，一帆风顺。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6471, '巳', '常眉头，欠利多忧。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6472, '巳', '兄弟十一人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6473, '巳', '立元坚固，未可摇动。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6474, '巳', '兄弟四人，中断离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6475, '巳', '做事蹉跎，其年破局多。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6476, '巳', '一手伤残，命中带来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6477, '巳', '一番好雨应阳春，眼见江城景色新。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6478, '巳', '妻命木金年生方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6479, '巳', '春色正可人，依依轻青绿。', '[3]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6480, '巳', '难逃七九之数。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6481, '巳', '金土之年国学，木火之年得贡。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6482, '巳', '江山春色未全来，满树桂花风雨催。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6483, '巳', '日破财耗，神接来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6484, '巳', '君多逢赛，西风泪几行。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6485, '巳', '半作田东半作渔，一生衣禄自无穷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6486, '巳', '官讼相连，破耗忧煎。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6487, '巳', '数有七子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6488, '巳', '劳力劳心勤且俭，半为儒生半为农。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6489, '巳', '文章入泮，弓马为先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6490, '巳', '缓步而行，默然无阻。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6491, '巳', '南陌田畴耕暇日，生涯着力得营谋。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6492, '巳', '喜气盈门，家室安宁。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6493, '巳', '知君加一岁，卜君是行程。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6494, '巳', '王都色带春，得意马蹄径。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6495, '巳', '再任催官。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6496, '巳', '求所不当求，空余未了愁。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6497, '巳', '一生竭力躬耕去，南陌西畴望岁农。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6498, '巳', '杨柳依依绕绿堤。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6499, '巳', '忿气莫伸，终为丧身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6500, '巳', '积喜之家，千般吉祥。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6501, '巳', '年逢古稀零有四，夫别阳关去。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6502, '巳', '九天开雾，干山秀色。', '[48, 49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6503, '巳', '晚景亨通，一生幸运。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6504, '巳', '徒弟七人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6505, '巳', '再转京台登大用，官归传阁肃风霜。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6506, '巳', '创立规模总是勤，十年前是一书生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6507, '巳', '难逃五十二，明说与君知。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6508, '巳', '吉利拥门，财源日进。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6509, '巳', '以监终身结，一生之结局。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6510, '巳', '数有六子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6511, '巳', '勤俭持家衣禄足，旺夫益子寿元长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6512, '巳', '将军一箭最难当，三岁孩儿身便亡。', '[3]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6513, '巳', '夫虽有寿，别之亦苦。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6514, '巳', '老来又精神，枯木又逢春。', '[91]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6515, '巳', '举人任知县，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6516, '巳', '父故于水年，母生于火年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6517, '巳', '妻生二子，妾生一儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6518, '巳', '数该生子。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6519, '巳', '子规啼落楼头月，一枕鸳鸯梦不成。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6520, '巳', '不出户庭，福自来寻。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6521, '巳', '不足不驳难相逐。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6522, '巳', '命带暗杀，三岁而亡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6523, '巳', '有子惟宣先抱女，原来有数定先知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6524, '巳', '人有黄金满玉楼，我有妙术度春秋。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6525, '巳', '当宴鹿鸣。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6526, '巳', '兔走鸟飞，领袖青换布衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6527, '巳', '未嫁夫先死，女之不幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6528, '巳', '前妻三子，后妻无儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6529, '巳', '希宇遇寒风，时当有等待。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6530, '巳', '古镜尘蒙，晦而不明。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6531, '巳', '再升知县。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6532, '巳', '谢却人间世，常纳祯祥福。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6533, '巳', '洛阳三月景色新，满日繁华应接忙。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6534, '巳', '五旬外丧亲，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6535, '巳', '时至出头食禄，运逢释褐宴鹿鸣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6536, '巳', '夫别阳关去，千愁万泪行。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6537, '巳', '春日凝妆上翠楼，幽人无事乐优游。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6538, '巳', '小雨暗前山，春风尚乍寒。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6539, '巳', '时行平稳，微恙不志。', '[2]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6540, '巳', '天道旋转，人将随之。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6541, '巳', '骑驴望马，心竟未定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6542, '巳', '夫君早忙碌，淑贤得安康。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6543, '巳', '兄弟九人，中断离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6544, '巳', '福来有根基，光阴无处不相宜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6545, '巳', '兄弟四人，先损一丁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6546, '巳', '初夏来时绿阴浓，荷花出水见芙蓉。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6547, '巳', '一卷残经诵未完，疏林月色满蒲团。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6548, '巳', '经历之职，名垂异路。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6549, '巳', '以贡知县，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6550, '巳', '危桥之下险难言，柱杖相接得周旋。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6551, '巳', '谋事不吉，谨慎行事。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6552, '巳', '数中有二室，乃结红紫衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6553, '巳', '百事谋来总是空，数中逢绝必倾身。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6554, '巳', '晴光烈烈日已升，无限春光在江滨。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6555, '巳', '桂子结成有一枝，江风吹折在空中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6556, '巳', '断而不断有汕锦，一线有路莫残圆。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6557, '巳', '喜事从天降，桂子结成双。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6558, '巳', '路无常直，运有得失。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6559, '巳', '服劳皇家，厥有成绩。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6560, '巳', '红颜薄命，好事多磨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6561, '巳', '且自庆晚年，春光在眼前。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6562, '巳', '雁阵成群，非一母所生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6563, '巳', '祖宗庇荫，百总之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6564, '巳', '五十零四，当止则止。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6565, '巳', '立志坚刚，不随流俗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6566, '巳', '武泮而选，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6567, '巳', '天符相照，是非不宁。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6568, '巳', '得傍贵人可成家，原来数定注不差。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6569, '巳', '轻裘带上，威权足重。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6570, '巳', '腐草得雨，生意自成。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6571, '巳', '桃花流水透天台，得个渔翁指路来。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6572, '巳', '茫茫风尘路，红拂敬知音。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6573, '巳', '身作白云客，子当拜圣君。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6574, '巳', '父故于水年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6575, '巳', '名登金榜，身宴琼林。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6576, '巳', '浮云卷尽日生阴，转眼云开月复明。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6577, '巳', '财帛有余，勤俭此得。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6578, '巳', '粟有余，财广地僻。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6579, '巳', '房考之年。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6580, '巳', '夫别阳关去，亦是难为情。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6581, '巳', '数有八子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6582, '巳', '金水之年，同学方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6583, '巳', '破财不安，流年不利。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6584, '巳', '勤俭创业，财帛自足。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6585, '巳', '不费精神事也成，运来相奏喜相连。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6586, '巳', '真入之道，济世之才。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6587, '巳', '喜逢黄道日，禀膳姓名香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6588, '巳', '千金定从俭里得，裕后儿孙福自绵。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6589, '巳', '少年克妻，闷之如何。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6590, '巳', '运有伤残，刑及妻房。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6591, '巳', '能刚能柔，万事之乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6592, '巳', '母逝于鸡年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6593, '巳', '幕年为政，渐入佳景。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6594, '巳', '先票后贡，前生注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6595, '巳', '极力经营虚，顺时是良图。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6596, '巳', '乡科及第。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6597, '巳', '一子兔年生方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6598, '巳', '天喜地德，家门吉庆。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6599, '巳', '复任知县。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6600, '巳', '水流花落，多少优愁。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6601, '巳', '乐极反忧，云行水流。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6602, '巳', '数有九子，八子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6603, '巳', '当有四母之称。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6604, '巳', '前途沉吟天心来，必合人心中途事。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6605, '巳', '兄弟十二人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6606, '巳', '福白天来，不自人为。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6607, '巳', '春秋依旧，日月如常。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6608, '巳', '鼓盆之悲，知命之年。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6609, '巳', '兄弟八人，秦楚不同盟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6610, '巳', '祸患接来，幸有吉人扶。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6611, '巳', '平常百姓人家。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6612, '巳', '初任有司，再升钦取。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6613, '巳', '若问阳生何日止，一程直至六旬余。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6614, '巳', '风卷灯花暗又明，摇摇不定影纵横。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6615, '巳', '晚年生子，人之大幸。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6616, '巳', '为招为运有不济。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6617, '巳', '谢却人间事，常纳祯祥福。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6618, '巳', '安步前驱，一必问路。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6619, '巳', '命有干金数，享得终生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6620, '巳', '贵时出嫁，命中注定。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6621, '巳', '柳上不舒眉，度日强支持。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6622, '巳', '天折数中定，黄金买不还。', '[2]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6623, '巳', '和丸有义方，当作贵人母。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6624, '巳', '水火之年克妻方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6625, '巳', '居易以矣，行险以求。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6626, '巳', '命中杀重，当刑克夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6627, '巳', '日行中天，何期罗计掩其光。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6628, '巳', '数中不幸，兄弟死于非命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6629, '巳', '新竹苍苍嫩柳丛，庭前茫茫物正蒙。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6630, '巳', '雪压椿枝，三年泣血。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6631, '巳', '妄意空花，难以入手。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6632, '巳', '岁月亭碧天，冰壶之灿烂。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6633, '巳', '大风拔树木，灾害并至此。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6634, '巳', '以监而选知县，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6635, '巳', '灾毒相侵，吉神化解。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6636, '巳', '其年夫死，妇之不幸。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6637, '巳', '知已所托可息肩，不用心神问往年。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6638, '巳', '兄弟五人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6639, '巳', '兔中巢中夜有光，主人不必问行藏。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6640, '巳', '财帛有余，勤俭所得。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6641, '巳', '问君阳年有几许，百有余矣。', '[103]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6642, '巳', '以贡而先知县，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6643, '巳', '子结二枝。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6644, '巳', '花开遍锦丛，无物不从容。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6645, '巳', '子结七枝，三枝送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6646, '巳', '寿数今朝不可延，幽魂恐坠入黄泉。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6647, '巳', '雁阵成行，非一母所生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6648, '巳', '晚年生子。', '[80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6649, '巳', '为人夜眠早，勤俭兴家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6650, '巳', '斯人庶母所生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6651, '巳', '命生不辰，幼年失恃。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6652, '巳', '舟波涛涌，人在危险行。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6653, '巳', '好事多逢君子道，是非莫听小人言。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6654, '巳', '拨开天上云千里，捧出波心月一轮。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6655, '巳', '缭乱鬓发无心理，沉吟朱户懒重开。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6656, '巳', '一生几成败，幸亏筋骨铮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6657, '巳', '父死骨肉相争。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6658, '巳', '命已去矣，何用再查。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6659, '巳', '好花未开，连遭风雨。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6660, '巳', '清净无为时，胜似神仙日。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6661, '巳', '前途波浪未恬静，吩咐舟人慢着篇。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6662, '巳', '雨足溪涧象，青山绿水行。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6663, '巳', '眉头欢笑颜，禄马相扶福自来。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6664, '巳', '花前月下听高歌，平坦康宁安意多。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6665, '巳', '阳年有几许，一百多有余。', '[101]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6666, '巳', '耳顺之年事不安，忧怀未可对人言。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6667, '巳', '叶新林换绿，花落地生香。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6668, '巳', '一步高来一步低，高低之处在忧疑。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6669, '巳', '骨肉相辞恨无凭，幼年洒泪漫沾衣。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6670, '巳', '财星照命，聚成巨富。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6671, '巳', '子死妻亡实可伤，临门二孝断肝肠。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6672, '巳', '乍雨乍晴云里月，半开半落雨中花。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6673, '巳', '十岁母亡，幼年之象。', '[10]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6674, '巳', '时逢恩星，当贡之期。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6675, '巳', '恐尔之寿，未满三旬。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6676, '巳', '鹊噪鸦鸣，吉凶未定。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6677, '巳', '兄弟十二人，数中有定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6678, '巳', '雨滴花阶，风毁蕊房。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6679, '巳', '途有荆棘，进退难行。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6680, '巳', '优惊成病总堪悲，独行迟迟不见归。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6681, '巳', '大利岁宁，春光可人。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6682, '巳', '历尽崎岖径，多少虚耗人。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6683, '巳', '瞻前顾后，索位无答。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6684, '巳', '兄弟五人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6685, '巳', '犬生两口，孝服之忧。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6686, '巳', '时来君宜守，何必徒劳心。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6687, '巳', '官至府门，不见高擢。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6688, '巳', '十件谋略九件成，人逢好运便前行。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6689, '巳', '生子之年。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6690, '巳', '名登九州，四海传颂。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6691, '巳', '牡丹开得精神足，会见同妆富贵春。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6692, '巳', '前有罗后有网，行人进步有仿。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6693, '巳', '大道烟笼，行人徘徊。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6694, '巳', '求鱼过清水，未能快人怀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6695, '巳', '衣食有余过岁月，看来暇豫乐晨昏。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6696, '巳', '数该生子。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6697, '巳', '项庄舞剑，意在沛公。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6698, '巳', '安分求谋不用贪，动则悔尤静则安。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6699, '巳', '钦命典试。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6700, '巳', '陈弦换当年，旧曲不如新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6701, '巳', '春风入我户，百事俱叶吉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6702, '巳', '生有结乳腊，世家手艺有高低。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6703, '巳', '春夏秋冬财源广，不西南北路皆通。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6704, '巳', '寒热无定，喜惧同庆。', '[5, 6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6705, '巳', '宝镜前妆，晓日紫云上绣香。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6706, '巳', '风卷禅灯暗又明，一明一暗心皆通。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6707, '巳', '夫别阳关去，千愁泪万行。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6708, '巳', '数该生子。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6709, '巳', '年逢七八，恐度鬼门关。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6710, '巳', '花残月缺，寿穷数尽。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6711, '巳', '颠沛转为安，赖有吉神佑。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6712, '巳', '人亦安然，何必问往年。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6713, '巳', '再任知县，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6714, '巳', '吉凶本在天遵道，人行自无。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6715, '巳', '三旬外入泮方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6716, '巳', '无无有有不须闻，闷闷愁愁自在天。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6717, '巳', '小盈大亏，得不如失。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6718, '巳', '妻生二子，妾自无儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6719, '巳', '财从勤生，利从广积。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6720, '巳', '数该生子。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6721, '巳', '大限入黄泉。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6722, '巳', '瑞气洋洋，门阑迪吉。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6723, '巳', '寿元百有余岁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6724, '巳', '常纳祯祥，永吉无疆。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6725, '巳', '霜落风吹，花无芳色。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6726, '巳', '丰盈得安然，不必问往年。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6727, '巳', '乡科及第。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6728, '巳', '夫死之年，妇之不幸。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6729, '巳', '勤俭持家，衣禄无亏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6730, '巳', '已年蛇走文场，泮池芹草生香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6731, '巳', '强梁纵强梁，安稳自安然。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6732, '巳', '贞足于事，自保其宁。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6733, '巳', '刑克为期，忧及克妻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6734, '巳', '数有七子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6735, '巳', '当宴膺扬。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6736, '巳', '无定今有定，前作当捷径。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6737, '巳', '钦命典试。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6738, '巳', '行尽泥泞多少难，将来安步渡关山。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6739, '巳', '数止于此矣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6740, '巳', '千里崎岖千里平，行人跋涉慢消停。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6741, '巳', '吉星相照，流年顺利。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6742, '巳', '山高水深，到此难行。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6743, '巳', '春回阳谷暖，万物自生辉。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6744, '巳', '命有八子，三子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6745, '巳', '福禄天降，财源日新。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6746, '巳', '花正开时风雨多，冷落凄凉多挫折。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6747, '巳', '得逢知己好相求，宽裕营谋不用忧。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6748, '巳', '初阳出林表，曙色照堂前。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6749, '巳', '先无慈母缝针线，惟有严亲在后归。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6750, '巳', '洞房花烛之年。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6751, '巳', '得之有心，失之无意。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6752, '巳', '老年丧妇，夫之不幸。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6753, '巳', '退才归林，安然乐意。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6754, '巳', '齿德俱尊，必入乡饮。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6755, '巳', '升迁知县，贵人提携。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6756, '巳', '一子送老，偏房所生。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6757, '巳', '紫微高照，官至迁升。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6758, '巳', '骨肉有刑伤，秋风泪两行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6759, '巳', '君家注定四旬零，数到黄泉恐不回。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6760, '巳', '暖侣初一日，前来景色新。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6761, '巳', '结婚自有梁鸿遇，双锁佳人到白头。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6762, '巳', '断弦之忧。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6763, '巳', '三岁丧母，莫大刑伤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6764, '巳', '未满三旬，不幸短命。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6765, '巳', '吐气扬眉，纵横如意。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6766, '巳', '勿以风光比旧年，风光不与旧年同。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6767, '巳', '朱颜温润，绿更新。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6768, '巳', '此年有乔迁之喜。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6769, '巳', '红贡而选知县，人之大幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6770, '巳', '劳心劳力，总成画饼。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6771, '巳', '有子当及第。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6772, '巳', '不须问后来，已是浑天数。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6773, '巳', '兄弟七人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6774, '巳', '光阴普照，失常可叹。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6775, '巳', '兄弟七人，中断惜离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6776, '巳', '快乐无极，毫无费力。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6777, '巳', '风卷花暗又明媚，摇摆无定影纵横。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6778, '巳', '数有四子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6779, '巳', '财帛随人，勃然兴发。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6780, '巳', '黄泉无客店，今夜宿谁家。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6781, '巳', '大运分明就转来，因人事有研究。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6782, '巳', '一子龙年生方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6783, '巳', '未满四旬，竟往西行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6784, '巳', '一重欢喜一重惊，道是无情却有情。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6785, '巳', '吉星高照，喜事重来。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6786, '巳', '三阳方来，气运相转。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6787, '巳', '园实树，晚景生春。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6788, '巳', '荣华乐意，福禄悠然。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6789, '巳', '骨肉有刑伤，西风泪两行。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6790, '巳', '花甲欠二春，大数止矣。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6791, '巳', '初任巡抚大厅。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6792, '巳', '今日清明整钓丝，得鱼沾江西歹怡。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6793, '巳', '东手弥缝，西手颠倒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6794, '巳', '防御之职，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6795, '巳', '家室康宁，事纳祯祥。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6796, '巳', '风卷灯花暗又明，飘摇无定影纵横。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6797, '巳', '敬以造事，克享厥成。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6798, '巳', '五十年来事未消，如何我寿寂寥寥。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6799, '巳', '碎不多时却又圆，几番挫折在身边。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6800, '巳', '时运未来，进退不如。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6801, '巳', '啾唧不免愁。', '[2]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6802, '巳', '勿嫌祸有胎，穷通命所该。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6803, '巳', '六岁丧母，幼年不幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6804, '巳', '硕果不食君子得，小人剥庐尚有汤。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6805, '巳', '持竿东海已数年，一旦无心得巨鳌。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6806, '巳', '惆怅复惆怅，时运未堪羡。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6807, '巳', '别万古愁，绿水青山空悠悠。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6808, '巳', '兄弟术年生，方合此刻。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6809, '巳', '雁行有序，非一母所生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6810, '巳', '官不休来私不休，安常处顺福悠悠。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6811, '巳', '兄弟八人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6812, '巳', '时逢大有，内外安宁。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6813, '巳', '时到中秋月朗圆，云生簇簇恨无凭。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6814, '巳', '春残花老，景物忧愁。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6815, '巳', '生父属牛，继父属羊。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6816, '巳', '道路泥泞，行人仿徨。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6817, '巳', '六岁丧父，幼年不幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6818, '巳', '芳草遇春风，前村绿阴浓。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6819, '巳', '水土之年宜配妻方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6820, '巳', '斐然成章，未遇朱衣。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6821, '巳', '杨柳风前最可思，迷离烟雨锁杨枝。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6822, '巳', '数该生子。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6823, '巳', '当时有为，事乃克济。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6824, '巳', '循分而动，动无不吉。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6825, '巳', '独子送终天注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6826, '巳', '无喜无乐，名日寂寞。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6827, '巳', '本年吉星照，姓名列痒序。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6828, '巳', '数注命丧虎，狼狈死其身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6829, '巳', '日月并明，万物从容。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6830, '巳', '软风吹小舟，安稳可无忧。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6831, '巳', '一字切忌日黄，可免则免。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6832, '巳', '一子举老，先天注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6833, '巳', '流年有坎坷，人事可奈何。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6834, '巳', '六九加一数将完。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6835, '巳', '大小安康，福禄天降。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6836, '巳', '年满一百，命恐不留。', '[10]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6837, '巳', '运限转时，眉头开展。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6838, '巳', '妻生二子，妾亦如之。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6839, '巳', '不满二十，不幸短命。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6840, '巳', '逢子年必可发越。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6841, '巳', '数止于此。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6842, '巳', '富贵如金昨夜看，五色眩目守偏长。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6843, '巳', '机会顺偶然，今年胜旧年。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6844, '巳', '晓日五云高，华筵集仙桃。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6845, '巳', '数该生子。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6846, '巳', '际遇非常，春风到处香。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6847, '巳', '数有十子，六子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6848, '巳', '解放愁眉，春风绿柳。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6849, '巳', '乡榜题名。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6850, '巳', '频频遇吉祥，流年之庆。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6851, '巳', '谋之有功，日日春风。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6852, '巳', '命犯孤刑。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6853, '巳', '风雨花冷落，欲渡清溪船。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6854, '巳', '驳杂无端眉，交未开颜。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6855, '巳', '操守有节，行藏不苟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6856, '巳', '本身出家，原来数定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6857, '巳', '喜气上眉，太平乐事。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6858, '巳', '兄弟六人，数有三贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6859, '巳', '人生坎坷，谨慎为是。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6860, '巳', '和气纳祯祥，遐龄庆有常。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6861, '巳', '人到中年运亨通。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6862, '巳', '喜气盈盈，家室和平。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6863, '巳', '暮景多忧，心不安然。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6864, '巳', '木凋奈若何，涕洒泪仿徨。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6865, '巳', '花甲欠一春，此君归期去。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6866, '巳', '高山又一重，融和景色浓。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6867, '巳', '文昌照命，数诀入泮。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6868, '巳', '古稀之年，官非耗财。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6869, '巳', '房考之年。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6870, '巳', '福曜正照，粲然光耀。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6871, '巳', '享平安之福，绝门外之嚣。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6872, '巳', '动静有常，好景相送。', '[5960]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6873, '巳', '兄弟十人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6874, '巳', '生子克子，好坏同庆。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6875, '巳', '几阵香风生绣户，一轮明月照闺门。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6876, '巳', '寻师访友，无往不利。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6877, '巳', '甲子一周必寿数。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6878, '巳', '子登黄甲。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6879, '巳', '太平官职，眼前奏捷。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6880, '巳', '逢运之年方进步。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6881, '巳', '春风阳气，景物自如。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6882, '巳', '日转南楼夜未光，子规啼处断肝肠。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6883, '巳', '若远若近，依稀行程。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6884, '巳', '学得一技好手艺，从无人敢问前行。', NULL);
