INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6893, '巳', '乡科及第。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6894, '巳', '一个青龙共白虎，数声鹊噪与鸦鸣。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6895, '巳', '穷睇盼于中天，极游于暇日。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6896, '巳', '金年克妻，火年再娶方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6897, '巳', '癫疯之疾，前生恶报。', NULL);
