INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6899, '巳', '少年克妻，闷之如何。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6900, '巳', '数尽归西日，花甲加一春。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6901, '巳', '悠然无事饶生趣。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6902, '巳', '暮诵朝歌，太平之曲。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6903, '巳', '叹君寿上，花甲有二春。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6904, '巳', '流年不利，多困多滞。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6905, '巳', '时逢底绩，家门赫奕。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6906, '巳', '命带文昌，夫登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6907, '巳', '啾唧不免，灵童之戏。', '[8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6908, '巳', '辛勤日夜费精神，转发如今物色新。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6909, '巳', '注定参真入道，水土年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6910, '巳', '春风鼓舞，意相从舒。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6911, '巳', '祖业淡薄，数内先注。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6912, '巳', '腐艇休从沧海过，颠车莫向大街行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6913, '巳', '数该生子。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6914, '巳', '四子送老，三子挺秀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6915, '巳', '九岁十岁路坦夷，春日迟乐意。', '[9, 10]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6916, '巳', '忧闷既觉为安乐，梦忆昏昏今始明。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6917, '巳', '坐钓渭溪，财官着手。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6918, '巳', '际遇际亨，事多就绪。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6919, '巳', '贵人提携，事乃克济。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6920, '巳', '数该生子。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6921, '巳', '悠然无事，饶有生趣。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6922, '巳', '梅花吐秀，万卉争妍。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6923, '巳', '数中注定，职受异子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6924, '巳', '事乖从意外，破财不安然。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6925, '巳', '花蕊初红，不怕风雨。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6926, '巳', '兄弟十人，同父各母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6927, '巳', '惆怅复惆怅，年来运未来。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6928, '巳', '命有刑伤，妇之不幸。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6929, '巳', '兄弟五人，同父各母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6930, '巳', '虽然子来晚，亦可作家珍。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6931, '巳', '画饼难充饥，行人不相宜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6932, '巳', '征马板桥霜露冷，行人巫峡波浪涛。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6933, '巳', '连宵风雨阻行人，今日晴明趁早行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6934, '巳', '若问寿元事，六旬有二是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6935, '巳', '遇良医大痛不死。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6936, '巳', '吉曜相照，人物和畅。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6937, '巳', '姐妹同胎，相貌同近。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6938, '巳', '才展丝纶，羽扇纶巾。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6939, '巳', '否极泰来，万象更新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6940, '巳', '命带血迹关，祈祷自安然。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6941, '巳', '流年不利，当有灾晦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6942, '巳', '一去不能返，幽魂入黄泉。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6943, '巳', '三岁啾唧，不安宁兮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6944, '巳', '谋事顺利，谋之有益。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6945, '巳', '哒之职，必有变迁。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6946, '巳', '有妻当活离，缘薄不相宜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6947, '巳', '无端百舌闹枝头，恨报东风人在楼。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6948, '巳', '年寿七十而止。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6949, '巳', '房考之年。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6950, '巳', '乡科及第。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6951, '巳', '数该生子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6952, '巳', '运转时来，图谋有益。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6953, '巳', '父死之年，三年泣血。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6954, '巳', '青矜有分，得失无常。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6955, '巳', '喜吉之象，天道还转。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6956, '巳', '歌舞楼中声寂寂，今朝别去旧龙亭。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6957, '巳', '职授学校，荣任之誉。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6958, '巳', '数有徒弟，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6959, '巳', '堂上自有老慈亲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6960, '巳', '福来人共庆，咸道好春光。', '[44]');
