INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6962, '巳', '朦朦胧胧，安胞之中。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6963, '巳', '数止矣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6964, '巳', '小宋应占，二子何得。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6965, '巳', '物情得宜，春风桃李。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6966, '巳', '天上玉书照，地下失英雄。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6967, '巳', '有利无害，其人吉祥。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6968, '巳', '老年生于，数有所致。', '[68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6969, '巳', '官至御史，荣归画堂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6970, '巳', '知心可托堪息肩，不必忧闷问往年。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6971, '巳', '数止矣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6972, '巳', '解甲归田，文君当炉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6973, '巳', '数该生子。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6974, '巳', '快乐无求，顺利图谋。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6975, '巳', '吉亨之象，喜庆重来。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6976, '巳', '帝中一王侯，犀象军宣谋。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6977, '巳', '劲节苍松，历霜不改。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6978, '巳', '造化蒙起，设帐训生徒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6979, '巳', '寿止矣。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6980, '巳', '瑞气融和，景象非前。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6981, '巳', '甲子入户，春风重来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6982, '巳', '人间五个字，断送少年人。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6983, '巳', '闭户静坐，避凶始宜。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6984, '巳', '数该生子。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6985, '巳', '祖业难守，离祖兴家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6986, '巳', '南柯一梦。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6987, '巳', '温温恭人德，仁厚丈夫心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6988, '巳', '无边红紫，大地阳春。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6989, '巳', '否泰相逢，大往小来。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6990, '巳', '已司空中色，方知色是空。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6991, '巳', '南柯一梦，此年丧命。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6992, '巳', '吉星照闺门，动止皆有则。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6993, '巳', '择贤无方，出身偏房。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6994, '巳', '大数宜天命，加一是归期。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6995, '巳', '柔能克刚，斟酌而行便有功。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6996, '巳', '贵人相逢，事事有益。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6997, '巳', '野酒香花处处香，风流常醉乐村庄。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6998, '巳', '受太上老君之诀，斩阴间邪鬼之魂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (6999, '巳', '性急作事是非多，倚赖高人奈若何。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7000, '巳', '命如文君，再嫁也美。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7001, '午', '羡君雁塔题名早，应在朝中作栋梁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7002, '午', '利见大人，赐我荣福。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7003, '午', '振祖宗箕裘，启后人厚业。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7004, '午', '上林花发千家锦，妆阁梅开万户香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7005, '午', '为人心急性坚刚，威风凛凛志昂昂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7006, '午', '只说子春规啼过，谁知还在隔林柄。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7007, '午', '棠棣双双三五树，七枝七叶共树根。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7008, '午', '结发未完偕老愿，命中惟带一孤神。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7009, '午', '命带魁罡，兰房花谢。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7010, '午', '坐山莫要频回顾，忽见南山有白云。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7011, '午', '少年宜努力，老来徒悲伤。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7012, '午', '浓阴之象，未悉晴明。', '[15161]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7013, '午', '其人寿穷数尽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7014, '午', '前运不贫不贱，一生衣禄无忧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7015, '午', '腹蕴万卷书，足步青云时。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7016, '午', '一石打通名利塞，剑光直射斗牛墟。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7017, '午', '土木之年进庠，金火之年恩贡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7018, '午', '数有九子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7019, '午', '囊中有物宜收拾，暗有群邪合伴谋。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7020, '午', '花色不鲜因雨久，月华来现阴云多。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7021, '午', '生子之年。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7022, '午', '老椿先被风吹折，暗自凄凉实悲伤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7023, '午', '金鳞不是池中物，一遇风云便化龙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7024, '午', '为人疏财重义，舍短从长为善。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7025, '午', '孔怀缘分少，孤雁往南飞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7026, '午', '一日祯再日拜。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7027, '午', '晦气消除人事安，平安清吉福如常。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7028, '午', '钓而不网当仲尼。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7029, '午', '数有十子，送老为奇。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7030, '午', '问名虚难成，问利实有益。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7031, '午', '半帘风卷杨花舞，温饱晚年乐有余。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7032, '午', '万里乾坤双行李，百年世上只单衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7033, '午', '偷去三十六，减少兴家机。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7034, '午', '涧边老松，偏耐风雨。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7035, '午', '一名真造化，名列国学中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7036, '午', '日行中天，阳回宇宙。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7037, '午', '任谋密用宜潜藏，逆理非为恐见伤。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7038, '午', '谋之克谐，纵横之徒无阻碍。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7039, '午', '结克未完偕老愿，夫妻再配得齐眉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7040, '午', '金榜题名，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7041, '午', '阴阳照命，恩自九重。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7042, '午', '姊妹六人，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7043, '午', '福星照耀，菱花绝尘。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7044, '午', '数有九子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7045, '午', '文星场畔有化龙，身着蓝袍入泮宫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7046, '午', '板桂蟾宫远，探珠出海波。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7047, '午', '祖宗厚业，受用终身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7048, '午', '身居禅院地，亦得沐皇恩。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7049, '午', '兄弟四人，同象不同声。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7050, '午', '弦断再续，两度姻缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7051, '午', '吉星相照，家室安宁。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7052, '午', '杜甫胸流三峡水，功名只许一青。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7053, '午', '虑善而动，动无不臧。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7054, '午', '飞符照命，闺中恐有是非来。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7055, '午', '入赘成婚，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7056, '午', '大征出旅威赫赫，清光入阵志扬扬。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7057, '午', '为人舌直，肝胆安然。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7058, '午', '阳气方升，飞龙在天。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7059, '午', '阳春回谷，万物生辉。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7060, '午', '不图月殿扳丹桂，只效萧曹更名扬。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7061, '午', '休嗟荣辱生平事，老景安闲逸与高。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7062, '午', '咸亨利贞，坤人吉庆。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7063, '午', '一生无大患，到底处安然。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7064, '午', '兄弟四人，中断离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7065, '午', '聪明果让人，早岁淹沉恨无恁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7066, '午', '石润苍松鼓晨钟，清风明月乐融融。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7067, '午', '操持未久鬓先斑，一点雄心尚未闹。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7068, '午', '阵列旌旗显，名威虎豹门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7069, '午', '斯时称孤子，方当不幸。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7070, '午', '布地金棠满，安享福无疆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7071, '午', '麟趾呈祥，天下文明。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7072, '午', '福自天来，不由人造。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7073, '午', '天地交泰上下志，同盛德业禄无穷。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7074, '午', '千里之才，终朝知遇。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7075, '午', '一年二顺，老来之荣。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7076, '午', '至哉坤元，幽人贞吉。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7077, '午', '如龙至渊，直上九霄。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7078, '午', '似流之至，都自安然。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7079, '午', '莫以有女嫌数，中原无子息。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7080, '午', '登科未迟，人随天意。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7081, '午', '亲生之子皆成梦，式谷之儿送我终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7082, '午', '红鸾相照。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7083, '午', '有分功名宜泮水，时来足下便生光。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7084, '午', '时未至兮君宜守，发财发福自有期。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7085, '午', '仙桃且图颜色鲜，嫩柳如今已发芽。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7086, '午', '千里片帆轻，浪平波不惊。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7087, '午', '九九且穷岁，金马招缠各有时。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7088, '午', '韬谋超管乐，演艺胜孙吴。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7089, '午', '暗室潜修，福照点头。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7090, '午', '逢猴之年方进步。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7091, '午', '桑榆暮景荣，松柏耐岁寒。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7092, '午', '堆金积玉，享福过入。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7093, '午', '宝镜生尘暗实多，欲要光明再重磨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7094, '午', '强裸呱呱已丧亲，泣血亲临承重恩。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7095, '午', '解组谁逼，安度晚年。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7096, '午', '见龙在田，利见大人。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7097, '午', '一子送老，挺秀之儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7098, '午', '篱菊舒独元亮光，江忽起季思情。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7099, '午', '上苑花开向午艳，色逾鲜枝发叶荣。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7100, '午', '云淡风轻，景物澄清。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7101, '午', '命中少福，兴家要俭。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7102, '午', '借问一生身外事，遇丑之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7103, '午', '此刻生人，死于金水之年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7104, '午', '云山高耸，孤雁高飞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7105, '午', '温道鱼竿丝纶弱，钓得金鲸已上钩。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7106, '午', '有王佐之才，无管氏之望。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7107, '午', '有治世功名之望，无科甲两榜之荣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7108, '午', '步履无，先忧后喜。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7109, '午', '灼灼宫花多喜喜，辉辉意气色扬扬。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7110, '午', '德厚业广，运到平康。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7111, '午', '漫道西湖好，人有路崎岖。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7112, '午', '王子之科，乡试中式。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7113, '午', '厚礼福神之年着，若无若有其所欲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7114, '午', '优而不忧，堪笑盈亏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7115, '午', '金年克妻，水年再娶。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7116, '午', '严霜坚冰，太阳一出便熏人。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7117, '午', '勤俭持家衣禄足，晚年跨灶有儿郎。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7118, '午', '人间欲避风波险，一日内波十二时。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7119, '午', '顺利福相随，祸灾永不侵。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7120, '午', '金门听玉漏，新日皎冰壶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7121, '午', '蒙雨连夜落，先压一枝萱。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7122, '午', '聘妻未识妻，其妻先死之。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7123, '午', '兄弟四人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7124, '午', '生子之年。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7125, '午', '寿元八旬足矣。', '[80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7126, '午', '福寿安然，有为克济。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7127, '午', '无意之得，先难后易。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7128, '午', '皆因风雨多冷落，欲渡清溪欠便船。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7129, '午', '正妻不结子，副妻有两儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7130, '午', '美德持家，旺夫益子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7131, '午', '乙酉之年，三场捷报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7132, '午', '名登黄甲。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7133, '午', '花开正遇春三月，只遇风夜雨飘。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7134, '午', '破财不利，大耗人命。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7135, '午', '三子送终，先天注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7136, '午', '如入深山平，地涌出黄金。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7137, '午', '问名三旬年，垂手可得时。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7138, '午', '子来四旬外，得之始实果。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7139, '午', '三子送老，一子挺秀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7140, '午', '命犯孤福，男子不齐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7141, '午', '至今赌不省，耗去许多金。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7142, '午', '一乐之福，晚年足欲。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7143, '午', '明月半窗虚，清风一枕凉。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7144, '午', '春风满面，啾唧一空。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7145, '午', '春风浩荡沾福厚，财禄于今亦自丰。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7146, '午', '正室无子，副室一儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7147, '午', '英雄际会，时有可为。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7148, '午', '数该生子。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7149, '午', '今朝装束离尘去，一声长叹归白云。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7150, '午', '徒弟六人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7151, '午', '姊妹二人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7152, '午', '上山多费力，有树可板枝。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7153, '午', '笑煞从前总是空，今朝别去又何如。', '[80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7154, '午', '本年火年，破财方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7155, '午', '此时兴发，失少得多。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7156, '午', '乡试中选。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7157, '午', '进五退四，只得其一。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7158, '午', '金木之上，破财方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7159, '午', '所亲者正人，所取者仁义。', '[32, 33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7160, '午', '好为他人，做嫁衣裳。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7161, '午', '注定坤人无姊妹，闺中独秀称大奇。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7162, '午', '轻投人爵修天爵，远寄青云伴白云。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7163, '午', '一日晴明一日阴，阴晴无定好忧心。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7164, '午', '由孔孟而入孙吴，名成其身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7165, '午', '命受两妻火命土命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7166, '午', '母赴瑶池，三年泣血。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7167, '午', '姊妹六人，前有数定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7168, '午', '不幸二亲欠俱寿，自成自立苦伶仃。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7169, '午', '不堪耗散妇人手，区区有口不能言。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7170, '午', '大数已定。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7171, '午', '雨水初收日淡红，梅花香里逐春风。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7172, '午', '命悬东壁上，西风落叶满天愁。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7173, '午', '终身数定荣枯事，梅花雪缀可知春。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7174, '午', '知进知退，居安虑危。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7175, '午', '三雁同飞各一方。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7176, '午', '将军逢桥断险路。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7177, '午', '借问一生身外事，遇鼠之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7178, '午', '严亲归西，人子向恬。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7179, '午', '数定无生子，单生一女傲成家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7180, '午', '松柏秀茂，仪表超群。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7181, '午', '洞庭月色转西厢，箫声借凤凰。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7182, '午', '幼年失估，莫大刑伤。', '[8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7183, '午', '雪遍琼瑶白满楼，台高十丈主丧服。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7184, '午', '身有高人轻借力，一生衣禄永无忧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7185, '午', '鸳鸯飞水面，花落又花开。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7186, '午', '急水孤舟，片时又遇打头风。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7187, '午', '安静且无咎，恩求福有灾。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7188, '午', '会试中式。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7189, '午', '官到学院，荣归画堂。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7190, '午', '无忧目下事难济，借力轻轻运转时。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7191, '午', '将星照命，弓马入泮。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7192, '午', '身出偏房，嫡庶有分。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7193, '午', '飘飘风吹玉器浓，一双鸿雁岭南来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7194, '午', '易日数止，岂不借哉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7195, '午', '身入泮池。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7196, '午', '一番思度一番忧，事欲忧时便可忧。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7197, '午', '老来致仕归山隐，一片舟孤逐水流。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7198, '午', '生子之年。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7199, '午', '优游无事日，得福自多时。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7200, '午', '四十年来还转红，贵人指引倍亨通。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7201, '午', '文就武挟，策入泮宫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7202, '午', '好花开得锦丛丛，天气人和乐意浓。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7203, '午', '大数已定，不用再查。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7204, '午', '辛苦之妇，何当命薄。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7205, '午', '子多且贵，乐莫大焉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7206, '午', '春深桃李，到处成蹊。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7207, '午', '钦命典试。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7208, '午', '美菊满园虽雅媚，松筠独翠晚来香。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7209, '午', '同年踪迹落风尘，一旦辞归作故人。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7210, '午', '一往奔西，行不复返。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7211, '午', '平生立志在四方，走遍江山千万里。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7212, '午', '太白状元任作为，一生快乐杏花村。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7213, '午', '事业经纬，既济苍生。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7214, '午', '少年不遇明花景，壮岁欣逢大有年。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7215, '午', '姻缘非一姓，佳人重又重。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7216, '午', '幼年丧父方合。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7217, '午', '二子送老，先天定数。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7218, '午', '父死故于水年，母生年属金方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7219, '午', '操持未久鬓先斑，一点雄心尚未闲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7220, '午', '如日初红，正盛之象。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7221, '午', '卜君阳年，许以古稀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7222, '午', '满园架蔷薇，花开十姊妹。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7223, '午', '自古立门高且大，倍增光处羡儿孙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7224, '午', '色丽黄金，腰横金璧。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7225, '午', '善庆有余，福德流芳。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7226, '午', '命带财星逢二德，一生福禄永绵绵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7227, '午', '头面不周全，前生已注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7228, '午', '泪流粉面，破滞残妆。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7229, '午', '命带刑伤，四旬之外得子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7230, '午', '有意无意，自首吟哦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7231, '午', '日坐书斋静，身心两自闲。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7232, '午', '时逢暖日景和平，人物光华地杰灵。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7233, '午', '祯祥自有，福禄无边。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7234, '午', '紫荆开五朵，田氏后庭花。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7235, '午', '事事亨通，太平大吉。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7236, '午', '闺中祯祥，纳福有余。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7237, '午', '君子当思吉，交辞利见刚。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7238, '午', '此刻注定贵妇人，水年入泮木年式。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7239, '午', '如天相照画堂新，阳和宇宙尽沽恩。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7240, '午', '命有将星，叶文就武。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7241, '午', '少年运叶如阳空，中运平平老景隆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7242, '午', '无母何恃，欲养难存。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7243, '午', '姊妹七人，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7244, '午', '子规啼落数头月，一梦南柯嗟不成。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7245, '午', '哀哉哀哉，萱草尘埃。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7246, '午', '未知妻命，先当受克。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7247, '午', '行藏顺遂，万物皆新。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7248, '午', '数有九子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7249, '午', '命主刑伤，五旬之外得子。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7250, '午', '春深桃李，到处成蹊。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7251, '午', '问名无成，问利有益。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7252, '午', '自然无不利，不顺也成功。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7253, '午', '两朵名花，一双姊妹。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7254, '午', '疏食饮水贫而乐，失水蛟龙志未伸。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7255, '午', '海润断桥，杨柳遮烟时未到。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7256, '午', '若问阳年有几许，尔生之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7257, '午', '倘行阴功，寿延一纪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7258, '午', '能克已不能屈己，能饶人不能让人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7259, '午', '幸观乐利之荣，永享太平之福。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7260, '午', '姊妹一人，掌上明珠。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7261, '午', '命中主刑伤，六旬外得子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7262, '午', '蕙茨帐生寒，须防藜咎。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7263, '午', '早岁已知多险病，福星相照得长年。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7264, '午', '阴阳已分，须可以行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7265, '午', '勤俭成家，毫厘不失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7266, '午', '花堂萱草谢，杜鹃啼血泣。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7267, '午', '持已磊磊落落，行藏不疾不徐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7268, '午', '姊妹二人，一人不存。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7269, '午', '五彩绳牵月老话，京兆画眉许张郎。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7270, '午', '离祖成家，怡然自乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7271, '午', '粟布有余，大称心怀。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7272, '午', '创业难，守业更难。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7273, '午', '陶令喜栽彭泽菊，严陵思钓富春鱼。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7274, '午', '波涛历卷三千里，福禄绵绵骨肉残。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7275, '午', '钦命典武。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7276, '午', '行恶运一落千丈。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7277, '午', '惟愿月明花正好，谁知风急夜生寒。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7278, '午', '虽然子来晚，亦可作家珍。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7279, '午', '人遇时来光彩现，花逢春到色更新。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7280, '午', '一生劳禄为他人，不禄无亏身不宁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7281, '午', '风卷荷叶碎又圆，圆碎总是风定缘。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7282, '午', '乙卯之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7283, '午', '江中风转好行舟，拿稳征帆远远游。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7284, '午', '三春花柳，风雨之中。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7285, '午', '皎月复圆，圆之复缺。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7286, '午', '梅花雪后，已自超群。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7287, '午', '赖有根基，得庇初年。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7288, '午', '大江滚滚，涉履安然。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7289, '午', '佛在西天，清闲悟禅。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7290, '午', '树小枝高，根浅摇折。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7291, '午', '守静宜恬退，轻狂惹是非。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7292, '午', '大数已定。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7293, '午', '扁舟一叶鸿毛小，寄语舟人把舵穿。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7294, '午', '山野晓烟清气回，桃林终日且和平。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7295, '午', '金阙书名多得意，食琼餐素福无双。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7296, '午', '风生浪平，遂息休心。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7297, '午', '梅剪杏秀，阳春回来。', '[36, 37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7298, '午', '丙午之年，三场捷报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7299, '午', '姊妹二人，姻缘配合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7300, '午', '一朝春尽红颜老，花落人亡两不知。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7301, '午', '渊明解印归山隐，诗酒黄花达性情。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7302, '午', '恍恍惚惚，不但人嗔且有鬼。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7303, '午', '年来岁未定，时兴又时低。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7304, '午', '能扫江汉，功积维新。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7305, '午', '年逢五九，优及椿庭。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7306, '午', '花开满院无枝叶，独发新芽春来到。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7307, '午', '不须操武略，名利在西方。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7308, '午', '任君唱咏且高歌，闺中和奏乐如何。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7309, '午', '小舟巨载被风浪，虽不颠覆也惊慌。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7310, '午', '四雁分行，吴楚历浙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7311, '午', '虽然子息迟，迟之子息奇。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7312, '午', '河边杨柳暮生烟，一段愁思梦相回。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7313, '午', '元亨利贞吉，西方喜气生。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7314, '午', '虽有手足全，即如陌路人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7315, '午', '全凭阴阳成终始，竹畔松阴结生子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7316, '午', '披麻无情，门庭闹乱。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7317, '午', '洛阳春色，景物宜人。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7318, '午', '江外青山利可求，前程进步在他舟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7319, '午', '武举选守府，人生之大幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7320, '午', '三九之年遇贵人，相赖提携显荣归。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7321, '午', '宝镜重磨，光景非旧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7322, '午', '帘前鸦鹊噪，报喜又报凶。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7323, '午', '雪压关山总末收，狂风吹断白云头。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7324, '午', '官至游府，逐美意如。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7325, '午', '人游花谷中，应接还不暇。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7326, '午', '兄弟二人，秦楚不同盟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7327, '午', '晚年生子，人之大幸。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7328, '午', '池水蛟龙身暂屈，埋头藏尾混鲸鳞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7329, '午', '老来得娇儿，黄天佑我子。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7330, '午', '名登黄甲。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7331, '午', '气息奄奄，徒劳度日。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7332, '午', '不为天下奇，定作人间女丈夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7333, '午', '上天福佑，喜庆相逢。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7334, '午', '桃源天色暖，和风丽日映千秋。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7335, '午', '峨眉巍峨，身隐无返。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7336, '午', '亢龙生晦吝，吉凶悔亡命。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7337, '午', '椿庭一病成回首，笑夸语稀梦里逢。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7338, '午', '妻配羊命，方能偕老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7339, '午', '六九之年晚运奇，不惟有寿福相依。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7340, '午', '三八之年大运通，从此立业事兴隆。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7341, '午', '数定原来少欠儿，幸有娇侄膝下娱。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7342, '午', '人逢古稀君未足，向由少八是归期。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7343, '午', '守着几亩田，安了一生身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7344, '午', '闺中弱女恨凄凄，风雨淋漓草色萎。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7345, '午', '病符相照，势如黄叶迎寒风。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7346, '午', '姊妹八人，数有前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7347, '午', '幽闲岁月，足称多福。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7348, '午', '点灯照路，来往无疑。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7349, '午', '翰墨流芳满胸才，不遇孙吴实可哀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7350, '午', '麟儿生下，天报喜人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7351, '午', '清明天气霭，雨过倍精神。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7352, '午', '春云西北起，玉雁岭南来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7353, '午', '庚子之年，三场捷报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7354, '午', '喜怒不形，物我无知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7355, '午', '当宴鹰扬。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7356, '午', '金菊流芳，兰蕙生香。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7357, '午', '进步晦生多不足，危前失后有春风。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7358, '午', '姊妹九人，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7359, '午', '轻抛人爵修天爵，远山青云伴白云。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7360, '午', '数止于此。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7361, '午', '薏苡被谤，可以思退竟无忧。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7362, '午', '自看天心，哭尺天涯近。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7363, '午', '点灯于当风，几灭其焰火。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7364, '午', '武试中选。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7365, '午', '一登平稳地，从此少风波。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7366, '午', '勿登春来至，行见春梅花。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7367, '午', '花卉满园红，人游乐无穷。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7368, '午', '姊妹八人，先损其一。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7369, '午', '冲天大鹏纵鱼跃，一息千里回旋高。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7370, '午', '降福除灾，喜至庆来。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7371, '午', '演武及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7372, '午', '家业浩大，何怕蚤破耗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7373, '午', '兄弟四人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7374, '午', '前程桃李漫成，红红白白斗芳菲。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7375, '午', '一朵灯花报喜来，进前无复有徘徊。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7376, '午', '父先故于木年，母生年属水方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7377, '午', '优之复喜，先难后易。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7378, '午', '中年而亡，先天定数。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7379, '午', '生子之年。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7380, '午', '武试中式。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7381, '午', '柳媚花明，赏心乐事。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7382, '午', '芝兰挺秀，还喜松筠映玉堂。', '[56, 57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7383, '午', '当宴鹰扬。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7384, '午', '喜得后园桃李茂，玉堂金马可成当。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7385, '午', '披麻无情，门庭闹乱。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7386, '午', '子规不隐声，啼出好伤心。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7387, '午', '行藏不傲不骄，动上半文半武。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7388, '午', '雪浪沾入寒，金鱼入手难。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7389, '午', '好花锦色丛，天意晴和人意浓。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7390, '午', '财如春水源源进，福似朝花朵朵鲜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7391, '午', '武科中进。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7392, '午', '发强刚毅，内助气轩。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7393, '午', '欢娱正好嫌夜短，泪洒西风解佩环。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7394, '午', '前荆后棘，移步不得。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7395, '午', '情效王羲之，懒系皇家汉。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7396, '午', '树植根基深，不怕风当头。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7397, '午', '半夜风云卷，五更云散明。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7398, '午', '知君老至精神壮，家业重兴子子昌。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7399, '午', '官至参将，不能高擢。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7400, '午', '戊子之年，不能捷报。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7401, '午', '兄弟三人，方合此数。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7402, '午', '炊白梦可伤，千里泪万行。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7403, '午', '命与伯道同，无子非定数。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7404, '午', '木火之年，进场方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7405, '午', '官至把总，必有变幻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7406, '午', '若知石中真有玉，下知造化识露机。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7407, '午', '其时月黑猿声切，微雨沾衣泪暗流。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7408, '午', '庞物敷施人物阜，人间齐口涌升平。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7409, '午', '红日上三竿，阴皆消灭。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7410, '午', '安如磐石，福禄屡增。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7411, '午', '摇摇不定风敲竹，寂寂无声雨打花。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7412, '午', '杨花扑面，三年泣血。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7413, '午', '数有四子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7414, '午', '时花和暖，福禄相从。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7415, '午', '太阳照耀，人物光华。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7416, '午', '君子有先见，徒劳无往还。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7417, '午', '数该生子。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7418, '午', '佳子珠翠盈满箱，只为他家富贵场。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7419, '午', '名登武科。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7420, '午', '兄弟二人，我居幼。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7421, '午', '一字当记日赌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7422, '午', '火星照命，官职高升。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7423, '午', '惆怅已多，劫神相催。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7424, '午', '行藏迥出人间事，卓然不肯居人后。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7425, '午', '名园种松竹，节操自盘根。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7426, '午', '姻缘早配名门子，红叶传书朵朵香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7427, '午', '未能长驱，车脱其辐。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7428, '午', '刑伤于早年，发福于中运。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7429, '午', '罗符照命，晚度相生。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7430, '午', '削发作尼僧，前生善果因。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7431, '午', '宇宙蒙晦，江山无色。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7432, '午', '勿多言勿多语，休管人间是与非。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7433, '午', '好运恰逢期，福禄处处同。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7434, '午', '昏昏黑黑，鬼魅现形。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7435, '午', '老椿忽作游仙客，难免三年泣血悲。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7436, '午', '命有五子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7437, '午', '膝下少斑烂，子嗣当式杀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7438, '午', '数逢大缺，子规啼落楼头月。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7439, '午', '六九之年运已亨，财禄之利更相隆。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7440, '午', '不足之心，难以自慰。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7441, '午', '保登武场。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7442, '午', '秋月初出林，江山气象新。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7443, '午', '财帛积丰，暮景兴隆。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7444, '午', '不文不武不鲜妍，到老生涯自在天。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7445, '午', '三策献于皇庭，沾九重之雨露。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7446, '午', '云暗月明，花开雨晴。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7447, '午', '朝攻暮课，诸吉悉至。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7448, '午', '高楼要在前村过，走过前村又一村。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7449, '午', '渡过危桥，百虑始消。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7450, '午', '病入膏育，屡医难治。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7451, '午', '劳心泰早福来迟，巧中还是拙还非。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7452, '午', '严慈受浩敕之荣，注定母先赴九京。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7453, '午', '月下琼花香可笑，日高梅影叶还疏。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7454, '午', '晓月寒烟迷作径，悲风带点征帆。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7455, '午', '去淫即可延寿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7456, '午', '红莲初小水，春色草怕霜。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7457, '午', '为出四肢病，防生得血声。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7458, '午', '亲近贵人，百事皆宜。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7459, '午', '有人相欺，囊中有失。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7460, '午', '二老膺造敕之荣，注定父先母后故。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7461, '午', '未计登科甲，有人让出头。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7462, '午', '千金富贵实，七百数荣身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7463, '午', '借问一生身外事，遇犬之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7464, '午', '往问前村路，还从暗里行。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7465, '午', '红粉绫纬纱，喜事何足任。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7466, '午', '雪满荒郊外，忧心切切时。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7467, '午', '枝头初蕊红芽放，识得春风景色佳。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7468, '午', '南极祥光照我身，到此古稀临。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7469, '午', '数该生子。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7470, '午', '院月寒烟迷行径，临风带雪点征帆。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7471, '午', '数该生子。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7472, '午', '别于庶人，实系兵家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7473, '午', '龙蛇潜伏时行路，喜气初临造化新。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7474, '午', '否极终成泰，赛后运不通。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7475, '午', '我有五岁未成童，不幸慈母入幽踪。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7476, '午', '劳心又劳力，持担未有人。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7477, '午', '深山有木，工师欲求。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7478, '午', '少年行欢乐，根基救前人。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7479, '午', '萤火不烧墙上草，利刀难杀镜中人。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7480, '午', '考试无常，得失有命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7481, '午', '黍稷盈仓，金玉满堂。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7482, '午', '寒气将回还先报喜，雪余欢笑赏红梅。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7483, '午', '年已古稀，竭力朝廷。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7484, '午', '其人事业，传于不朽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7485, '午', '谋为顺遂般般合，作事亨通着着高。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7486, '午', '解组林下，心逸日休。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7487, '午', '鹏飞霄汉云程远，腰金衣紫近星台。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7488, '午', '为人耿介作事公，心高志更高。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7489, '午', '瑞气谒金炉，神仙造化扶。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7490, '午', '科场得意，必中科举。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7491, '午', '椿树已颓风木恨，难免三年泣血悲。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7492, '午', '造化天然为女命，夫荣子秀福绵绵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7493, '午', '历尽江湖苦，买田置业丰。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7494, '午', '洞触阴阳元化成，天地奇功玄妙中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7495, '午', '根基敦厚，可以守成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7496, '午', '铁笔一枝写人间，金钱三个预乾坤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7497, '午', '房考之年。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7498, '午', '科甲及第。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7499, '午', '三八之年遇贵人，相助提携福转荫。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7500, '午', '父命属蛇，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7501, '午', '兄弟八人，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7502, '午', '多有助天德，善主频繁民。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7503, '午', '芳名远播，恩泽之荣。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7504, '午', '一笑马前人事好，几多风雨在鱼矶。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7505, '午', '厦门庭增彩，置田地生荣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7506, '午', '九死一生，吉神护佑。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7507, '午', '一点阳春送信来，前程堪进勿徘徊。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7508, '午', '方知和弦乐，岂期竟鼓盆。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7509, '午', '妻配猴命，方能白首。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7510, '午', '眉头不挂烦恼，心境自然安舒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7511, '午', '年已九旬，不必问往年。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7512, '午', '土木偶为伴，焚香好诵经。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7513, '午', '数该丧严亲，难留在画堂。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7514, '午', '好运正兴，玉出荆山色更明。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7515, '午', '数该生子。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7516, '午', '科甲及第。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7517, '午', '身入泮林。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7518, '午', '履道坦坦，幽人贞吉。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7519, '午', '虽然未远青云志，可羡人间一富翁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7520, '午', '武场捷报。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7521, '午', '巧言令色，成人之美。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7522, '午', '谢却人间事，常纳祯祥福。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7523, '午', '柳媚花明，赏心乐事。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7524, '午', '松柏亭亭上，鸾凤婆乐少。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7525, '午', '镜破合圆，虽圆不美。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7526, '午', '武场捷报。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7527, '午', '冲天志不得，惟田又惟桑。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7528, '午', '项庄舞剑，意在沛公。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7529, '午', '工师作室，历不成居。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7530, '午', '为着别故人，空作百年计。', '[86]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7531, '午', '庚午之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7532, '午', '燕子又飞花正长，园林吐锦百花香。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7533, '午', '风流逸客少年光，更多对酒野花香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7534, '午', '惊恐成病，马陷泥沙。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7535, '午', '五色绳牵月老话，画眉京兆许张郎。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7536, '午', '数未满旬，主丧严亲。', '[9]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7537, '午', '仰托余庆，少年风光。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7538, '午', '数中十二子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7539, '午', '姊妹四人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7540, '午', '和风生细雨，泮水耀青毡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7541, '午', '兄弟二人，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7542, '午', '路途有崎岖，幸得渔人引。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7543, '午', '乡试独步。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7544, '午', '灾消祸除，喜事频至。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7545, '午', '生子之年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7546, '午', '荣登上品，学敌万人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7547, '午', '步步挣挫，坎坷厉过。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7548, '午', '家道雍和，内助之力。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7549, '午', '六九之年运已通，贵人指引福自红。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7550, '午', '辛酉之年，乡科中选。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7551, '午', '惟安惟静，平安之庆。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7552, '午', '严亲弃世日，人子泣血时。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7553, '午', '笔下倒流三峡水，胸中惟富五车书。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7554, '午', '兄弟六人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7555, '午', '国学驰名日，鸿列耀青毡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7556, '午', '花发上林，锦绣炫目。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7557, '午', '杏林春日暖，冠带自天来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7558, '午', '时逢春色，十分佳景。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7559, '午', '钦命典试。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7560, '午', '当宴鹰扬。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7561, '午', '口不进禄，空余紫骨。', '[95, 96]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7562, '午', '若问平生名利事，标名光耀国学中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7563, '午', '天边问明月，几岁缺不圆。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7564, '午', '凌空忘世味，洪恩一命来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7565, '午', '鸳鸯两分飞，独立溪边影自孤。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7566, '午', '若问平生事，上苑花开别样红。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7567, '午', '不幸父亡，三年泣血。', '[351]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7568, '午', '恰似风前柳，犹如雨打萍。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7569, '午', '众盛且弱，即富且康。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7570, '午', '武试中式。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7571, '午', '谋事在人，成事在天。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7572, '午', '一腔热血涌，挥金满面春。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7573, '午', '秦楚不和，兴兵结怨。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7574, '午', '遐龄暮景宁，无风烛之忧。', '[81]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7575, '午', '运至高催官爵显，荣封腰系又生香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7576, '午', '徒弟四人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7577, '午', '鹿鸣之宴，又兆熊黑。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7578, '午', '父死之年，昊天罔极。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7579, '午', '武场得意，必中科举。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7580, '午', '千里片帆轻，浪平波不惊。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7581, '午', '数有一子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7582, '午', '雅志寄于腊梅花，雪气清爽淡胸中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7583, '午', '红鸾相照。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7584, '午', '风传刻漏星河落，月上梧桐雨露清。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7585, '午', '生子之年。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7586, '午', '千里月华明，寒鸣栖复惊。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7587, '午', '明珠未出海，涵养天真且自宽。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7588, '午', '湘江烟雨波涛阔，玉雁高飞任来去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7589, '午', '梨花院落三更月，杜鹃啼散五更风。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7590, '午', '枯木发新枝，天增人寿命。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7591, '午', '经史向市，欣然乐于世。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7592, '午', '相夫而高大门庭，拮据而克享其子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7593, '午', '名进宫墙，弓马入泮。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7594, '午', '椿枝一折，泣血三年。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7595, '午', '御街献策三千丈，金榜题名独占先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7596, '午', '一乡为故老，冠带幸留恩。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7597, '午', '吉星高照，人事凑合。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7598, '午', '兄弟五人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7599, '午', '仁慈通玄，身列道全。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7600, '午', '数有一子，送老难齐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7601, '午', '武场中式。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7602, '午', '轻风能便借，喜笑见前程。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7603, '午', '女儿鸾风真奇才，旺夫益子发大家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7604, '午', '泮水芹香今朝采。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7605, '午', '万花丛中，应接不暇。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7606, '午', '敏颖入泮宫，威略展孙昊。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7607, '午', '几年奔走名扬，今年方得安康。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7608, '午', '数定前乾真出奇，总无一子结枝头。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7609, '午', '日落西山人影灭。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7610, '午', '思父不见，泣血三年。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7611, '午', '不得其志，渊明东归。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7612, '午', '老椿已折，三年泣血。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7613, '午', '武场中式。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7614, '午', '功名落少成，出家觅黄金。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7615, '午', '朝夕餐，美在其中。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7616, '午', '生平仁德清，文章及身功。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7617, '午', '招得水火之子方合。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7618, '午', '韶光明媚，物色更新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7619, '午', '解组林下，身日逸休。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7620, '午', '衣沾芹泮露，袖惹御烟浮。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7621, '午', '安常处顺，得意倍常。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7622, '午', '胸中难藏宿，口直心宜直。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7623, '午', '姊妹四人，姻缘各配。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7624, '午', '早起夜卧宁，休息育神功。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7625, '午', '初运有成有败，老来乃炽乃昌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7626, '午', '妻财致富，人之大幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7627, '午', '桃红柳绿，大称心怀。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7628, '午', '天有不测风云，人有旦夕祸福。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7629, '午', '武场入泮。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7630, '午', '椿树枯矣，三年之悲。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7631, '午', '无心而得，无心而失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7632, '午', '三场捷报，乡科及第。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7633, '午', '数未满旬，何亡之速。', '[9]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7634, '午', '识字能文，女中才子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7635, '午', '通先圣妙理，定人间休咎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7636, '午', '田连阡陌，家业兴隆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7637, '午', '劳碌心闲事不闲，三分火性逐心偏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7638, '午', '数有八子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7639, '午', '早起夜卧宁，休息育神功。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7640, '午', '数止浮云去。', '[77]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7641, '午', '木年父命终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7642, '午', '正好倚楼观夜月，谁知西面起乌云。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7643, '午', '雪压椿枝，三年泣血。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7644, '午', '火木年出家方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7645, '午', '高枕北窗下，自有大吉人。', '[87, 88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7646, '午', '投网捕鱼，兔则接之。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7647, '午', '朦朦又胧胧，山色有无中。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7648, '午', '名进贤关，文章入泮。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7649, '午', '武举任千总，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7650, '午', '粟帛盈仓，有实无虚。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7651, '午', '衣禄不关心，克享菩提福。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7652, '午', '佳人七姓副室多。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7653, '午', '出身荣华之地，命当诗礼之家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7654, '午', '喜事相临，流年之庆。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7655, '午', '雪压椿枝，三年泣血。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7656, '午', '兄弟恰恰，又入泮宫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7657, '午', '黄叶于秋林，鱼子涸辙。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7658, '午', '将队之中有个名，先天注定一兵丁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7659, '午', '兄弟三人方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7660, '午', '是年登科。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7661, '午', '猴年文昌照命，青不换布衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7662, '午', '蹉跎时不利，欲进且难前。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7663, '午', '赋性纯和，行遵矩度。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7664, '午', '一枕和风初，佳人报花开。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7665, '午', '园林春花，千红万紫。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7666, '午', '全凭阴陟生慈念，自有麟儿入梦来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7667, '午', '前棘后棘，红紫光辉。', '[18, 19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7668, '午', '春光明媚，红绿并新。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7669, '午', '助良人之才，纳闺中之福。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7670, '午', '红鸾交白虎，吉里又藏凶。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7671, '午', '火年伤妻，土年再娶方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7672, '午', '雪压椿枝，三年泣血。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7673, '午', '蹉跎已数年，一朝复还原。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7674, '午', '姻缘长短皆前定，月缺花残数不饶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7675, '午', '福德吉星临，门庭喜气多。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7676, '午', '十一丧严亲，幼年大不幸。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7677, '午', '轻抛人爵修天爵，还望青云伴白云。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7678, '午', '岁亨通甲子，遗下一双儿。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7679, '午', '命带文昌，夫登科甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7680, '午', '一字须忌之日刑。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7681, '午', '谢却人间事，常纳祯祥福。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7682, '午', '拥厚实似无，无求人多乐。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7683, '午', '堪羡运转有为时。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7684, '午', '注定贵妇人，夫入泮池中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7685, '午', '不当进步且盘桓，得意之中欠欢乐。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7686, '午', '琴无且意，皆因弦断。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7687, '午', '琢磨成功，皆成大器。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7688, '午', '琴棋从我好，诗酒任君行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7689, '午', '文昌照命，青衣换布衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7690, '午', '天哭催人，有伤骨肉。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7691, '午', '作事常存三尺法，见人浑是一团春。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7692, '午', '欲成夫子兴家业，信是人间女丈夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7693, '午', '梅花初发，引得福来。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7694, '午', '饱食暖衣，无求之乐。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7695, '午', '乡科及第。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7696, '午', '是年弦断。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7697, '午', '生财有道存忠厚，克己无私体至公。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7698, '午', '扬眉吐气是斯年。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7699, '午', '命有四子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7700, '午', '韶光明媚物色新。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7701, '午', '命中少兴，兴家要俭', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7702, '午', '一番春雨露，杨柳正芳菲。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7703, '午', '夫荣子秀乐锦宫，财禄定无穷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7704, '午', '逢好运把精神展，遇敌方知正始雄。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7705, '午', '此年游泮，中年得志。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7706, '午', '财多情薄，只寡合少。', '[58, 59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7707, '午', '荆棘当前，进退两难。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7708, '午', '祖父之业不守，子孙之基有玷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7709, '午', '北方之运西方地，自是清闲胜显名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7710, '午', '十载夫妻情未满，良人早已入黄泉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7711, '午', '豺狼当道，举步纠缠。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7712, '午', '有名无实，乖运亦乖。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7713, '午', '天喜相照，一胎生二子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7714, '午', '扫开万里云，现出一天星。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7715, '午', '披麻相照，忧及椿庭。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7716, '午', '落花满空山，秋风解佩环。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7717, '午', '命有六子，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7718, '午', '惟爱风流是意多，花开酌酒或吟哦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7719, '午', '夫荣子旺常增辉。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7720, '午', '姊妹二人，融融洽洽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7721, '午', '当宴鹰场。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7722, '午', '蓉菊满园虽雅丽，松筠独翠晚来香。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7723, '午', '财源交接中年发，家业兴隆气象新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7724, '午', '陶令喜栽彭泽菊，严于思钓富春鱼。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7725, '午', '恍惚每多，意外之忧。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7726, '午', '六九之年晚运通，贵人提得兴隆。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7727, '午', '祖业更添新，门庭反胜旧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7728, '午', '此刻爱妻多金命，土命并火衣禄长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7729, '午', '一朵梨花白玉开，丧门照命有忧来。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7730, '午', '一胎二胞，一男一女。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7731, '午', '老椿先作游仙客，泣血沾衣泪涟涟。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7732, '午', '忽梦钦白，忧难消除。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7733, '午', '老年当壮，优于仕途。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7734, '午', '姊妹二人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7735, '午', '重山之外问黄金，始历艰辛后有成。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7736, '午', '未得成人，其人亡矣。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7737, '午', '镜破钗分，花残月缺。', '[77]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7738, '午', '正是丰年人快乐，不妨红日系绳长。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7739, '午', '三八年来运已通，成家立业自兴隆。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7740, '午', '离家之人真不孝，犹有爱妾心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7741, '午', '火年父命先终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7742, '午', '椿树有年，狂风吹折。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7743, '午', '兄弟五人，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7744, '午', '才逢坦道又遇雨，正好行舟又遇风。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7745, '午', '门外坦途，无往不利。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7746, '午', '羡君有酒沉沉醉，喜君无钱不觉贫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7747, '午', '分织女工无他了，内室安闲纳福多。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7748, '午', '椿树吹折，三年泣血。', '[19]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7749, '午', '戊午之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7750, '午', '昏昏黑黑，鬼魅现形。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7751, '午', '履虎之尾，不见其凶。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7752, '午', '风木有余恨，难免泣血悲。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7753, '午', '生子之年。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7754, '午', '童年甫一句，父死泪沾襟。', '[10]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7755, '午', '数该生子。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7756, '午', '嫩柳抽丝，晚烟浓露。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7757, '午', '雪里高山尽白头，树中仙果几千秋。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7758, '午', '登科及第。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7759, '午', '房考之年。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7760, '午', '良人丧后，子结二枝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7761, '午', '翁姑俱丧，妇之不幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7762, '午', '一阳初动候黄钟，得合天心困始通。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7763, '午', '断弦之忧，此年难免。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7764, '午', '只身一人，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7765, '午', '借问一生身外事，遇猪之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7766, '午', '仕途变幻，官讼交加。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7767, '午', '兴兵结怨，吴越交争。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7768, '午', '五彩绳牵月老话，京兆画眉许张郎。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7769, '午', '八岁丧父方合。', '[8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7770, '午', '百岁欠一春，含笑入黄泉。', '[99]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7771, '午', '梅萼枝枝秀，春信到画堂。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7772, '午', '猛虎出松林，吼啸风自生。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7773, '午', '多有助夫之德，又招富贵贤郎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7774, '午', '马头带剑，掌握兵权。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7775, '午', '老椿吹折，三年泣血。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7776, '午', '钦命典试。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7777, '午', '篱竹独舒元亮兴，江忽起季鹰情。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7778, '午', '到处交情容易投，清风车马贵人留。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7779, '午', '雨地有人耕野绿，月明无犬吠花阴。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7780, '午', '元享利贞，室人之庚。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7781, '午', '喜遇青龙现，安然不须忧。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7782, '午', '命照武英，弓马入泮。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7783, '午', '三月艳阳天，游人乐少年。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7784, '午', '含哺虽有喜，进退且待时。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7785, '午', '不惑之时孝服临，堂上栋梁倾。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7786, '午', '勤俭为生理，兴家发达时。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7787, '午', '事不见机，运到阻滞。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7788, '午', '秋云登桂籍，青衣换紫袍。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7789, '午', '兄弟六人方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7790, '午', '不得其志，渊明东归。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7791, '午', '三徒金年收，四徒水年收。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7792, '午', '道路荆棘塞，莫问津。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7793, '午', '事事只宜坚守牢，妾行取用反为凶。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7794, '午', '灼灼桃天，日暖花娇。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7795, '午', '日暖风和，芳草含意。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7796, '午', '兄弟六人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7797, '午', '徒弟三人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7798, '午', '数有偏枯，二子不肖。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7799, '午', '钦命典试。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7800, '午', '和气叶祯祥，闺中庆有常。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7801, '午', '花落有意，流水无情。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7802, '午', '哀哀泣血，正有刑伤。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7803, '午', '易田畴树艺，五谷风快乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7804, '午', '手艺不分贵，只求发达兴隆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7805, '午', '胸中藏列锦云章，身居国学姓名扬。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7806, '午', '鹊噪南楼，频频报喜。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7807, '午', '蛟龙入海，风云际会。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7808, '午', '春光开遍，万绿千红。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7809, '午', '文昌照命，定入泮水生香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7810, '午', '产亲数已尽，难在画堂留。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7811, '午', '清风明月里，事得福自多。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7812, '午', '暮景安闲，天赐洪麻。', '[87, 88]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7813, '午', '南国风烈，吹折椿枝。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7814, '午', '出将入相，比美宫中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7815, '午', '风雨初收，中天日现。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7816, '午', '官至游府，以乐终身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7817, '午', '生子之年。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7818, '午', '气运方顺，将来发达。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7819, '午', '万顷波涛千点乱，一天星斗夏秋间。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7820, '午', '一生衣禄足，运到花丛锦上添。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7821, '午', '兄弟四人，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7822, '午', '红莲荷绿水，摇动引鱼龙。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7823, '午', '天地常存，年华久合。', '[97, 98]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7824, '午', '长安虽乐，宜归故梓。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7825, '午', '芙蓉在秋江，不耐风雨霜。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7826, '午', '官至游府，以乐终身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7827, '午', '不假余力，根基自植。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7828, '午', '处处花开我亲栽，开时又遇狂风吹。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7829, '午', '姻缘还匹配，鸾凤自相交。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7830, '午', '桃红柳绿，人多乐意。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7831, '午', '贞静幽闲德，女阁内助人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7832, '午', '先甲三日吉，后甲三日昌。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7833, '午', '福星照耀，官职高升。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7834, '午', '风吹绿柳最难持，三思而行免祸危。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7835, '午', '阴气盘桓步履错，得交和气日朝阳。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7836, '午', '不用五经应试，只凭三箭显名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7837, '午', '细雨活新花，闺门乐意浓。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7838, '午', '武试中式，得占高魁。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7839, '午', '四九之年已亨通，图谋顺利事隆隆。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7840, '午', '神人之乐日悠悠。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7841, '午', '此刻财运，渐佳安泰。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7842, '午', '融融日色丽，抵掌庆有年。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7843, '午', '幽闲妇女正清奇，旺夫益子发大家。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7844, '午', '借问平生何处事，邀游京国在他乡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7845, '午', '福星当益壮，蛟龙已出渊。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7846, '午', '子有双枝，玉人复亡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7847, '午', '尘掩菱花，月中多滞。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7848, '午', '红日东升，阴气消除。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7849, '午', '天赐南山寿，人享福平安。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7850, '午', '五彩绳牵月老话，京兆画眉许张郎。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7851, '午', '已卯之年，乡科及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7852, '午', '闺中弱女都生悉，可怜花被雨中羞。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7853, '午', '水流花落，惆怅堪悲。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7854, '午', '银带出身金带止，青山盼望白云倾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7855, '午', '终身弥陀苦修行，苍天佑我消得愁。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7856, '午', '父命终于上年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7857, '午', '乡科及第。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7858, '午', '久思洞房快乐。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7859, '午', '少年安乐得庇荫。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7860, '午', '梅花开施早，好不恨春迟。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7861, '午', '鱼游临渊，踊跃自如。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7862, '午', '轻舟遇顺风，欣笑急流中。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7863, '午', '兄弟七人，数有一贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7864, '午', '椿枝风吹折，难免泣血悲。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7865, '午', '春光暖日，复饶物色。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7866, '午', '水尽山穷命不坚，渺渺茫茫别有天。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7867, '午', '寻师访友，忽遇知音。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7868, '午', '虎怒噬人，见之有悲。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7869, '午', '临风回首，揽三叹。', '[93, 94]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7870, '午', '得人轻借力，便是运通时。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7871, '午', '脱却尘埃，悠然物外。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7872, '午', '点灯相照，往来大道。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7873, '午', '姊妹五人方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7874, '午', '可恨姻缘不到头，一旬之外断弦扰。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7875, '午', '初任都司之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7876, '午', '赖有吉神位，闺中福祯祥。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7877, '午', '所谋有韬略，暴虎凭河辈。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7878, '午', '红叶喜相引，气和日暖时。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7879, '午', '大限凶星当压死。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7880, '午', '日暖风和丽，禅室添好景。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7881, '午', '陆路高低弗点灯，月明如昼亦难行。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7882, '午', '命有贵子，前生注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7883, '午', '满同名花，映人耳目。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7884, '午', '虑深方有喜，云散月光辉。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7885, '午', '春光暖日，复饶物色。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7886, '午', '轻风能便借，功业见掀天。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7887, '午', '人生七十古来稀，今日少三是归期。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7888, '午', '时逢暖景，人物光华。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7889, '午', '锦衣之职，数有注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7890, '午', '宜室宜家，幽人贞吉。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7891, '午', '六九年运谋，财禄两相宜。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7892, '午', '丧门相照，优及严亲。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7893, '午', '五彩绳牵月老话，京兆画眉许张郎。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7894, '午', '姊妹五人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7895, '午', '心高性刚直，甘苦皆经历。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7896, '午', '官至总府，以乐终身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7897, '午', '财禄自丰。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7898, '午', '安然顺利。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7899, '午', '钦命典试。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7900, '午', '送老二子，花开别树。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7901, '午', '吉凶相逐，慎之慎之。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7902, '午', '徒弟四人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7903, '午', '恩星相照，任升司徒。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7904, '午', '波平风静，稳度无忧。', '[80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7905, '午', '姊妹十人，数有前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7906, '午', '妻室悬梁，数中注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7907, '午', '浅水蛟龙养头角，直待风云上九霄。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7908, '午', '子结三四枝，玉人弃世去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7909, '午', '大限已停命即倾，六亲有泪洒沾襟。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7910, '午', '相照有丧门，衣裳白一番。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7911, '午', '怀抱安舒，际遇相安。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7912, '午', '若问好姻缘，全在吴与越。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7913, '午', '不幸椿枝折，三年泣血悲。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7914, '午', '朝霞映日，画堂佳气。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7915, '午', '兄弟七人方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7916, '午', '轻抛人爵修天爵，远近青山伴白云。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7917, '午', '春雷已有声，潜光从此振。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7918, '午', '妻娶五度，方能白首。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7919, '午', '万卷诗书少读时，登云步月沐皇恩。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7920, '午', '未得成人，主丧严亲。', '[15]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7921, '午', '运筹帷，妙机惟精。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7922, '午', '李杜文章无意得，萧曹案渎足荣身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7923, '午', '椿枝风吹折，泣血三年悲。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7924, '午', '老蚌生珠之喜，坐井观天之吉。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7925, '午', '房考之年。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7926, '午', '名登国学地，身在碧云霄。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7927, '午', '此刻生人，身材消瘦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7928, '午', '运到自从坤地发，百发各向午时开。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7929, '午', '椿枝已折，三年泣血。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7930, '午', '琢磨之玉，价重连城。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7931, '午', '父命三妻，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7932, '午', '鹊噪鸦鸣，吉凶自有。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7933, '午', '得授金腰，举家沾福。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7934, '午', '族子送老，数中定然。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7935, '午', '伶俐僧言，庸常之辈。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7936, '午', '坐马未得鞍，徘徊不敢前。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7937, '午', '命照武曲，弓马入泮。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7938, '午', '借问花开结子否，奈何吐气柳梢春。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7939, '午', '琴瑟和鸣，良人先逝。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7940, '午', '命犯凶星，妻死烟炮中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7941, '午', '精习杜康艺，立意醉刘伶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7942, '午', '碧草生春色，黄鹏报好音。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7943, '午', '玉人亡后，子结一枝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7944, '午', '牧马之贞，流年吉庆。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7945, '午', '权星照命，官升司马。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7946, '午', '椿树有年，被风吹折。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7947, '午', '兄妹二人，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7948, '午', '恺梯存心，端方律己。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7949, '午', '术精何难至，富以身荣光。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7950, '午', '月中行现斗，光暗各分明。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7951, '午', '勋勋鼎彝，封造荣身。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7952, '午', '印中偏财，必作副室。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7953, '午', '偏逢堪谢箭，熟读六韬书。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7954, '午', '喜入门庭，吉利相从。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7955, '午', '一浪未平，一波又起。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7956, '午', '黎民一点四方志，禄位高升便超群。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7957, '午', '睿智之人，事不可感。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7958, '午', '官拜总兵，至侯一等。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7959, '午', '勤俭守钱，毫厘不失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7960, '午', '人死桃花树下。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7961, '午', '琴瑟和鸣，一弦忽断。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7962, '午', '驾鹤乘云去，飘然竟不回。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7963, '午', '姊妹十一人，数有前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7964, '午', '利名当香，须以待之。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7965, '午', '空门无室碍，福德自相随。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7966, '午', '双飞鸿雁，出入门间。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7967, '午', '每恨庄子叹，于今我亦同。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7968, '午', '房考之年。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7969, '午', '不得其志，渊明东归。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7970, '午', '椿树风吹折，三年泣血悲。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7971, '午', '逢灾不成，遇难有救。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7972, '午', '时来君展翅，人遂平生愿。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7973, '午', '兄弟四人方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7974, '午', '运至时来，无往不利。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7975, '午', '小心奸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7976, '午', '眉头开畅，事得施为。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7977, '午', '消无妾灾，纳祯祥福。', '[65]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7978, '午', '勿嫌春未至，幸见早桃开。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7979, '午', '姻缘非一姓，佳人重又重。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7980, '午', '乡科得意，必中科举。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7981, '午', '兄弟九人方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7982, '午', '三九之年运正好，贵人指引得相宜。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7983, '午', '数有五子，四子送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7984, '午', '安闲岁月，无忧无虑乐春风。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7985, '午', '五福寿为先，明媚色更新。', '[99100]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7986, '午', '母赴瑶池，三年泣血。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7987, '午', '残花幸得逢春早，点缀桃花面目中。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7988, '午', '吉星应相照，唤醒三春梦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7989, '午', '德明心性格，定入凤凰池。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7990, '午', '箱囊金堆积，仓库有余粮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7991, '午', '日月照眉瑞，光明在目前。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7992, '午', '徒弟一人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7993, '午', '数载窗寒名不成，不如市尘利盈盈。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7994, '午', '兄弟五人方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7995, '午', '福星相照，及时图利。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7996, '午', '为人天资明，敏气质刚柔。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7997, '午', '家肥屋润般般遂，旺夫益子事事昌。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7998, '午', '物艺精通，生快偿年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (7999, '午', '徒弟四人，得以送老。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8000, '午', '姊妹十二人，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8001, '未', '欲步青云梯，登陆财富期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8002, '未', '白云终是散，明月落谁家。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8003, '未', '闺中顺利乐忘忧，春日凝妆上翠楼。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8004, '未', '恬恃有思沾福泽，数定父先母后归。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8005, '未', '珠在掌中，自然稳当。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8006, '未', '灯花新喜，吉事频来。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8007, '未', '大车既载，无往不利。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8008, '未', '一家叶吉，利涉大川。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8009, '未', '怀过人之志，慕众人之能。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8010, '未', '鱼初得水，踊跃前行。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8011, '未', '燕山之子，数口呸爽而失三。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8012, '未', '兄弟三人，却被功名利冲散。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8013, '未', '兄弟五人，今存其二。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8014, '未', '许群游泮春风暖，丹桂须知自厚培。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8015, '未', '鱼跃于渊，游然无阻。', '[42, 43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8016, '未', '行藏豹变，知虑过人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8017, '未', '兄弟三人，二人过亡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8018, '未', '双亲俱有寿，异日父先母后归。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8019, '未', '美在其中，畅于四肢。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8020, '未', '福自随人，无往不亨通。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8021, '未', '谋事发达，定期改换门庭。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8022, '未', '早运淹没中运通，成家立业福兴隆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8023, '未', '白玉楼高但赋美。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8024, '未', '借问一生身外事，遇龙之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8025, '未', '三旬之外，得之始实。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8026, '未', '癸丑之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8027, '未', '性秉仁慈无鄙吝，气存各厚少骄矜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8028, '未', '父子俱出家，先天注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8029, '未', '无祸变无灾，居安福自来。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8030, '未', '此刻生人，注定是婢命方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8031, '未', '赖有吉神扶，唤醒三春梦。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8032, '未', '红鸾相照。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8033, '未', '不入红尘波，惟耽终日静中居。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8034, '未', '不幸萱花萎，椿庭正茂长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8035, '未', '一人进一人退，吉里藏凶须仔细。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8036, '未', '功名早成，淹况中运稍遂志。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8037, '未', '八八卦中先算定，南柯一梦报君知。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8038, '未', '形影相吊，晚景堪怜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8039, '未', '勤克勤俭为生理，自有兴家发达时。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8040, '未', '财来运发男儿志，裕后光前自有为。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8041, '未', '数中四子得送老。二子高飞鸣上林。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8042, '未', '兄弟四人，一人失群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8043, '未', '画虎于墙上，有惊无实害。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8044, '未', '三雁高飞，何期一只归罗网。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8045, '未', '持家有则，可夺夫权。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8046, '未', '轻舟波浪稳，可知用力难。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8047, '未', '一字切忌日马，可允可求。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8048, '未', '不为台阁三台贵，百亩安闲乐自知。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8049, '未', '乡科及第。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8050, '未', '寒窗苦志发，终有达贵时。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8051, '未', '同飞三雁，一只先失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8052, '未', '头胎水命儿难受，再生木命始为真。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8053, '未', '操存舍亡，求之在我。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8054, '未', '不是君家粟，江头风逆渡难开。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8055, '未', '满眼春花发，一天秋月明。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8056, '未', '若得杏林生意好，须将苦苦问功名。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8057, '未', '画堂严君与慈帷，异日忧悲母在先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8058, '未', '桂有秋香枝叶秀，物先发出牡丹芽。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8059, '未', '但有秋风便，扁舟渡万山。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8060, '未', '天道循环，好运方转。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8061, '未', '兄弟三人，数当尽贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8062, '未', '出入交游皆显达，行藏守礼更施仁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8063, '未', '兄弟四人，数注俱贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8064, '未', '慈先归西，严当在后。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8065, '未', '不阴不阳待贵贱，出宫入宫身贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8066, '未', '命主有刑，择配金石。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8067, '未', '出入通大道，从此保初终。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8068, '未', '有子当贵，贵者是次。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8069, '未', '安心乐田畴，拮据不须忧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8070, '未', '此刻生人，注定是奴命方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8071, '未', '未能光大终幽暗，日落西山又反东。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8072, '未', '兄弟五人，二人不全。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8073, '未', '天高地厚，莫可穷愁。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8074, '未', '雨含藏笑口，柳烟锁愁眉。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8075, '未', '新竹成林高旧竹，奇花暮发胜先枝。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8076, '未', '宁观鲁庙三口，安绪曹娥八字诗。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8077, '未', '欲左欲右，心安意稳。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8078, '未', '虚花儿女竟来多，限上焉能一尽忘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8079, '未', '天边雁足传书至，一树梅花喜气新。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8080, '未', '五福为寿先，平安乐天年。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8081, '未', '石旁有皮须防破。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8082, '未', '兄弟三人，中断离群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8083, '未', '池塘水月新如钩，梦断邯郸眉黛愁。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8084, '未', '兄弟四人，我在空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8085, '未', '福寿康宁，精神倍爽。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8086, '未', '风静月华明，高阁奏笛声。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8087, '未', '椿庭有寿，狂风吹折。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8088, '未', '此时得成功，贵人指引喜匆匆。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8089, '未', '金殿传鲈，人生大幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8090, '未', '加官进禄，又喜乔迁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8091, '未', '若娶偏房，发生一子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8092, '未', '鸟鹊逢林，未可即安。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8093, '未', '壬辰之年，进士及第。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8094, '未', '乡科题名。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8095, '未', '江关昨夜报潮生，侵晓楼头水正平。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8096, '未', '问名问利，名不如利。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8097, '未', '桃李春风花不结，三秋丹桂一枝香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8098, '未', '佳人命运乘，配得郎不才。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8099, '未', '土年使要，离乡背井。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8100, '未', '此刻生人，贩夫走卒合卦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8101, '未', '群雁高飞，三只先投入罗网。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8102, '未', '父命属金方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8103, '未', '中运时来自坦夷，慨然春色满皇洲。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8104, '未', '知君老至精神壮，运求晚运事辉煌。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8105, '未', '福寿康宁，明烛不怕风和雨。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8106, '未', '山高水深，纵有舟车不易行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8107, '未', '眉头开展，事得施张。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8108, '未', '儿女多慨说，运上能念志。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8109, '未', '五行票得中和气，烈烈轰轰山群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8110, '未', '称彼凹，介以眉寿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8111, '未', '蜻蜓莫入蜘蛛网，萤火休教到上林。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8112, '未', '暗晦植侵，流年不宁。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8113, '未', '凡事皆可谋，善终又善始。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8114, '未', '兄弟三人，一在空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8115, '未', '人事不齐，只多怅。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8116, '未', '啾啾唧唧似黄昏，四壁虫声织暮空。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8117, '未', '人物生清秀，机关度量深。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8118, '未', '从前运限生狼，今岁春回淑气催。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8119, '未', '读书应有分，难以步青云。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8120, '未', '因于黎，三刑其妻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8121, '未', '数该生子。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8122, '未', '无事双亲，拮据生养。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8123, '未', '椿庭虽有寿，今朝一旦亡。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8124, '未', '六阴阴极水成冰，造物人明未有成。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8125, '未', '花因雨坊边根瘦，柳为风摇带絮飞。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8126, '未', '双亲共乐享作年，异日哀哉母为先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8127, '未', '一掷千金便是胆，家徒四壁不知贫。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8128, '未', '危桥初尽休回首，且看桃园路可通。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8129, '未', '昔日偏今日，嫡庶又无分。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8130, '未', '兄弟六人，四人先去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8131, '未', '太岁当头，不测自来。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8132, '未', '家计贫且苦，好似雪中花。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8133, '未', '壬戌之年，名登黄甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8134, '未', '启后光前非谷子，少年容易占高科。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8135, '未', '萱堂已折，幼年不幸。', '[3]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8136, '未', '早岁虽无庄子叹，中年难免鼓盆歌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8137, '未', '要历中运至，有子可傍依。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8138, '未', '颖悟超群，襟怀洒落。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8139, '未', '命有伤官，作人继室。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8140, '未', '水火之年，入泮方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8141, '未', '椿萱俱已谢，母先赴瑶池。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8142, '未', '序案中题姓字，伴林池内有名香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8143, '未', '异路有功名，遇猴之年方进步。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8144, '未', '人事从容，老来清吉。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8145, '未', '安乐清福，老来足欲。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8146, '未', '性中杰物人中杰，出入超群志量深。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8147, '未', '云收雨过，日月光明。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8148, '未', '锦堂开寿域，儿孙绕膝福无穷。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8149, '未', '顺则千金不吝，逆则一芥如珠。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8150, '未', '子如化龙，人之报喜。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8151, '未', '乍暖梅花无气力，淡时花影未全舒。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8152, '未', '椿枝先折，萱草后凋。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8153, '未', '戊辰之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8154, '未', '灯花报喜，吉事频来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8155, '未', '子有出继，先天注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8156, '未', '他时若肯输钱粟，异路功名可称怀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8157, '未', '方觉岩前飞快马，干层浪里驾孤舟。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8158, '未', '兄弟二人，一入空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8159, '未', '慌慌忙忙，不但人嗔有鬼喷。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8160, '未', '疾风知劲草，岁寒识松柏。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8161, '未', '桃花初吐秀，朝露衬红妆。', '[7]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8162, '未', '一胸热血，偏招是非。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8163, '未', '出水芙蓉，点缀秋江。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8164, '未', '生子之年。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8165, '未', '兄弟三人，一人不存。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8166, '未', '椿萱卜算遐龄永，先赴瑶池是母亲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8167, '未', '非吏非儒，猛浪岁月。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8168, '未', '鸳鸯重整。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8169, '未', '独雁南飞各宿食，玉人两度是前缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8170, '未', '桂子初虚秋后实，原来有数定先天。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8171, '未', '兄弟六人，先失其一。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8172, '未', '知君多合高人意，堪叹当招小辈凌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8173, '未', '早年诗文入泮宫，岁寒然后习凋松。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8174, '未', '兄弟五人，一在空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8175, '未', '叹宫昭君怨，胡为我亦同。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8176, '未', '喜气足喜，流年之庆。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8177, '未', '水年娶妻，木年纳宠。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8178, '未', '椿萱沾宠渥，父先入幽冥。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8179, '未', '丧门相照，哭泣之哀。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8180, '未', '温良恭俭让，行藏似古人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8181, '未', '兄弟四人，一在空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8182, '未', '坤人内助得殷勤，一生认禄不求人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8183, '未', '兄弟六人，先失其二。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8184, '未', '一胞二女，两度红鸾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8185, '未', '兄弟四人，二人空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8186, '未', '风火性情，其心最急。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8187, '未', '结发未从谐老耗，还言锦怅续鸳鸯。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8188, '未', '梅花迥出群，清香扑鼻香。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8189, '未', '丁丑之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8190, '未', '四宫见李日，收成凤凰郎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8191, '未', '利禄胜当年。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8192, '未', '兄弟六人，先失其半。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8193, '未', '芙蓉生在秋江上，不与群芳斗色香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8194, '未', '兄弟三人，只求其一。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8195, '未', '不从文武科中出，命有总督一品官。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8196, '未', '兄弟六人，“一入空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8197, '未', '春色园林茂，秋天宇宙清。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8198, '未', '祸患不可测，不但人嗔且有鬼。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8199, '未', '肉之中情少倚，良人重配得齐眉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8200, '未', '操持有大节，劈烈丈夫心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8201, '未', '早运艰辛中运好，成家立业福相随。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8202, '未', '兄弟六人，只得其五。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8203, '未', '此时称孤子，三年泣血悲。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8204, '未', '数该生子。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8205, '未', '碧碧澄澄，苍苔露冷。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8206, '未', '兄弟九人，数当尽贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8207, '未', '红莲初出水，春草无冰霜。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8208, '未', '四女乘龙去，得子宜结迟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8209, '未', '财旺生宫在数中，夫荣子秀福无穷。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8210, '未', '牡丹却是人间瑞，花在园林色更新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8211, '未', '凉风初至楚王台，烦热消除爽气来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8212, '未', '少壮而至老，终无阻逆虞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8213, '未', '双亲同白发，数定父先母后归。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8214, '未', '虽然女命宜科第，插玉空金到白头。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8215, '未', '因来宜择避，松树耐岁寒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8216, '未', '纯阴无自，数止于此。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8217, '未', '不幸玉人惟欠寿，先吾四十丧黄泉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8218, '未', '继母嫡母，生我是母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8219, '未', '兄弟七人，理存其五。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8220, '未', '姻缘早配名门子，桂子得芳朵朵鲜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8221, '未', '土年父先终方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8222, '未', '春残莫怨无颜色，喜有葵花映日红。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8223, '未', '兄弟七人，只存其四。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8224, '未', '雁君七人，一只先飞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8225, '未', '滩头无船壮志悲，若无良马何保侯。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8226, '未', '阴极阳盛，数止于此。', '[84]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8227, '未', '兄弟三人，我在空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8228, '未', '辛苦拮据积，后福而悠亡。', '[74, 75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8229, '未', '九曲明珠穿不得，回头却问采桑郎。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8230, '未', '俄然内卷浮云去，禅房日色下光辉。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8231, '未', '杜鹃啼血泪，月上已三更。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8232, '未', '兄弟七人，四人不存。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8233, '未', '一年又一年，人事参差不可言。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8234, '未', '帘前喜鹊噪，报喜又报晴。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8235, '未', '今朝欲托前生事，觅得岭续后枝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8236, '未', '兄弟九人，我在空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8237, '未', '本是同林鸟，不幸雉者早先飞。', '[29]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8238, '未', '二月桃花红灼灼，三春杨柳绿绵绵。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8239, '未', '如龙如虎双双子，送终实许两枝荣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8240, '未', '喜气洋溢，十分春色可人怀。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8241, '未', '申运遇艰，午潮有待。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8242, '未', '送终一子，花开别树。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8243, '未', '兄弟六人，我在空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8244, '未', '寿算滔滔八卦止，怕有渔郎来问津。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8245, '未', '芙蓉花开，秋江冷淡。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8246, '未', '子产河东玉凤器，他日飞翔有偏贤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8247, '未', '牡丹虽富贵，梅菊不同芳。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8248, '未', '送老惟三子，别树一枝红。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8249, '未', '父先故于火年，母生年属木方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8250, '未', '不必问行藏，进五而退十。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8251, '未', '两朵名花开玉树。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8252, '未', '兄弟七人，我在空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8253, '未', '花外莺声巧，春风草色新。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8254, '未', '淹淹晦滞，流年不宁。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8255, '未', '财帛破耗，流年多滞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8256, '未', '安于淡薄，识父母心。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8257, '未', '当有三母之称。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8258, '未', '虎凶出于，征夫不能前。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8259, '未', '子秀夫荣谁可及，荣花直到七旬春。', '[70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8260, '未', '夫妻同庚得齐眉，鸳鸯何年晚分飞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8261, '未', '暗中摸索处，隙路有光阴。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8262, '未', '破家一床蝴蝶梦，惊散鸳鸯不在眠。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8263, '未', '数该生子。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8264, '未', '上苑奇花呈富贵，庭前绿竹耀祥光。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8265, '未', '南极祥光照我身，此年幸有花甲临。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8266, '未', '南北江山争秀丽，风前花柳正繁华。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8267, '未', '送老四子，三枝挺秀。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8268, '未', '子许成双是良材，量有埋蛇救蚁功。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8269, '未', '利子益夫，助家之际。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8270, '未', '无子似有子，副室之儿送我终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8271, '未', '四德兼全，巨家主权。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8272, '未', '水年火年俱得子，无奈土命年先去。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8273, '未', '少享庇阴年，晚启后人业。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8274, '未', '送老三子，两朵名花开玉树。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8275, '未', '克勤克俭能内助，一生衣禄自安然。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8276, '未', '俄然风起卷云至，中天日色尽光辉。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8277, '未', '伯道无儿天道绝，幸有犹子唱骊歌。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8278, '未', '旧恨新悉且莫问，须知从经复安然。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8279, '未', '父去永不归，人子沾泪衣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8280, '未', '劳碌心闲事不闲，三分火性在心头。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8281, '未', '性赋刚直，无偏无私。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8282, '未', '风吹云散月光明，枯木生花满户庭。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8283, '未', '骨肉之中情不足，六亲恩谊冷如冰。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8284, '未', '不进孔孟门，乃读萧曹律。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8285, '未', '未嫁姑先亡，妇之大不幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8286, '未', '青年跌破莲花镜，惊走鸳鸯再会难。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8287, '未', '岩畔青桦树，根磐石上生。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8288, '未', '太阳具役，形骸俱来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8289, '未', '运转遇解凶成吉，烦恼无根着意消。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8290, '未', '玉人之寿，短我五年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8291, '未', '慈航普济，早证菩提。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8292, '未', '晚年进福，子振家声。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8293, '未', '财帛破耗，流年不利。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8294, '未', '前顾后盼，挣挫艰难。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8295, '未', '机会不来，大图小就。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8296, '未', '椿枝已折，泣血三年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8297, '未', '椿树已先折，萱花在后萎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8298, '未', '雁门品字方成阵，终始君臣各一天。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8299, '未', '丧门相照我一家，入到堂前栋梁倾。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8300, '未', '金年克妻，火年再娶方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8301, '未', '从前无事乐君芳，喜气重重隆吉祥。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8302, '未', '丙辰之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8303, '未', '和风日暖时时乐，进喜添财事事新。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8304, '未', '正当荆棘路，扶杖又崎岖。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8305, '未', '花得雨滋偏馥郁，弄璋还应梦中诗。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8306, '未', '翁姑俱丧，妇之不幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8307, '未', '漫漫彻夜风又雨，吹落梅花白雪飞。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8308, '未', '妻未归门而之，缘之浅也。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8309, '未', '丧门相照，优萱亲服。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8310, '未', '东边沉了西边挽，引动人间是与非。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8311, '未', '门庭闹乱，蛇休雷霆。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8312, '未', '诸姑辞伯姊，一双红烛洞房辉。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8313, '未', '老椿雪压已多年，萱花堂上福绵绵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8314, '未', '堪叹孔缘乃浮浅，数中纵有也分离。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8315, '未', '却芜循大道，拨开云雾见青天。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8316, '未', '不作生涯不耕田，一生常在贵人边。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8317, '未', '一重欢喜一重愁，峻岭扳枝着力风。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8318, '未', '莫说少年荣枯事，梅花雪里见精神。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8319, '未', '性秉仁慈无鄙吝，气存和厚少骄矜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8320, '未', '一字切忌日兔，遇不得。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8321, '未', '诸吉皆在，门庭喜气。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8322, '未', '孤雁成行当，有将于子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8323, '未', '福照星耀，天喜临门。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8324, '未', '欲谋图进用，枉费决无功。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8325, '未', '声名孚宇宙，皇都得意回。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8326, '未', '荆藜根，流年不宁。', '[67]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8327, '未', '一重欢喜一重愁，高下崎岖着力游。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8328, '未', '财帛破耗，流年不利。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8329, '未', '守旧安居，虽危无答。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8330, '未', '玉人之寿，短吾十年。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8331, '未', '狂风吹散叶，飘动不安宁。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8332, '未', '财帛破耗，流年不利。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8333, '未', '一轮月明，花开雨晴。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8334, '未', '俾知皇阁三公贵，今人巧作古人形。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8335, '未', '一种痴情容易愁，清风车马任追求。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8336, '未', '自有高人轻借力，两重门户得光辉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8337, '未', '试看园中花再果，晚年丹桂一枝香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8338, '未', '数中偏枯刑伤命，妻宜迟娶子亦迟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8339, '未', '迢迢前路未通津，革故从新始见成。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8340, '未', '正妻属子，副妻属已。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8341, '未', '结发夫妻防有克，还须燕尔得相宜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8342, '未', '贵人相扶便可期，庭枯木风来相仪。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8343, '未', '平行安乐地，更有福相随。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8344, '未', '知音提去江东。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8345, '未', '财帛破耗，也是定数。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8346, '未', '一双玉手千人枕，半点朱唇万客尝。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8347, '未', '不用诗书思禄位，只图农业乐终身。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8348, '未', '读罢三坟与五典，儿郎及第早登科。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8349, '未', '人生绪有何用，不若刘郎沉醉乡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8350, '未', '有人来问迷津路，水在吴江月在空。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8351, '未', '入地欲知谁是竹，一尘不染出入踪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8352, '未', '任君富贵荣华处，宁为净口乐菩提。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8353, '未', '花开五色，挺秀园中。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8354, '未', '义里成仇，恩中结怨。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8355, '未', '兄弟七人，数中尽贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8356, '未', '母赴瑶池，三年泣血。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8357, '未', '要知命里有刑杀，妻当晚娶子宜迟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8358, '未', '振祖父之基业，启后生之事业。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8359, '未', '老来致仕归山去，一片忠心逐水流。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8360, '未', '破去财帛，命主耗星。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8361, '未', '不进须当退，方无阻赛忧。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8362, '未', '忠厚立心，天赋其性。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8363, '未', '兄弟九人，数有七贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8364, '未', '日出被去，时下暗光辉。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8365, '未', '明明精雪厚，三尺冻云飞。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8366, '未', '生子之年。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8367, '未', '兄弟五人，我入空门。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8368, '未', '路途皆崎岖，撑过是坦夷。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8369, '未', '夫配金水之年，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8370, '未', '名登金榜。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8371, '未', '谢安选胜，东山日歌酒。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8372, '未', '水年木年生子，无损方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8373, '未', '上下无不和，门庭喜庆多。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8374, '未', '且宜先退让，方可免灾厄。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8375, '未', '获得金鳞垂钓丝，江头月落醉眠时。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8376, '未', '名进贤关，弓马入泮。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8377, '未', '红鸾相配，见而免灾。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8378, '未', '上下皆仇怨，日暮偏又来。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8379, '未', '送老无子，以婿为儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8380, '未', '衰哀泣泣，正有刑伤。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8381, '未', '蟠桃三结子，丹桂一枝香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8382, '未', '官至刑部，锦衣荣贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8383, '未', '荣谋顺遂，动止又安详。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8384, '未', '日现中天光，光明普照。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8385, '未', '财帛破散，皆因耗人。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8386, '未', '春暖桃李，色艳光华。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8387, '未', '民歌陶舞乐尧天。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8388, '未', '房考之年。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8389, '未', '武曲照命，三场捷报。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8390, '未', '菊因秋老边根瘦，桃为风飘带雪飞。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8391, '未', '荫袭国公职，祖宗植根深。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8392, '未', '扫尽长空，放出光现。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8393, '未', '老树叶落，归于根下。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8394, '未', '癸丑之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8395, '未', '百福饼臻，喜气盈门。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8396, '未', '海棠花香，雨泪胭脂。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8397, '未', '双双紫燕，高飞云外。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8398, '未', '五耗人命，多耗钱财。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8399, '未', '正宣发奋同前，好个声名闻誉。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8400, '未', '耳顺之年晚运宜，桑榆暮景福相随。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8401, '未', '琵琶江上曲，回首正佳音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8402, '未', '以监出仕，任至有司。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8403, '未', '厚重自持，德高心下。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8404, '未', '阳春复来先报喜，雪余欢适赏红梅。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8405, '未', '时值亢阳，俄然雨露爽人怀。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8406, '未', '红鸾相照，喜气频来。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8407, '未', '萤虽光大终幽暗，月落西沉远照中。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8408, '未', '以监而选州官，高擢荣升。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8409, '未', '崇高富贵，五福咸备。', '[60, 61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8410, '未', '乙未之年，名登黄甲。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8411, '未', '文章字字珠玉，必然金榜题名。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8412, '未', '无妄之空而失之，行人之得邑人忧。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8413, '未', '母先辞世，抱恨终天。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8414, '未', '人生七十古来稀，却当六六是归期。', '[66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8415, '未', '山深路远，竟得樵人来指引。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8416, '未', '兄弟十人，数有八贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8417, '未', '少年丧父，子大不幸。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8418, '未', '举步多荆棘，见凶须要防。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8419, '未', '一生无大虑，平安享福保始终。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8420, '未', '三十年前不得闲，后运来获福绵绵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8421, '未', '大耗小耗，耗我财帛。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8422, '未', '大风拔树，根本难留。', '[10]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8423, '未', '武曲照命，三场捷报。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8424, '未', '浮生如云，相似往事梦一场。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8425, '未', '赖有吉神照，终属坦夷不为凶。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8426, '未', '今朝一旦许归程，满眼新知泪几零。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8427, '未', '灯花结蕊，喜事频来。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8428, '未', '南山杜鹃啼，句句频言客不归。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8429, '未', '课雨问晴，中天顺人。', '[83, 84]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8430, '未', '玉人不齐眉，先去十五年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8431, '未', '夜雨正逢春，宇宙生和气。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8432, '未', '寿穷数尽，渺渺茫茫。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8433, '未', '良田种松竹，节操自盘根。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8434, '未', '数至于宫，弄璋之喜。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8435, '未', '运至四旬，处称其心。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8436, '未', '兄弟十人，数有七贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8437, '未', '风恬浪自静，色秀不须凝。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8438, '未', '美色之能，岂但齐家。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8439, '未', '祸患不可测，不但人嗔且为鬼。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8440, '未', '天耗地耗，耗我金玉。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8441, '未', '萤火之光，暗室辉明。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8442, '未', '大地恩光照，黄河日渐清。', '[9]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8443, '未', '少时多疾，至此莫狐。', '[3, 4]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8444, '未', '粉黛一湾新月瘦，园林化放老生春。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8445, '未', '韶光明媚人，人在锦丛中。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8446, '未', '可把阴功祈善保，怨字无心一在头。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8447, '未', '数尽年止。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8448, '未', '以武举而选千况，不幸之幸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8449, '未', '一字切忌日林，可允可求。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8450, '未', '虽然不是同行道，揽驰驱亦无伤。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8451, '未', '驰马路崎岖，立马对斜晖。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8452, '未', '北斗日中现，目前有忧疑。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8453, '未', '莫恨妻无缘，犯一狐神带。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8454, '未', '椿树已先折，萱花在后萎。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8455, '未', '红鸾加白虎，吉里又藏凶。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8456, '未', '八面秋风，愁人离恨。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8457, '未', '初生爱松柏，栽向雪霜中。', '[11, 12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8458, '未', '白虎现形，见者有惊。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8459, '未', '名列琥场，弓马入泮。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8460, '未', '运至时来，名利两得。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8461, '未', '闭门当相守，不管户外忧。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8462, '未', '无端风雨催春去，落尽枝头桃李花。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8463, '未', '流年有庆，灾星不侵。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8464, '未', '五岁归土，何须养母。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8465, '未', '梦魂千里去，室中离恨深。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8466, '未', '鹊噪南楼，喜事频来。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8467, '未', '未酬怀抱之恩，咏至蓼而兴感。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8468, '未', '孝服临门，忧及于父。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8469, '未', '左支右吾，优闷频多。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8470, '未', '秋风吹鹿鸣，天上降麒麟。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8471, '未', '莺老花残人远去，跨鹤乘云上九天。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8472, '未', '二耗相侵，不能稳守。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8473, '未', '分有前母，尔有继母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8474, '未', '气度深沉，不相推测。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8475, '未', '闻道东君尚未回，水流花谢雨相催。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8476, '未', '枫落吴江冷，金风阵阵寒。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8477, '未', '双双雁阵同飞舞，两个高翔一独鸣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8478, '未', '财帛破耗，流年不利。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8479, '未', '云锁婵娟秋寂寞，风吹桃李花凋残。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8480, '未', '玉人不齐眉，先吾十九年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8481, '未', '耗星入限，流年不利。', '[53]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8482, '未', '呼童寻行李，不必问东君。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8483, '未', '兄弟九人，数有七贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8484, '未', '灾晦绵绵，眉头未开展。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8485, '未', '财帛破耗，人情伤尽。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8486, '未', '椿庭有年，暴风吹折。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8487, '未', '癸未之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8488, '未', '术平身职赴，目下有来头。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8489, '未', '昏昏黑黑，鬼魅现形。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8490, '未', '龙德吉星照，灾毒不能侵。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8491, '未', '已丑之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8492, '未', '人事多乐，家事兴隆。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8493, '未', '锦帐兰芳，春花秋月。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8494, '未', '一夜金风吹，三更玉露寒。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8495, '未', '三九年来运已通，成家立业自兴隆。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8496, '未', '一子送终，挺秀之儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8497, '未', '力敌撑波艇，乘风得到瀛。', '[79, 80]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8498, '未', '豹变西有山，鹏博北临风。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8499, '未', '不惑三年，渐入佳景。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8500, '未', '武曲照命，三场捷报。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8501, '未', '穷与愁相对，正是难为难。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8502, '未', '暮夜有贼，预防不失。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8503, '未', '玉人自是不齐眉，早春三十定归期。', '[30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8504, '未', '数该生子。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8505, '未', '风吹椿枝折，三年泣血悲。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8506, '未', '寿九已尽，难享八旬。', '[79]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8507, '未', '扬花扑面，难免孝服。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8508, '未', '童未成人，一旦归西。', '[6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8509, '未', '生计顺相从，无计不亨通。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8510, '未', '楚山莫谓无椿树，潮水还防有鳄鱼。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8511, '未', '缘木求鱼，必不可得。', '[47]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8512, '未', '无是无非，优游禅室。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8513, '未', '初间一片月，若到中间倍十分。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8514, '未', '安居顺遂，酌酒高歌。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8515, '未', '借问一生身外事，遇羊之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8516, '未', '知君老至精神壮，宝剑光辉鬼胆寒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8517, '未', '案头列字，始登泮水荣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8518, '未', '陆地行舟，难于用力。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8519, '未', '阴袭王侯，祖宗之功力不浅。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8520, '未', '无物不从容，乐于管弦中。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8521, '未', '财帛破耗，如水之流。', '[63]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8522, '未', '芙蓉初出蕊，独自占秋江。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8523, '未', '灾晦缠绵，眉头交未开颜。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8524, '未', '思患预防，事乃克济。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8525, '未', '所思尽可得，有意皆从心。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8526, '未', '穿破二字，天数注定。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8527, '未', '寻常一夜窗前月，才有梅花便不同。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8528, '未', '亨夫之荣，安然快乐。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8529, '未', '金水之年，入泮方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8530, '未', '酷热已蒸，薰风又生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8531, '未', '流水落花，多少伤心事。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8532, '未', '辛未之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8533, '未', '功名事就，措手安居。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8534, '未', '一阵清风水面来，芙蓉香拂近楼台。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8535, '未', '前溪自有鱼舟引，不必迟凝自在行。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8536, '未', '一字切记日鸡，忘不得。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8537, '未', '此年琴弦断，出放知音人。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8538, '未', '心上事难言，逢人强为宽。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8539, '未', '一字切忌日猴，进不得。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8540, '未', '独子偏能兴家业。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8541, '未', '以痒而贡，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8542, '未', '可惜双亲太薄情，移抛离别向谁言。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8543, '未', '移居于灾，世事并绝。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8544, '未', '谨慎终无几，灾消祸亦消。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8545, '未', '以监而选州官，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8546, '未', '我生不辰，少年丧父。', '[5]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8547, '未', '扶持而得成功日，云开风转计从先。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8548, '未', '官至督抚，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8549, '未', '名登金榜。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8550, '未', '天恩未报，父入黄泉。', '[18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8551, '未', '四雁同飞，一只先失。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8552, '未', '绿杨烟锁拌黄昏，愁听枝头杜鹃啼。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8553, '未', '楚树吴花景色明，燕语莺歌日暖晴。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8554, '未', '终寿之数，寅年戌中追求。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8555, '未', '母赴瑶池，三年泣血。', '[26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8556, '未', '恍恍惚惚，不但人嗔且有鬼。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8557, '未', '彩云旭日出，秋水送潮来。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8558, '未', '前妻无结子，后妻一个儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8559, '未', '钦命典试。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8560, '未', '陇头几点桃花放，一道霞光次第来。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8561, '未', '破耗重重，如川之流。', '[57]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8562, '未', '春风鼓动能生物，春色宜人更恼人。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8563, '未', '鼓腹而歌，日暖风和。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8564, '未', '三人同行，一人升天。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8565, '未', '出家不了局，竟到要还俗。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8566, '未', '如临深渊，如履薄冰。', '[5, 6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8567, '未', '太阴行难度，土计掩其光。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8568, '未', '孝服相侵，优及于父。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8569, '未', '涉川无不利，得来运限通。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8570, '未', '可怜鸿翼，悲飞向红颜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8571, '未', '桃嫩不禁三月雨，莺鸣声叹五更寒。', '[5, 6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8572, '未', '耗星入财，不禁破耗。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8573, '未', '花正开时色正艳，连霄风雨又离枝。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8574, '未', '先难后易，运中如此。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8575, '未', '八卦之中晚运奇，不惟有寿便相依。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8576, '未', '名登金榜。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8577, '未', '有荣无辱，此为多福。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8578, '未', '喜事足嘉，光华满堂。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8579, '未', '浮云少害，不必思疑。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8580, '未', '云开山色丽，风静竹枝安。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8581, '未', '遇考拔前茅，必得膳俸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8582, '未', '禄勋星照，时到荣迁。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8583, '未', '年华康泰，事得称心。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8584, '未', '杨花扑面，三年泣血。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8585, '未', '出胎克父，莫大刑伤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8586, '未', '月缺花残，此年已倾。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8587, '未', '借问一生身外事，遇马之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8588, '未', '其人性坚，急能有功。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8589, '未', '喜气重来，家门迪吉。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8590, '未', '知命之年孝服来，老椿含笑入幽冥。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8591, '未', '花含晚露重，湿泪点胭脂。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8592, '未', '一明春尽花零落，欲渡清波欠便船。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8593, '未', '三九年来运已通，成家立业福兴隆。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8594, '未', '阴难还相及，则中且得时。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8595, '未', '多怨复多忌，运转人还喜。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8596, '未', '乡榜题名。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8597, '未', '人事乐意，家业兴隆。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8598, '未', '梧桐秋月色，好酒对知音。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8599, '未', '名利来不来，眉头锁不开。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8600, '未', '昏昏黑黑，鬼魅现形。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8601, '未', '春令正好游，一朝风雨至。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8602, '未', '老来生子，人之大幸。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8603, '未', '几度成来几度败，几番变幻几番迁。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8604, '未', '夫妻正好快乐事，谁知竟被鼓盆歌。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8605, '未', '命有关杀过房，成业寿元长。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8606, '未', '晓光开霁色，云散月光明。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8607, '未', '山冈之路可相通，为今此处趁东风。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8608, '未', '严亲数尽，难留在堂。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8609, '未', '顺水行舟，又得顺风。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8610, '未', '幼年丧父，何当命赛。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8611, '未', '守经无灾咎，安常福自随。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8612, '未', '平地成天日，风云际会时。', '[20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8613, '未', '南柯梦入华胥国，又忆英雄笑语中。', '[89, 90]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8614, '未', '秋日丹成谢严谷，一朝引领向天行。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8615, '未', '流年有咎，嗨气相侵。', '[14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8616, '未', '半钵清泉云外客，一肩破讷寺中僧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8617, '未', '兄弟六人，先损其一。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8618, '未', '高楼幸有梯，俯视白云低。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8619, '未', '流年有气晦，鬼喷逼人来。', '[48, 49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8620, '未', '虽有扁鹊复生，乃为阴司所夺。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8621, '未', '莫叹当年不如意，喜逢时运称心怀。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8622, '未', '四九之年运正通，成家立业见兴隆。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8623, '未', '飞符命相照，浮灾意外来。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8624, '未', '几番忧心事未专，言公相侮晦还生。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8625, '未', '红鸾相照，咏叶关雎。', '[9, 10]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8626, '未', '进步宜有待，欲速反成灾。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8627, '未', '薰风微微起，轻动绣帘来。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8628, '未', '嗟予从来运失时，今朝新运正相宜。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8629, '未', '谁料半途分别去，恨无言语对银缸。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8630, '未', '日影落西，人不见归。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8631, '未', '钦命典试。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8632, '未', '金风忽报秋江好，一叶扁舟顺水流。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8633, '未', '事机不密，反遭晦气。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8634, '未', '进士及第。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8635, '未', '云收雨晴，春光暗度。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8636, '未', '魂还流水去，魄逐落花飞。', '[43]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8637, '未', '天为蓬鸟屋，云外作锦屏。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8638, '未', '窗外乘流风未便，青灯黄卷且勤劳。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8639, '未', '欲识生人数，前三与后四。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8640, '未', '风前之烛，光摇不定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8641, '未', '遇尽前滩与后滩，险处不为难。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8642, '未', '梦入黄泉，一场空游。', '[44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8643, '未', '花开正当艳，风雨暴相残。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8644, '未', '再任把总，荣任之职。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8645, '未', '兄弟十人，数有七贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8646, '未', '天地常存，年华始尽。', '[87]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8647, '未', '萱花经霜萎，风雨又相催。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8648, '未', '绣帷结鸳鸯，花开花落鸟长栖。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8649, '未', '武曲照命，三场捷报。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8650, '未', '寿短似花，福薄如纸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8651, '未', '终日苦奔驰，劳劳碌碌几时休。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8652, '未', '修德避难，不可行险以求。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8653, '未', '见险思退，渐回且喜。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8654, '未', '年逢五七，寿如斯已。', '[35]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8655, '未', '此时老翁得道日，南柯一梦问归程。', '[91]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8656, '未', '命照丧门，萱花已落。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8657, '未', '祸患不可测，不但人嗔且有鬼。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8658, '未', '此刻生人，死而名长在。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8659, '未', '萱花已落，三年泣血。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8660, '未', '雨涨长江，波涛万顷。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8661, '未', '先女后男，数定不差。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8662, '未', '年当方壮，不幸父亡。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8663, '未', '中年虚耗，晚景兴隆。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8664, '未', '祥光相照，喜事重重。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8665, '未', '好事推人，犹如马足。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8666, '未', '迷失桃源路，还从洞里寻。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8667, '未', '时逢运长，福自日昌。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8668, '未', '土年父命先终，方合此刻。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8669, '未', '一妻五妾，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8670, '未', '当宴鹿鸣，天赐麟儿。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8671, '未', '好修清净福，莫入风尘中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8672, '未', '数定其人职，队中-一总官。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8673, '未', '一妻又一妻，两度佳人时。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8674, '未', '姊妹五人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8675, '未', '志气又昂昂，直上可施为。', '[37]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8676, '未', '人逢美景地，花开宜春时。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8677, '未', '见危终获福，得遇险中生。', '[75, 76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8678, '未', '六六之年运已奇，成家立业福自依。', '[36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8679, '未', '名进宫墙，弓马入泮。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8680, '未', '画龙点晴，破壁飞腾。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8681, '未', '文昌附落长江水，槛外长江空自流。', '[74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8682, '未', '妻生一子，妾产二儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8683, '未', '夫妻同庚，姻缘前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8684, '未', '同群五雁，四只先飞。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8685, '未', '此人皆在牢笼内，不成商贾不成儒。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8686, '未', '人逢美景地，犹如花遇春。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8687, '未', '可限灾星不可逃，犹如阴阳度祸。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8688, '未', '福享安然，禅门清净。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8689, '未', '分有前母，我生后母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8690, '未', '虎笑崖前威势大，运逢驿马路相逢。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8691, '未', '本是清净无尘日，悠然平地起风波。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8692, '未', '帝宠星辰近，天恩雨露深。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8693, '未', '夫妻同庚，前生注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8694, '未', '欲东欲西，心中未定。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8695, '未', '运转洪钧去复来，挽回入事笑颜天。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8696, '未', '鹿鸣得宴，无望琼瑶。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8697, '未', '吉自天来，无心之处得逢财。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8698, '未', '阴功积大官，星显富荣身。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8699, '未', '房考之年。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8700, '未', '恍恍惚惚，不但人嗔且有鬼。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8701, '未', '一妻不得谐老，再娶方可齐眉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8702, '未', '良宵有酒须当醉，得意吹箫便月明。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8703, '未', '事机宜谨慎，无是亦无非。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8704, '未', '兄弟八人，乐奏几般音。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8705, '未', '天嘉星临，内外安然。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8706, '未', '戊戌之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8707, '未', '财帛散尽不复来，老年眉头锁不开。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8708, '未', '生父养父，命中注定。', '[13]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8709, '未', '伯爵荫祖宗，培植根基深。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8710, '未', '几番人事多更变，行尽艰辛路不通。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8711, '未', '椿树有年，狂风吹折。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8712, '未', '鸿雁成群，非一母所生。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8713, '未', '自看天心，只只天涯近。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8714, '未', '名进贤关，弓马入泮。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8715, '未', '知君本是良家子，却食朝廷一分粮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8716, '未', '夫妻同年，姻缘注定。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8717, '未', '梁木已残，不能整顿。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8718, '未', '紫微星照，爵禄高荣。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8719, '未', '壮年劳劳碌碌，老来福禄悠悠。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8720, '未', '身虽欲坠，却有仁心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8721, '未', '身在营伍，却有仁心。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8722, '未', '大鹏有健翼，一展便冲天。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8723, '未', '闺门深恨桃花飞，不管人间岁月移。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8724, '未', '金风吹萧讽，西南喜气多。', '[69]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8725, '未', '幼年而亡，徒增长者悲。', '[89]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8726, '未', '渊明解印身归隐，酌酒黄花达性情。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8727, '未', '哀哉风木恨，椿树受灾先。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8728, '未', '昔受皇恩，今朝出贡期。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8729, '未', '无晴无阴，愁怀莫释。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8730, '未', '慈母先去尘，镜中留影深。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8731, '未', '夫妻同庚，百世姻缘。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8732, '未', '喜事足嘉，光华瑞气。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8733, '未', '处高不伤，虽危不亡。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8734, '未', '太阳东升，阴气消除。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8735, '未', '莫贪意外财，谨守匣中器。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8736, '未', '伤心肠欲断，泪血滴胭脂。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8737, '未', '一夫不得谐，二夫得齐眉。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8738, '未', '中运恢复，强宗自立。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8739, '未', '一字切忌日虎，遇不得。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8740, '未', '路悠悠而怀转，人处处而逢迎。', '[55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8741, '未', '经之营之，勤俭度日。', '[21]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8742, '未', '钻木取火，大有所望。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8743, '未', '龙嘘气而直，五色云呈祥。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8744, '未', '争讼不已，更相牵缠。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8745, '未', '晦气相侵，流年不宁。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8746, '未', '名登金榜。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8747, '未', '前妻无子，后妻两儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8748, '未', '名挂营中，常行善事。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8749, '未', '火奎其气时，哀痛不如泪。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8750, '未', '怀水成海，乾坤浩大。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8751, '未', '入赘成婚，姻缘前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8752, '未', '调鼎事复新，指引有渔郎。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8753, '未', '行人路崎岖，享福又过人。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8754, '未', '黄莺出谷，迁于乔木。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8755, '未', '已兴钱已加增，贵人指引倍亨通。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8756, '未', '喜鹊营巢久，鸠鸣又变迁。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8757, '未', '数该生子。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8758, '未', '命照武曲，三场捷报。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8759, '未', '其人寿天，一梦人华胥。', '[16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8760, '未', '位值青龙，喜事从容。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8761, '未', '非文非武，营伍相公。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8762, '未', '莫报东风急，好花向春开。', '[27, 28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8763, '未', '嫩草霜欺，其色早萎。', '[8]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8764, '未', '庚戌之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8765, '未', '恶星相照，高堂寿终。', '[76]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8766, '未', '浔阳江上，道有来潮。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8767, '未', '青云得路，梦叶熊黑。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8768, '未', '恍恍惚惚，不得人嗔且有鬼。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8769, '未', '分有前母，生我后母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8770, '未', '千山景秀，背翠夺目。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8771, '未', '世事犹如春梦，人生恰似浮云。', '[58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8772, '未', '主中馈频繁，君子多助贤。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8773, '未', '身虽营伍队，能文不能武。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8774, '未', '虽无金刀割，忽使琴弦断。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8775, '未', '年逢十二，数定命伤。', '[12]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8776, '未', '夫星虽旺身，生来暗晦作偏房。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8777, '未', '倚养舅母，赖以成人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8778, '未', '十里片帆轻，波平浪不惊。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8779, '未', '光景好中年，春光茂光华。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8780, '未', '祸患不可测，不但人嗔且有鬼。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8781, '未', '晴天雷震，君家有恐。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8782, '未', '人在紫微深处立，笙歌韶乐在其中。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8783, '未', '钦命典试。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8784, '未', '春深桃李，到处成蹊。', '[11]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8785, '未', '名登金榜。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8786, '未', '月色在中天，画堂展峥嵘。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8787, '未', '花开未久春光尽，可异枝头一旦倾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8788, '未', '劝君早作山林计，近水楼台总是空。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8789, '未', '却忌花前酒，休贪不义财。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8790, '未', '画堂佳气，门庭生晖。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8791, '未', '儿孙满堂，老景安康。', '[77, 78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8792, '未', '姊妹五人，二人先损。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8793, '未', '日出不堪云淡淡，花开只怕雨滂沱。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8794, '未', '数有不幸，当死非命。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8795, '未', '数有偏枯，身有带疾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8796, '未', '春酒今朝热，嬉嬉醉北邻。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8797, '未', '祸患不中测，不但人嗔且有鬼。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8798, '未', '悠悠福长，家门吉祥。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8799, '未', '早岁发财如涌水，中年得利似雷鸣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8800, '未', '七七之年孝服临，萱花已落椿枝淋。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8801, '未', '千军之权，万人之册。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8802, '未', '尝尽艰辛苦，滋味转甘甜。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8803, '未', '寒鸦枯木日沉西，回首青山事与非。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8804, '未', '岁暮平稳，一生安康。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8805, '未', '意气所至，无忧无虑。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8806, '未', '勤恳发财，处地施为。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8807, '未', '己未之年，名登金榜。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8808, '未', '兄弟四人，数有二贵。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8809, '未', '将星照命，弓马入泮。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8810, '未', '明伦之任，如虎添翼。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8811, '未', '三复而问，虑事不济。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8812, '未', '涧锁芳亭月，门迎细柳春。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8813, '未', '数中注定女艰辛，惟生二女在堂前。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8814, '未', '一朝天赐佳景到，功显寻常贯万邦。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8815, '未', '借问一生身外事，遇蛇之年是归期。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8816, '未', '名进宫墙，弓马入泮。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8817, '未', '赵赵武夫，公侯干城。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8818, '未', '乡科及第。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8819, '未', '喜气重来，家门吉祥。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8820, '未', '演武及第。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8821, '未', '母赴瑶池，三年泣血。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8822, '未', '三雁高飞，一只在后。', '[9000]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8823, '未', '主持军器，家食天禄。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8824, '未', '以监而选府判，数由前定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8825, '未', '绿林花中出艳色，白莲池上蕊生香。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8826, '未', '花卉减却春，春尽愁难尽。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8827, '未', '前妻无子，后妻一儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8828, '未', '易得易失，得难失难。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8829, '未', '整顿自然，不负良辰美景。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8830, '未', '龟鹤之期，高寿之年。', '[71]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8831, '未', '君子思古，屡辞小人。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8832, '未', '正妻本无子，偏房许生儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8833, '未', '风中之烛，光摇不定。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8834, '未', '问文无益，问武有余。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8835, '未', '身虽无子，赖有继孙。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8836, '未', '保邦保民，万国安宁。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8837, '未', '耗星相照，钱财难守。', '[59]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8838, '未', '操调中舟当，风波之鼎沸。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8839, '未', '命有关煞，一周而亡。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8840, '未', '武曲照命，弓马入泮。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8841, '未', '耗星照命，其年破耗。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8842, '未', '南极吉星照，其年瑞气多。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8843, '未', '命带孤寡宿，实恐无妻日。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8844, '未', '姊妹四人，前缘注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8845, '未', '问晴求雨，心腹羲皇。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8846, '未', '以监而纳中书，出入荣显。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8847, '未', '喜事逢泰安，乐日渐渐长。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8848, '未', '任君学尽千般艺，不离行伍一兵丁。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8849, '未', '林木春将近，芳菲景色新。', '[25, 26]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8850, '未', '生来未满旬，徒增父母悲。', '[9]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8851, '未', '阳关一曲断肠声，草木青山别故人。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8852, '未', '武场合式入泮。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8853, '未', '呦呦鹿鸣，天赐麟儿。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8854, '未', '黄菊绽东篱，秋色胜春光。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8855, '未', '建国安邦比牧侯，救民畜众乐忘忧。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8856, '未', '暗箭飞来，当防险处。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8857, '未', '常鼓其腹，歌乐太平。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8858, '未', '财帛勃发，涌泉而至。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8859, '未', '丽日正芳菲，春风吹柳丝。', '[17, 18]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8860, '未', '狂风叶难长，波浪孤舟橹不宁。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8861, '未', '晦气相侵，流年不利。', '[38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8862, '未', '高忧北窗下，悠林自得乐。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8863, '未', '阵伍中姓名不扬。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8864, '未', '朝霞映画堂，彩色龙凤飞。', '[61, 62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8865, '未', '金风萧杀不可当，空中萱花别故乡。', '[27]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8866, '未', '科甲及第。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8867, '未', '拮据不求，克享其子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8868, '未', '一树名花今既谢，从来无子结枝头。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8869, '未', '林木春将近，焕然景色新。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8870, '未', '安然获福，俾尔渐昌。', '[13, 14]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8871, '未', '此刻生人，死于木火年方合。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8872, '未', '幼年承继数，该处双亲人。', '[3]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8873, '未', '前途有推呼，惊防一点无。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8874, '未', '此日虽憔翠，当年有吉星。', '[78]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8875, '未', '花移春苑娇娆好，全赖栽培雨露深。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8876, '未', '莫道浮云无骤雨，须防尺水起波涛。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8877, '未', '风前之烛，危而难免。', '[67, 68]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8878, '未', '竹松鼓劲日，秋色正春容。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8879, '未', '水涨长江两岸平，孤舟自在皆前行。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8880, '未', '乡试中式。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8881, '未', '孝子至此之称，不亚斑烂之乐。', '[73]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8882, '未', '寿少一春，一命归天。', '[31]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8883, '未', '秋风桂子花开晚，海棠蟠桃结子迟。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8884, '未', '其年虽好，难免啾唧。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8885, '未', '一片白云迷户内，孝服相催泪两行。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8886, '未', '一泓清水映满堂，春色光明照乾坤。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8887, '未', '恍恍惚，不但人嗔且有鬼。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8888, '未', '瑞气祥光珠翠现，轻风吹动绮罗香。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8889, '未', '名登黄甲。', '[24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8890, '未', '务本营生理，一世便无忧。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8891, '未', '病符相照，浮灾意外。', '[31, 32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8892, '未', '凿井得泉，其水汪然。', '[43, 44]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8893, '未', '许多烦恼许多忧，变幻兴亡事事愁。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8894, '未', '严亲数尽，三年泣血。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8895, '未', '雨沾春色园林茂，日遍秋天宇宙清。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8896, '未', '子息虽有生，难育寿天年。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8897, '未', '移花接木，运未得舒。', '[32]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8898, '未', '命照武曲，殿试中式。', '[54, 55]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8899, '未', '天命加六数，大限黄泉人。', '[56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8900, '未', '演武及第。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8901, '未', '耗星照命，其年破耗。', '[61]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8902, '未', '云收雨散，日月光明。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8903, '未', '闲把酒怀消日月，名利无关乐意浓。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8904, '未', '操持器量，畏首畏尾。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8905, '未', '老年丧父，三年泣血亦英雄。', '[75]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8906, '未', '自叹夫君先去世，空余银烛伴黄昏。', '[49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8907, '未', '断弦之忧，是年之咎。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8908, '未', '毒亡身，妻该乐死。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8909, '未', '此年有耗星，只恐破财帛。', '[62]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8910, '未', '琴瑟无音，皆因弦断。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8911, '未', '病符相照，浮灾意外来。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8912, '未', '静中心地泰，喜色上眉头。', '[48, 49]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8913, '未', '母赴瑶池，三年泣血。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8914, '未', '承异姓祀，缔百年好。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8915, '未', '玉轮光皎洁，景色焕新艳。', '[35, 36]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8916, '未', '暗中措索处，特见一天星。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8917, '未', '红鸾相照。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8918, '未', '早淹暮安然，中间别有好花香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8919, '未', '以财发身日监。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8920, '未', '灾晦缠身，流年不利。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8921, '未', '寿至于此，一命归天。', '[93, 94]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8922, '未', '天不绝人后，临终却有娠。', '[79]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8923, '未', '财帛不谨，是后有祸。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8924, '未', '拨云见青天，今年胜去年。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8925, '未', '华堂八旬零，灾晦又相缠。', '[81, 82]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8926, '未', '终身监生，亦可见矣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8927, '未', '乡榜及第。', '[25]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8928, '未', '送老以女为儿。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8929, '未', '少年多灾，忧常不足。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8930, '未', '日是辰斗现，光暗各分明。', '[17]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8931, '未', '年满五旬，堂上萱花萎。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8932, '未', '老年生子。', '[57, 58]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8933, '未', '中秋望月，光圆千里。', '[41, 42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8934, '未', '便把阴功修福寿，栽培不至老枯松。', '[71, 72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8935, '未', '房考之年。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8936, '未', '雨滋芳草润，转眼绿姜姜。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8937, '未', '琴瑟弦又断，必须更换韵方和。', '[22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8938, '未', '承祖居而广大，不止守成。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8939, '未', '破耗财帛，人财两空。', '[64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8940, '未', '贵人点头，其利可求。', '[37, 38]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8941, '未', '所得惟中正，安然不须忧。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8942, '未', '堂上萱草落，三年泣血悲。', '[33]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8943, '未', '老年益壮，探花玩月醉长流。', '[55, 56]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8944, '未', '数该生子。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8945, '未', '太阳相照，人物光华。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8946, '未', '好花不常嫌春冷，皓月关门不怕寒。', '[5, 6]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8947, '未', '卜云其吉，终焉允藏。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8948, '未', '数该生子。', '[39, 40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8949, '未', '九岁丧父，刑莫大焉。', '[9]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8950, '未', '过险方为福，逢吉自可升。', '[29, 30]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8951, '未', '姊妹六人，同父不同母。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8952, '未', '莫嫌早运晦，须待水年荣。', '[9, 10]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8953, '未', '胜地不常，盛难再。', '[15, 16]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8954, '未', '女命操持，丈夫之度。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8955, '未', '不名不利，时运未至。', '[19, 20]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8956, '未', '中秋云掩月，黄昏难辨时。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8957, '未', '母赴瑶池，三年泣血。', '[28]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8958, '未', '官讼勾连，是非难免。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8959, '未', '命带文星，天招秀士作夫人。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8960, '未', '已喜鹿鸣宴，又美产麒麟。', '[59, 60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8961, '未', '三军队内我堪羡，轰轰烈烈迥出群。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8962, '未', '数注寒窗名未成，不如市上利盈盈。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8963, '未', '莫信时运好，须防有灾耗。', '[73, 74]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8964, '未', '造物多福，贵人妻宣。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8965, '未', '好意催人，图谋事成。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8966, '未', '波静浪平，扁舟稳渡。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8967, '未', '终日福无疑，安常福自随。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8968, '未', '莫道老景无限好，好似黄花晚节香。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8969, '未', '云雨浓浓，运至时通。', '[21, 22]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8970, '未', '朱颜易老，亦犹桃木。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8971, '未', '好运恰相逢，福禄处处通。', '[3738]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8972, '未', '游子归乡，浪子回头。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8973, '未', '大利北方。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8974, '未', '临事慷慨，喜气融和。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8975, '未', '玉树琼树方得荣，忽被狂风吹折根。', '[53, 54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8976, '未', '太阳照耀，人物光华。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8977, '未', '轻舟将近浪，一喜又一忧。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8978, '未', '片帆遇逆流，急舟则蹉跎。', '[48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8979, '未', '数该生子。', '[42]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8980, '未', '老椿先作游仙客，萱草桃花在后归。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8981, '未', '五雁同飞，一只先入罗网。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8982, '未', '生子之年。', '[54]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8983, '未', '一束名花今既谢，从来无子结枝头。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8984, '未', '命犯孤刑，姻缘不宜早配。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8985, '未', '凶神前后扰，吉神拥扶持。', '[33, 34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8986, '未', '兴尽悲来识，盈虚之有数。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8987, '未', '此时称孤子，人生一谦事。', '[72]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8988, '未', '道途皆坦平，步动履无忧。', '[60]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8989, '未', '朔望之月，其光渐减。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8990, '未', '喜之又不喜，日月有盈亏。', '[23]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8991, '未', '元亨利贞，大有所获。', '[45, 46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8992, '未', '此年无灾，略见平安。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (8993, '未', '天喜吉来临，天灾又无难。', '[15, 16]');
