INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12972, '亥', '行藏集福，坤入之幸。', '[39]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12973, '亥', '亲疏不分，痛苦乱伦。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12974, '亥', '进徒之喜。', '[47, 48]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12975, '亥', '与弟有染，数中注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12976, '亥', '重嫁已亥夫，方免刑夫。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12977, '亥', '老景得安康，不料中馈亡。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12978, '亥', '童运未坚，寒热多沾。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12979, '亥', '夫死之年，老来之悲。', '[50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12980, '亥', '命中无儿，不必强求子。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12981, '亥', '妻死之年，人生不幸。', '[45]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12982, '亥', '家室安泰，其乐融融。', '[40]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12983, '亥', '独木桥头休跨马，千层浪里莫行舟。', '[23, 24]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12984, '亥', '进徒之喜。', '[49, 50]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12985, '亥', '舟中重重险，扬子江头苦叫天。', '[34]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12986, '亥', '再配辛亥夫，数中注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12987, '亥', '信是栽培阴鹭好，雨滋花萼得荣华。', '[69, 70]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12988, '亥', '苏小妹前休纵酒，谢公城内莫内游。', '[83, 84]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12989, '亥', '夫死之年，人生不幸。', '[51]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12990, '亥', '命中无女，数中注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12991, '亥', '妻死之年，人生不幸。', '[46]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12992, '亥', '享平安福，乐大有年。', '[41]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12993, '亥', '一周二岁生荆棘，西风吹动子猷舟。', '[1]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12994, '亥', '进徒之喜。', '[51, 52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12995, '亥', '花开正苑香犹扑，笋长名园苗更长。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12996, '亥', '再嫁癸亥夫，姻缘注定。', NULL);
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12997, '亥', '克己从人防得失，安心谨慎获行藏。', '[65, 66]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12998, '亥', '运交胜从前，积玉堆金广置田。', '[63, 64]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (12999, '亥', '夫死之年，人生不幸。', '[52]');
INSERT INTO tiao_wen ("id", "set_name", "content1", "age_set1_json") VALUES (13000, '亥', '万象更新，周而复始。', NULL);
